head.b:skin:
/* ==========================================================
   SAMI — PRODUCT UI SYSTEM
   Purpose: a clean live-TV product shell over the existing
   Blogger/Firebase/HLS application logic.
   ========================================================== */

:root{
  color-scheme:dark;
  --bg:#071016;
  --bg-elev:#0b171f;
  --surface:#0d1b24;
  --surface-2:#11232d;
  --surface-3:#17303b;
  --line:#1b333e;
  --line-strong:#294550;
  --text:#f2f7f8;
  --text-2:#b8c7cc;
  --text-3:#7f949c;
  --accent:#23c9a8;
  --accent-2:#67e2c9;
  --accent-soft:rgba(35,201,168,.11);
  --accent-line:rgba(35,201,168,.44);
  --live:#ff4d68;
  --good:#33d18a;
  --warn:#f0b84f;
  --bad:#ff6f78;
  --star:#ffc857;
  --scrim:rgba(1,7,10,.72);
  --content:1480px;
  --pad:clamp(14px,2vw,30px);
  --radius-sm:10px;
  --radius-md:14px;
  --radius-lg:18px;
  --radius-xl:24px;
  --pill:999px;
  --shadow-1:0 12px 32px rgba(0,0,0,.22);
  --shadow-2:0 20px 50px rgba(0,0,0,.28);
  --ease:cubic-bezier(.2,.75,.2,1);
  /* compatibility aliases for retained AI/comment/runtime styles */
  --bg-2:var(--bg-elev);
  --accent-3:#46b8ff;
  --accent-ring:rgba(35,201,168,.16);
  --btn-a:var(--accent);
  --btn-b:var(--accent);
  --on-accent:#062019;
  --btn-shadow:rgba(35,201,168,.14);
  --btn-shadow-hover:rgba(35,201,168,.20);
  --card-bg:var(--surface);
  --hi:rgba(255,255,255,.04);
  --shadow:var(--shadow-2);
  --shadow-soft:var(--shadow-1);
}

[data-theme='light']{
  color-scheme:light;
  --bg:#f3f7f8;
  --bg-elev:#ffffff;
  --surface:#ffffff;
  --surface-2:#f0f6f7;
  --surface-3:#e6f0f2;
  --line:#dbe7e9;
  --line-strong:#c2d4d8;
  --text:#10222a;
  --text-2:#51676e;
  --text-3:#768b92;
  --accent:#087f70;
  --accent-2:#0f9f8a;
  --accent-soft:rgba(8,127,112,.10);
  --accent-line:rgba(8,127,112,.36);
  --live:#d91f45;
  --good:#087f55;
  --warn:#a96b06;
  --bad:#c83a45;
  --star:#b77700;
  --scrim:rgba(13,30,37,.52);
  --shadow-1:0 10px 28px rgba(28,63,71,.10);
  --shadow-2:0 18px 44px rgba(28,63,71,.14);
  --bg-2:var(--bg-elev);
  --accent-3:#0875b5;
  --accent-ring:rgba(8,127,112,.14);
  --btn-a:var(--accent);
  --btn-b:var(--accent);
  --on-accent:#ffffff;
  --btn-shadow:rgba(8,127,112,.14);
  --btn-shadow-hover:rgba(8,127,112,.20);
  --card-bg:var(--surface);
  --hi:rgba(255,255,255,.72);
  --shadow:var(--shadow-2);
  --shadow-soft:var(--shadow-1);
}

*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
html{
  scroll-behavior:smooth;
  scroll-padding-top:92px;
  -webkit-text-size-adjust:100%;
  text-size-adjust:100%;
}
body{
  min-height:100vh;
  background:var(--bg);
  color:var(--text);
  font-family:'Cairo',system-ui,sans-serif;
  line-height:1.6;
  overflow-x:hidden;
}
body::before{display:none}
a{color:inherit;text-decoration:none}
button,input{font:inherit}
button{border:0;background:none;color:inherit;cursor:pointer}
button,[role='button'],a{touch-action:manipulation}
img{display:block;max-width:100%}
svg{display:block}
:focus-visible{
  outline:3px solid var(--accent-2);
  outline-offset:3px;
}
::selection{background:var(--accent);color:#00130f}

/* Preserve Blogger widgets as runtime dependencies while keeping them out of the app UI. */
#blogger-hidden-widgets{display:none!important}
#statsSource{
  position:absolute!important;
  width:1px!important;
  height:1px!important;
  overflow:hidden!important;
  clip:rect(0,0,0,0)!important;
  white-space:nowrap!important;
  border:0!important;
  padding:0!important;
  margin:-1px!important;
  left:0;
  top:0;
}
.channel-grid-ad{grid-column:1/-1}

/* App shell */
.ambient{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.ambient::before,
.ambient::after{
  content:'';
  position:absolute;
  width:36vw;
  max-width:520px;
  aspect-ratio:1;
  border-radius:50%;
  opacity:.08;
  filter:blur(48px);
}
.ambient::before{top:-22vw;right:-12vw;background:var(--accent)}
.ambient::after{left:-18vw;bottom:4vw;background:#4b8cff}

.app-shell{
  position:relative;
  z-index:2;
  width:min(100%,var(--content));
  margin-inline:auto;
  padding:14px var(--pad) 64px;
}
.topbar{
  position:sticky;
  top:10px;
  z-index:90;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  align-items:center;
  gap:18px;
  min-height:64px;
  padding:8px 10px;
  background:var(--bg-elev);
  border:1px solid var(--line);
  border-radius:18px;
  box-shadow:var(--shadow-1);
}
.brand{
  display:inline-flex;
  align-items:center;
  gap:10px;
  min-width:0;
  padding:5px 7px;
  border-radius:12px;
}
.brand-mark{
  width:40px;
  height:40px;
  display:grid;
  place-items:center;
  flex:0 0 auto;
  border-radius:12px;
  background:var(--accent);
  color:#04201a;
  font-weight:900;
  font-size:17px;
}
.brand-copy{
  display:flex;
  flex-direction:column;
  min-width:0;
}
.brand-name{
  font-size:14px;
  line-height:1.1;
  font-weight:900;
  letter-spacing:.2px;
}
.brand-sub{
  margin-top:3px;
  color:var(--text-3);
  font-size:9px;
  font-weight:700;
  letter-spacing:.45px;
  text-transform:uppercase;
}
.primary-nav{
  min-width:0;
  display:flex;
  justify-content:center;
  align-items:center;
  gap:4px;
  overflow:auto;
  scrollbar-width:none;
}
.primary-nav::-webkit-scrollbar{display:none}
.nav-link{
  position:relative;
  padding:10px 13px;
  border-radius:10px;
  color:var(--text-2);
  font-size:12px;
  font-weight:800;
  white-space:nowrap;
  transition:background .2s var(--ease),color .2s var(--ease);
}
.nav-link:hover,
.nav-link.active{
  color:var(--text);
  background:var(--surface-2);
}
.nav-link.active::after{
  content:'';
  position:absolute;
  inset:auto 13px 3px;
  height:2px;
  border-radius:2px;
  background:var(--accent);
}
.top-actions{
  display:flex;
  gap:6px;
  align-items:center;
}
.icon-btn,
.action-btn{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border:1px solid var(--line);
  border-radius:11px;
  background:var(--surface);
  color:var(--text-2);
  transition:background .18s var(--ease),border-color .18s var(--ease),color .18s var(--ease),transform .18s var(--ease);
}
.icon-btn:hover,
.action-btn:hover{
  color:var(--text);
  border-color:var(--line-strong);
  background:var(--surface-2);
  transform:translateY(-1px);
}
.icon-btn:active,
.action-btn:active{transform:scale(.96)}
.icon-btn svg{width:18px;height:18px;fill:currentColor}
.search-trigger{
  width:auto;
  min-width:86px;
  padding-inline:12px;
  grid-auto-flow:column;
  gap:7px;
}
.search-trigger::after{
  content:'بحث';
  font-size:11px;
  font-weight:800;
}
[data-theme='light'] .search-trigger::after{color:var(--text)}

/* Main hierarchy */
#home{display:block}
.hero{
  display:grid;
  grid-template-columns:minmax(0,1.4fr) minmax(280px,.6fr);
  gap:16px;
  margin:22px 0 18px;
}
.hero-copy,
.hero-card{
  border:1px solid var(--line);
  border-radius:var(--radius-xl);
  background:var(--bg-elev);
  box-shadow:var(--shadow-1);
}
.hero-copy{
  position:relative;
  overflow:hidden;
  padding:clamp(24px,4vw,44px);
}
.hero-copy::after{
  content:'';
  position:absolute;
  width:300px;
  aspect-ratio:1;
  right:-120px;
  bottom:-180px;
  border-radius:50%;
  background:radial-gradient(circle,var(--accent-soft),transparent 67%);
  pointer-events:none;
}
.eyebrow{
  display:inline-flex;
  align-items:center;
  gap:8px;
  padding:7px 10px;
  border:1px solid var(--line);
  border-radius:var(--pill);
  color:var(--text-2);
  font-size:10px;
  font-weight:800;
}
.eyebrow i{
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--live);
  box-shadow:0 0 0 5px rgba(255,77,104,.10);
}
.hero h1{
  max-width:780px;
  margin:18px 0 12px;
  font-size:clamp(30px,5vw,58px);
  line-height:1.05;
  letter-spacing:-1.5px;
  text-wrap:balance;
}
.hero h1 span{
  color:var(--accent-2);
}
.hero p{
  max-width:720px;
  color:var(--text-2);
  font-size:14px;
  line-height:1.95;
}
.hero-actions{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  margin-top:22px;
}
.primary-btn,
.secondary-btn{
  min-height:44px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:10px 15px;
  border-radius:11px;
  font-size:12px;
  font-weight:900;
  transition:background .18s var(--ease),border-color .18s var(--ease),transform .18s var(--ease),box-shadow .18s var(--ease);
}
.primary-btn{
  background:var(--accent);
  color:#062019;
  border:1px solid var(--accent);
  box-shadow:0 10px 26px rgba(35,201,168,.14);
}
.primary-btn:hover{
  transform:translateY(-1px);
  box-shadow:0 14px 28px rgba(35,201,168,.19);
}
.secondary-btn{
  background:var(--surface);
  color:var(--text);
  border:1px solid var(--line-strong);
}
.secondary-btn:hover{
  transform:translateY(-1px);
  background:var(--surface-2);
}
.hero-card{
  padding:18px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  gap:10px;
}
.hero-card-label{
  color:var(--text-3);
  font-size:10px;
  font-weight:800;
  letter-spacing:.04em;
  text-transform:uppercase;
}
.hero-card h2{font-size:18px;line-height:1.4}
.hero-card p{
  color:var(--text-2);
  font-size:11px;
  line-height:1.9;
}
.hero-card .secondary-btn{margin-top:6px}
.hero-card .legacy-runtime-stats,
.hero-card .hero-signal,
.stat-grid{display:none!important}

/* Discovery/search */
.discovery-bar{
  position:sticky;
  top:86px;
  z-index:65;
  margin:0 0 18px;
  padding:10px;
  background:var(--bg-elev);
  border:1px solid var(--line);
  border-radius:16px;
  box-shadow:var(--shadow-1);
}
.discovery-head{
  display:flex;
  align-items:end;
  justify-content:space-between;
  gap:12px;
  padding:2px 4px 10px;
}
.discovery-title{
  font-size:15px;
  font-weight:900;
}
.discovery-sub{
  color:var(--text-3);
  font-size:10px;
}
.search-box{
  position:relative;
  display:flex;
  align-items:center;
  gap:8px;
}
.search-box input{
  width:100%;
  min-height:46px;
  padding:11px 13px 11px 44px;
  border:1px solid var(--line);
  border-radius:12px;
  outline:none;
  background:var(--surface);
  color:var(--text);
  font-size:15px;
}
.search-box input::placeholder{color:var(--text-3)}
.search-box input:focus{
  border-color:var(--accent-line);
  box-shadow:0 0 0 3px var(--accent-soft);
}
.search-icon{
  position:absolute;
  left:15px;
  width:18px;
  height:18px;
  fill:var(--text-3);
  pointer-events:none;
}
.search-meta{
  display:flex;
  align-items:center;
  gap:7px;
  overflow:auto;
  padding:9px 1px 1px;
  scrollbar-width:none;
}
.search-meta::-webkit-scrollbar{display:none}
.filter-chip{
  min-height:38px;
  display:inline-flex;
  align-items:center;
  gap:7px;
  padding:8px 11px;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--surface);
  color:var(--text-2);
  white-space:nowrap;
  font-size:11px;
  font-weight:800;
  transition:background .18s var(--ease),border-color .18s var(--ease),color .18s var(--ease);
}
.filter-chip:hover,
.filter-chip.active{
  color:var(--text);
  background:var(--accent-soft);
  border-color:var(--accent-line);
}
.filter-chip .count,
#gridLabel,
.result-badge,
.cc-count{display:none!important}
.search-results{
  display:none;
  position:absolute;
  inset-inline:10px;
  top:68px;
  max-height:55vh;
  overflow:auto;
  padding:8px;
  border:1px solid var(--line-strong);
  border-radius:14px;
  background:var(--bg-elev);
  box-shadow:var(--shadow-2);
}
.search-results.show{display:block}
.search-result{
  width:100%;
  display:flex;
  align-items:center;
  gap:10px;
  padding:10px;
  border-radius:10px;
  text-align:right;
}
.search-result:hover,
.search-result.active{background:var(--surface-2)}
.result-icon{
  width:36px;
  height:36px;
  flex:0 0 auto;
  display:grid;
  place-items:center;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--surface-2);
}
.result-main{min-width:0}
.result-name{
  font-size:12px;
  font-weight:900;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.result-sub{color:var(--text-3);font-size:10px}

/* Sections */
.section{margin-top:26px}
.section-header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin-bottom:12px;
}
.section-kicker{
  display:inline-flex;
  align-items:center;
  gap:7px;
  color:var(--accent-2);
  font-size:9px;
  font-weight:900;
  letter-spacing:.09em;
  text-transform:uppercase;
}
.section-kicker::before{
  content:'';
  width:16px;
  height:2px;
  border-radius:2px;
  background:var(--accent);
}
.section-title{
  margin-top:2px;
  color:var(--text);
  font-size:22px;
  line-height:1.35;
  font-weight:900;
  letter-spacing:-.35px;
}
.section-sub{color:var(--text-3);font-size:10px}
.section-header .head-actions{
  display:flex;
  align-items:center;
  gap:9px;
}
.back-btn{
  min-height:40px;
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:7px 11px;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--surface);
  color:var(--text-2);
  font-size:11px;
  font-weight:800;
}
.back-btn:hover{background:var(--surface-2);border-color:var(--line-strong)}
.back-btn[hidden]{display:none}

/* Rails added by the smart layer */
.history-track,
.featured-track{
  display:flex;
  gap:9px;
  overflow:auto;
  padding:1px 1px 2px;
  scrollbar-width:none;
}
.history-track::-webkit-scrollbar,
.featured-track::-webkit-scrollbar{display:none}
.history-item,
.featured-item{
  flex:0 0 220px;
  display:flex;
  align-items:center;
  gap:10px;
  padding:10px 12px;
  border:1px solid var(--line);
  border-radius:13px;
  background:var(--surface);
}
.history-item:hover,
.featured-item:hover{
  border-color:var(--line-strong);
  background:var(--surface-2);
}

/* Country / channel discovery */
.channel-grid{
  display:grid;
  grid-template-columns:repeat(6,minmax(0,1fr));
  gap:11px;
}
.channel-grid.country-grid{
  grid-template-columns:repeat(5,minmax(0,1fr));
}
.country-card{
  position:relative;
  min-height:112px;
  display:flex;
  flex-direction:column;
  justify-content:flex-end;
  gap:3px;
  padding:14px;
  overflow:hidden;
  border:1px solid var(--line);
  border-radius:16px;
  background:var(--surface);
  text-align:start;
  transition:transform .18s var(--ease),border-color .18s var(--ease),background .18s var(--ease);
}
.country-card::after{
  content:'';
  position:absolute;
  inset:auto 0 0;
  height:2px;
  background:var(--accent);
  opacity:0;
  transition:opacity .18s var(--ease);
}
.country-card:hover{
  transform:translateY(-2px);
  border-color:var(--accent-line);
  background:var(--surface-2);
}
.country-card:hover::after{opacity:1}
.country-card .cc-flag{
  position:absolute;
  top:10px;
  inset-inline-end:11px;
  font-size:47px;
  line-height:1;
  opacity:.92;
}
.country-card .cc-name{
  position:relative;
  z-index:1;
  font-size:14px;
  font-weight:900;
}
.channel-card{
  position:relative;
  min-width:0;
  display:grid;
  grid-template-columns:64px minmax(0,1fr);
  grid-template-rows:auto auto;
  gap:9px 10px;
  padding:9px;
  border:1px solid var(--line);
  border-radius:16px;
  background:var(--surface);
  overflow:hidden;
  transition:transform .18s var(--ease),border-color .18s var(--ease),background .18s var(--ease),box-shadow .18s var(--ease);
}
.channel-card:hover,
.channel-card:focus-within{
  transform:translateY(-2px);
  border-color:var(--accent-line);
  background:var(--surface-2);
  box-shadow:var(--shadow-1);
}
.channel-card:focus-visible{
  outline:3px solid var(--accent-2);
  outline-offset:2px;
}
.channel-card .thumb{
  grid-row:1/span 2;
  width:64px;
  aspect-ratio:1;
  position:relative;
  border:1px solid var(--line);
  border-radius:13px;
  overflow:hidden;
  background:var(--surface-2);
  display:grid;
  place-items:center;
}
.channel-card .thumb img{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:cover;
  background:var(--surface-2);
}
.channel-card .thumb-flag{
  font-size:30px;
  line-height:1;
}
.channel-card .thumb .live-tag{
  position:absolute;
  top:5px;
  inset-inline-start:5px;
  z-index:2;
}
.channel-card .card-info{min-width:0;align-self:end}
.channel-card .channel-name{
  color:var(--text);
  font-size:12px;
  line-height:1.45;
  font-weight:900;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.channel-card .channel-cat{
  margin-top:2px;
  color:var(--text-3);
  font-size:9px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.channel-card .card-bottom{
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:6px;
  grid-column:2;
}
.live-tag{
  display:inline-flex;
  align-items:center;
  gap:5px;
  min-height:24px;
  padding:3px 7px;
  border:1px solid rgba(255,77,104,.20);
  border-radius:7px;
  background:rgba(255,77,104,.08);
  color:#ffd6dc;
  font-size:8px;
  font-weight:900;
}
.live-tag i{
  width:6px;
  height:6px;
  border-radius:50%;
  background:var(--live);
}
.card-tools{
  display:flex;
  gap:4px;
}
.small-action{
  width:40px;
  height:40px;
  display:grid;
  place-items:center;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--surface);
  color:var(--text-2);
}
.small-action:hover{
  background:var(--surface-3);
  border-color:var(--line-strong);
}
.small-action svg{width:15px;height:15px;fill:currentColor}
.small-action.starred{
  color:var(--star);
  border-color:rgba(255,200,87,.34);
  background:rgba(255,200,87,.09);
}
.empty{
  grid-column:1/-1;
  padding:44px 18px;
  text-align:center;
  border:1px dashed var(--line);
  border-radius:16px;
  color:var(--text-3);
}
.empty strong{display:block;color:var(--text-2);font-size:13px}
.empty span{display:block;margin-top:5px;font-size:10px}
.skeleton{
  min-height:140px;
  border-radius:16px;
  border:1px solid var(--line);
  background:linear-gradient(90deg,var(--surface) 20%,var(--surface-2) 50%,var(--surface) 80%);
  background-size:200% 100%;
  animation:shimmer 1.25s linear infinite;
}
@keyframes shimmer{to{background-position:-200% 0}}

/* Watch workspace */
.watch-section{
  margin-top:34px;
  scroll-margin-top:94px;
}
.watch-section .section-header{
  align-items:flex-end;
  margin-bottom:14px;
  padding:0 2px;
}
.watch-grid{
  display:grid;
  grid-template-columns:minmax(0,1fr) 300px;
  gap:12px;
}
.player-card,
.player-side{
  min-width:0;
  border:1px solid var(--line);
  border-radius:18px;
  background:#03070a;
  box-shadow:var(--shadow-2);
  overflow:hidden;
}
.player-card{color-scheme:dark}
.player-frame{
  position:relative;
  aspect-ratio:16/9;
  background:#020507;
}
.player-frame video{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:contain;
  background:#020507;
}
.player-placeholder{
  position:absolute;
  inset:0;
  z-index:2;
  display:grid;
  place-items:center;
  padding:24px;
  background:radial-gradient(circle at 50% 38%,rgba(35,201,168,.12),transparent 45%),#020507;
  text-align:center;
}
.player-placeholder[hidden]{display:none}
.player-placeholder>div{max-width:360px}
.player-placeholder .p-icon{
  width:58px;
  height:58px;
  margin:0 auto 12px;
  display:grid;
  place-items:center;
  border:1px solid rgba(35,201,168,.26);
  border-radius:16px;
  background:rgba(35,201,168,.08);
  font-size:22px;
}
.player-placeholder h2{font-size:16px}
.player-placeholder p{
  margin-top:4px;
  color:rgba(242,247,248,.62);
  font-size:11px;
}
.player-overlay{
  position:absolute;
  inset:auto 0 0;
  z-index:4;
  display:flex;
  align-items:center;
  gap:6px;
  padding:46px 12px 12px;
  background:linear-gradient(transparent,rgba(0,0,0,.88));
}
.player-overlay.hide{opacity:0;pointer-events:none}
.ctrl{
  width:44px;
  height:44px;
  display:grid;
  place-items:center;
  flex:0 0 auto;
  border:1px solid rgba(255,255,255,.11);
  border-radius:10px;
  background:rgba(255,255,255,.07);
  color:#fff;
  transition:background .16s var(--ease),border-color .16s var(--ease),transform .16s var(--ease);
}
.ctrl:hover{background:rgba(35,201,168,.14);border-color:rgba(35,201,168,.38)}
.ctrl:active{transform:scale(.94)}
.ctrl svg{width:17px;height:17px;fill:currentColor}
.ctrl.spacer{margin-inline-start:auto}
.progress{
  position:absolute;
  left:12px;
  right:12px;
  bottom:57px;
  height:12px;
  display:flex;
  align-items:center;
  cursor:pointer;
}
.progress-track{
  width:100%;
  height:3px;
  overflow:hidden;
  border-radius:5px;
  background:rgba(255,255,255,.18);
}
.progress-fill{
  width:0;
  height:100%;
  border-radius:5px;
  background:var(--accent);
}
.player-side{
  padding:17px;
  display:flex;
  flex-direction:column;
  gap:12px;
  background:#09121a;
  color:#f2f7f8;
}
.watch-identity{
  display:flex;
  align-items:center;
  gap:11px;
}
.now-avatar,
.account-avatar-lg{
  width:48px;
  height:48px;
  flex:0 0 auto;
  display:grid;
  place-items:center;
  border:1px solid rgba(255,255,255,.10);
  border-radius:14px;
  background:#10212a center/cover no-repeat;
  color:#b9c8cc;
  font-weight:900;
}
.now-copy{min-width:0}
.side-title{
  color:rgba(242,247,248,.56);
  font-size:9px;
  font-weight:900;
  letter-spacing:.05em;
  text-transform:uppercase;
}
.now-title{
  margin-top:1px;
  font-size:19px;
  line-height:1.35;
  font-weight:900;
  overflow:hidden;
  text-overflow:ellipsis;
}
.now-meta{
  margin-top:2px;
  color:rgba(242,247,248,.56);
  font-size:10px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.signal-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding:10px 11px;
  border:1px solid rgba(255,255,255,.08);
  border-radius:11px;
  background:rgba(255,255,255,.03);
}
.signal-status{
  display:flex;
  align-items:center;
  gap:7px;
  font-size:10px;
  font-weight:800;
}
.signal-dot{
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--good);
  box-shadow:0 0 0 5px rgba(51,209,138,.10);
}
.signal-dot.warn{background:var(--warn);box-shadow:0 0 0 5px rgba(240,184,79,.10)}
.signal-dot.bad{background:var(--bad);box-shadow:0 0 0 5px rgba(255,111,120,.10)}
.signal-dot.live{animation:signalPulse 1.8s ease-in-out infinite}
@keyframes signalPulse{50%{box-shadow:0 0 0 8px rgba(51,209,138,.03)}}
.quality-list{
  display:flex;
  flex-direction:column;
  gap:6px;
  max-height:250px;
  overflow:auto;
}
.quality-btn{
  width:100%;
  min-height:42px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:8px 10px;
  border:1px solid rgba(255,255,255,.08);
  border-radius:10px;
  background:rgba(255,255,255,.03);
  text-align:right;
  font-size:10px;
  font-weight:900;
}
.quality-btn:hover,
.quality-btn.active{
  border-color:rgba(35,201,168,.36);
  background:rgba(35,201,168,.10);
}
.quality-btn .q-mark{color:rgba(242,247,248,.5);font-size:9px}

/* Utility / non-primary layers */
.utility-strip{display:none!important}
#presentation{display:none!important}
#gridLabel{visibility:hidden}
.legacy-runtime-stats{display:none!important}
.grid-sentinel{grid-column:1/-1;height:1px}
.about{
  margin-top:44px;
  content-visibility:auto;
  contain-intrinsic-size:auto 900px;
}
.about-card{
  padding:24px;
  border:1px solid var(--line);
  border-radius:18px;
  background:var(--surface);
}
.about-card h3{margin:18px 0 6px;font-size:16px}
.about-card>h3:first-child{margin-top:0}
.about-card p{
  color:var(--text-2);
  font-size:12px;
  line-height:2;
}
.acc{
  margin-top:10px;
  border:1px solid var(--line);
  border-radius:14px;
  background:var(--surface-2);
}
.acc>summary{
  list-style:none;
  cursor:pointer;
  padding:14px 16px;
  display:flex;
  align-items:center;
  gap:8px;
  font-size:13px;
  font-weight:900;
}
.acc>summary::-webkit-details-marker{display:none}
.acc>summary::before{content:'›';font-size:18px;color:var(--accent-2)}
.acc[open]>summary::before{content:'⌄'}
[dir='ltr'] .acc>summary::before{content:'‹'}
[dir='ltr'] .acc[open]>summary::before{content:'⌄'}
.acc-body{padding:0 16px 15px}
.acc-body ul{
  padding-inline-start:19px;
  color:var(--text-2);
  font-size:12px;
  line-height:2;
}
.acc-body a{color:var(--accent-2);text-decoration:underline}

.ad-slot{
  max-width:100%;
  min-height:76px;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:5px;
  margin:18px 0;
  padding:8px 10px;
  overflow:hidden;
  border:1px solid var(--line);
  border-radius:14px;
  background:var(--surface);
}
.ad-slot-label{
  color:var(--text-3);
  font-size:8px;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.ad-slot ins.adsbygoogle{width:100%}

.footer{
  margin-top:48px;
  padding:22px 0 8px;
  display:flex;
  justify-content:space-between;
  gap:18px;
  flex-wrap:wrap;
  border-top:1px solid var(--line);
  content-visibility:auto;
  contain-intrinsic-size:auto 140px;
}
.footer-main{
  color:var(--text-3);
  font-size:10px;
  line-height:2;
}
.footer-main b{color:var(--text-2)}
.footer-links{display:flex;gap:6px;flex-wrap:wrap}
.footer-link{
  min-height:38px;
  display:inline-flex;
  align-items:center;
  padding:7px 10px;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--surface);
  color:var(--text-2);
  font-size:9px;
}
.footer-link:hover{background:var(--surface-2);border-color:var(--line-strong)}

/* Toast and overlays */
.toast{
  position:fixed;
  left:50%;
  bottom:22px;
  z-index:300;
  max-width:calc(100vw - 28px);
  transform:translate(-50%,16px);
  opacity:0;
  pointer-events:none;
  padding:10px 13px;
  border:1px solid var(--line-strong);
  border-radius:11px;
  background:var(--bg-elev);
  box-shadow:var(--shadow-2);
  font-size:10px;
  font-weight:900;
  transition:opacity .2s var(--ease),transform .2s var(--ease);
}
.toast.show{opacity:1;transform:translate(-50%,0)}

.command-backdrop,
.modal-backdrop{
  position:fixed;
  inset:0;
  z-index:200;
  background:var(--scrim);
  opacity:0;
  pointer-events:none;
  transition:opacity .18s var(--ease);
}
.command-backdrop.show,
.modal-backdrop.show{
  opacity:1;
  pointer-events:auto;
}
.command-panel,
.modal-card{
  position:absolute;
  top:9vh;
  left:50%;
  width:min(720px,calc(100vw - 28px));
  transform:translateX(-50%) scale(.985);
  border:1px solid var(--line-strong);
  border-radius:18px;
  background:var(--bg-elev);
  box-shadow:var(--shadow-2);
  overflow:hidden;
  transition:transform .18s var(--ease);
}
.command-backdrop.show .command-panel,
.modal-backdrop.show .modal-card{transform:translateX(-50%) scale(1)}
.command-input{
  display:flex;
  align-items:center;
  gap:8px;
  padding:11px;
  border-bottom:1px solid var(--line);
}
.command-input input{
  flex:1;
  border:0;
  outline:0;
  background:transparent;
  color:var(--text);
  font-size:15px;
}
.command-body{max-height:52vh;overflow:auto;padding:7px}
.command-item{
  width:100%;
  display:flex;
  align-items:center;
  gap:9px;
  padding:11px;
  border-radius:10px;
  text-align:right;
}
.command-item:hover,
.command-item.active{background:var(--surface-2)}
.command-key{
  margin-inline-start:auto;
  color:var(--text-3);
  font-size:9px;
}
.modal-card{width:min(500px,calc(100vw - 28px));top:12vh;padding:18px}
.modal-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  margin-bottom:12px;
}
.modal-title{font-size:15px;font-weight:900}
.modal-text{color:var(--text-2);font-size:11px;line-height:1.9}
.modal-card .icon-btn{width:38px;height:38px}

/* Account */
.account-btn{position:relative}
.account-btn svg{width:19px;height:19px;fill:currentColor}
.account-btn.signed-in svg#accountIconGuest{display:none}
.account-avatar{
  width:24px;
  height:24px;
  border:1px solid var(--line-strong);
  border-radius:50%;
  background-size:cover;
  background-position:center;
}
.account-btn.signed-in .account-avatar{display:block}
.account-body{display:flex;flex-direction:column;gap:13px;text-align:center}
.account-lead{color:var(--text-2);font-size:12px;line-height:1.8}
.account-note{color:var(--text-3);font-size:10px;line-height:1.8}
.gsi-btn{
  width:100%;
  min-height:44px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:9px;
  padding:10px 14px;
  border:1px solid #d8dde0;
  border-radius:11px;
  background:#fff;
  color:#303438;
  font-size:13px;
  font-weight:800;
}
.gsi-btn:disabled{opacity:.58;cursor:wait}
.gsi-icon{width:18px;height:18px;flex:0 0 auto}
.gsi-icon svg{width:100%;height:100%}
.account-divider{display:flex;align-items:center;gap:9px;color:var(--text-3);font-size:10px}
.account-divider::before,
.account-divider::after{content:'';flex:1;height:1px;background:var(--line-strong)}
.email-auth-form{display:flex;flex-direction:column;gap:0}
.email-field{display:flex;flex-direction:column;gap:5px;margin-bottom:10px}
.email-field label{color:var(--text-2);font-size:11px;font-weight:800}
.email-auth-form input{
  width:100%;
  min-height:42px;
  padding:9px 12px;
  border:1px solid var(--line-strong);
  border-radius:10px;
  background:var(--surface);
  color:var(--text);
  outline:none;
  font-size:13px;
  direction:ltr;
  text-align:right;
}
.email-auth-form input:focus{
  border-color:var(--accent);
  box-shadow:0 0 0 3px var(--accent-soft);
}
.email-auth-error{display:none;color:var(--bad);font-size:10px;line-height:1.6;margin-bottom:5px}
.email-auth-error.visible{display:block}
.email-auth-submit{
  min-height:44px;
  margin-top:2px;
  padding:10px;
  border-radius:11px;
  background:var(--accent);
  color:#062019;
  font-size:12px;
  font-weight:900;
}
.email-auth-submit:disabled{opacity:.55;cursor:wait}
.email-auth-links{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-top:11px;
}
.link-btn{
  padding:2px 0;
  color:var(--text-3);
  font-size:10px;
  text-decoration:underline;
}
.link-btn:hover{color:var(--text)}
.account-profile-row{display:flex;align-items:center;gap:12px;text-align:right}
.account-profile-copy{min-width:0;display:flex;flex-direction:column;gap:2px}
.account-profile-copy strong{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.account-profile-copy small{color:var(--text-3);font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.account-sync-status{color:var(--text-3);font-size:10px;text-align:right}
.account-signout{
  min-height:42px;
  padding:9px;
  border:1px solid var(--line-strong);
  border-radius:10px;
  background:var(--surface);
  font-size:11px;
  font-weight:900;
}
.account-card{max-height:80vh;overflow-y:auto;overscroll-behavior:contain}
.signup-extra{display:none;flex-direction:column}
.avatar-pick{display:flex;align-items:center;gap:11px;margin-bottom:11px}
.avatar-pick-preview{
  width:58px;
  height:58px;
  flex:0 0 auto;
  display:grid;
  place-items:center;
  overflow:hidden;
  border:1px dashed var(--line-strong);
  border-radius:50%;
  background:var(--surface-2) center/cover no-repeat;
  color:var(--text-3);
  font-size:21px;
}
.avatar-pick-preview.has-img{border-style:solid}
.avatar-pick-copy{display:flex;flex-direction:column;gap:4px;text-align:right}
.avatar-pick-btn{
  align-self:flex-start;
  min-height:36px;
  padding:7px 11px;
  border:1px solid var(--line-strong);
  border-radius:9px;
  background:var(--surface);
  font-size:10px;
  font-weight:900;
}
.avatar-pick-hint{color:var(--text-3);font-size:9px}
.name-row{display:flex;gap:8px}
.name-row .email-field{flex:1;min-width:0}
.email-auth-form input[type=number]{direction:ltr}

/* Mobile navigation */
.mobile-nav{
  display:none;
  position:fixed;
  inset:auto 10px 10px;
  z-index:120;
  gap:4px;
  padding:6px;
  border:1px solid var(--line-strong);
  border-radius:16px;
  background:var(--bg-elev);
  box-shadow:var(--shadow-2);
}
.mobile-nav button{
  flex:1;
  min-height:48px;
  display:grid;
  place-items:center;
  gap:2px;
  padding:5px;
  border-radius:11px;
  color:var(--text-3);
  font-size:8px;
  font-weight:900;
}
.mobile-nav button.active,
.mobile-nav button:hover{
  color:var(--text);
  background:var(--surface-2);
}
.mobile-nav svg{width:17px;height:17px;fill:currentColor}

/* Smart/PWA/AI/Comments integration surfaces — restyled, not removed */
.v10-offline{
  position:fixed!important;
  left:50%!important;
  top:14px!important;
  z-index:310!important;
  width:min(560px,calc(100vw - 28px))!important;
  transform:translateX(-50%)!important;
  padding:9px 12px!important;
  border:1px solid var(--line-strong)!important;
  border-radius:10px!important;
  background:var(--bg-elev)!important;
  box-shadow:var(--shadow-2)!important;
  color:var(--text)!important;
  font-size:10px!important;
  text-align:center!important;
}
.v10-mini{
  border:1px solid var(--line-strong)!important;
  border-radius:14px!important;
  background:var(--bg-elev)!important;
  box-shadow:var(--shadow-2)!important;
}
.v10-mic,.v10-install{
  border:1px solid var(--line)!important;
  border-radius:10px!important;
  background:var(--surface)!important;
}
/* fix: channel name + sub-label were inline spans and rendered glued together */
.history-copy{display:flex!important;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;flex:1 1 auto;text-align:start}
.history-name{display:block;max-width:100%;font-weight:700;line-height:1.6;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:0!important}
.history-cat{display:block;max-width:100%;font-size:12px;line-height:1.6;color:var(--muted,#8fa3a8);letter-spacing:0!important}
.v10-sec{margin-top:24px!important}
.v10-tile{
  border:1px solid var(--line)!important;
  border-radius:13px!important;
  background:var(--surface)!important;
}
.ai-fab{
  width:52px!important;
  height:52px!important;
  border-radius:16px!important;
  background:var(--accent)!important;
  color:#062019!important;
  box-shadow:0 14px 30px rgba(35,201,168,.20)!important;
}
.ai-panel{
  width:min(420px,calc(100vw - 24px))!important;
  border:1px solid var(--line-strong)!important;
  border-radius:18px!important;
  background:var(--bg-elev)!important;
  box-shadow:var(--shadow-2)!important;
}
.ai-chip{
  border:1px solid var(--line)!important;
  border-radius:10px!important;
  background:var(--surface)!important;
}
.cm-section{
  border-top:1px solid var(--line);
}
.cm-section input,
.cm-section textarea{
  border:1px solid var(--line)!important;
  border-radius:10px!important;
  background:var(--surface)!important;
  color:var(--text)!important;
}

/* Watch focus state */
[data-watching='1'] .watch-section .player-card{
  border-color:var(--accent-line);
}
[data-watching='1'] .watch-section .section-title{color:var(--text)}

/* Responsive */
@media (min-width:1250px){
  .channel-grid{grid-template-columns:repeat(6,minmax(0,1fr))}
  .channel-grid.country-grid{grid-template-columns:repeat(5,minmax(0,1fr))}
}
@media (max-width:1249px){
  .channel-grid{grid-template-columns:repeat(5,minmax(0,1fr))}
  .channel-grid.country-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
}
@media (max-width:1050px){
  .topbar{grid-template-columns:auto 1fr auto}
  .primary-nav{justify-content:flex-start}
  .hero{grid-template-columns:1fr}
  .hero-card{min-height:0}
  .watch-grid{grid-template-columns:1fr}
  .channel-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
  .channel-grid.country-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
}
@media (max-width:780px){
  html{scroll-padding-top:82px}
  .app-shell{padding:10px 12px 104px}
  .topbar{
    top:6px;
    min-height:58px;
    grid-template-columns:auto 1fr auto;
    gap:8px;
    border-radius:15px;
  }
  .brand-mark{width:36px;height:36px;border-radius:10px}
  .brand-name{font-size:12px}
  .brand-sub{display:none}
  .primary-nav{display:none}
  .top-actions{gap:4px}
  .top-actions .icon-btn{
    width:38px;
    height:38px;
  }
  .search-trigger{min-width:38px;padding:0}
  .search-trigger::after{display:none}
  .hero{margin:16px 0 14px;gap:10px}
  .hero-copy{padding:22px;border-radius:20px}
  .hero h1{font-size:34px;letter-spacing:-.8px}
  .hero p{font-size:12px}
  .hero-card{padding:16px;border-radius:16px}
  .discovery-bar{top:72px;border-radius:14px}
  .discovery-head{padding-bottom:8px}
  .discovery-title{font-size:14px}
  .discovery-sub{font-size:9px}
  .section{margin-top:22px}
  .section-title{font-size:19px}
  .section-header{margin-bottom:10px}
  .channel-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .channel-grid.country-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .country-card{min-height:100px;padding:12px;border-radius:14px}
  .country-card .cc-flag{font-size:42px}
  .channel-card{grid-template-columns:56px minmax(0,1fr);padding:8px;border-radius:14px}
  .channel-card .thumb{width:56px;border-radius:11px}
  .channel-card .channel-name{font-size:11px}
  .channel-card .card-bottom{gap:5px}
  .small-action{width:40px;height:40px}
  .live-tag{font-size:7px}
  .watch-section{margin-top:28px}
  .watch-grid{gap:8px}
  .player-card,.player-side{border-radius:15px}
  .player-side{padding:13px}
  .player-placeholder{padding:18px}
  .player-overlay{padding:40px 9px 9px}
  .ctrl{width:40px;height:40px}
  .progress{left:9px;right:9px;bottom:52px}
  .mobile-nav{display:flex}
  .about-card{padding:18px}
  .footer{margin-top:36px}
}
@media (max-width:520px){
  .hero-card{display:none}
  .hero-copy{border-radius:18px}
  .hero h1{font-size:30px}
  .hero-actions .secondary-btn{flex:1}
  .hero-actions .primary-btn{flex:1}
  .search-box input{min-height:44px;font-size:16px}
  .section-title{font-size:18px}
  .section-sub{display:none}
  .section-header .head-actions{gap:6px}
  .watch-section .section-header{align-items:flex-start}
  .watch-section .section-title{font-size:19px}
  .watch-grid{grid-template-columns:1fr}
  .player-side{order:2}
  .quality-list{max-height:220px}
  .history-item,.featured-item{flex-basis:190px}
}
@media (max-width:370px){
  .app-shell{padding-inline:10px}
  .channel-grid,
  .channel-grid.country-grid{grid-template-columns:1fr}
  .top-actions .icon-btn{width:36px;height:36px}
  .hero h1{font-size:28px}
}
@media (min-width:1101px){
  .app-shell{padding-inline-end:var(--pad)}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{
    scroll-behavior:auto!important;
    animation-duration:.01ms!important;
    animation-iteration-count:1!important;
    transition-duration:.01ms!important;
  }
}


/* ===== Merge v15+v16: watch page + admin panel ===== */
#homeView[hidden],#watchView[hidden],#adminStats[hidden],#relatedSection[hidden]{display:none!important}
.watch-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:18px 0 6px}
.watch-bar .back-btn{display:inline-flex}
#watchFav[aria-pressed='true']{border-color:var(--star);color:var(--star)}
#watchFav[aria-pressed='true'] .fav-ico{color:var(--star)}
.watch-section{margin-top:10px}
.admin-panel{margin:0 0 18px;padding:14px;border:1px solid var(--accent-line);border-radius:var(--radius-xl);background:var(--bg-elev);box-shadow:var(--shadow-1)}
.admin-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}
.admin-badge{padding:4px 11px;border-radius:99px;background:var(--accent-soft);border:1px solid var(--accent-line);color:var(--accent-2);font-size:11px;font-weight:900}
.admin-sub{color:var(--text-3);font-size:11px}
.admin-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
.admin-grid .stat-card{min-width:0;padding:12px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--surface)}
.admin-grid .stat-label{display:flex;align-items:center;gap:6px;color:var(--text-3);font-size:11px;font-weight:800}
.admin-grid .stat-value{margin:6px 0 2px;color:var(--text);font-size:24px;font-weight:900;line-height:1.1;font-variant-numeric:tabular-nums}
.admin-grid .muted{color:var(--text-3);font-size:10px;line-height:1.6}
.admin-grid .stat-card[style]{grid-column:auto!important}
@media (max-width:900px){.admin-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:420px){.admin-grid .stat-value{font-size:20px}}



/* SAMI Live TV — refreshed visual layer. */
/* SAMI Live TV — refreshed visual layer.
   Intentionally uses the existing selectors and leaves all Blogger and app logic intact. */
:root {
  color-scheme: dark;
  --bg: #071018;
  --bg-2: #0b1722;
  --bg-elev: #0d1d29;
  --surface: #0d1b27;
  --text: #edf6fa;
  --text-2: #a8bbc8;
  --text-3: #7e94a3;
  --accent: #55d6c3;
  --accent-2: #a0f2df;
  --accent-soft: rgba(85, 214, 195, .12);
  --accent-line: rgba(85, 214, 195, .34);
  --accent-3: #77bcff;
  --accent-ring: rgba(85, 214, 195, .2);
  --on-accent: #06201d;
  --radius-xl: 24px;
  --shadow-1: 0 16px 44px rgba(0, 0, 0, .25);
}

[data-theme='light'] {
  color-scheme: light;
  --bg: #f0f6f7;
  --bg-2: #ffffff;
  --bg-elev: #ffffff;
  --surface: #ffffff;
  --text: #112937;
  --text-2: #4e6674;
  --text-3: #6d8490;
  --accent: #087f70;
  --accent-2: #0c9e88;
  --accent-soft: rgba(8, 127, 112, .09);
  --accent-line: rgba(8, 127, 112, .28);
  --accent-3: #1673aa;
  --accent-ring: rgba(8, 127, 112, .16);
  --on-accent: #ffffff;
  --shadow-1: 0 16px 42px rgba(17, 48, 62, .1);
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 96px;
}

body {
  background:
    radial-gradient(ellipse at 88% 2%, rgba(37, 117, 131, .13), transparent 36rem),
    var(--bg);
  color: var(--text);
  font-family: 'Cairo', system-ui, sans-serif;
}

button,
a,
input {
  -webkit-tap-highlight-color: transparent;
}

:where(button, a, input, video):focus-visible {
  outline: 3px solid var(--accent-2);
  outline-offset: 3px;
}

.ambient::before,
.ambient::after {
  opacity: .55;
  filter: blur(110px);
}

.topbar {
  border: 1px solid var(--accent-line);
  border-radius: 22px;
  background: color-mix(in srgb, var(--bg-2) 84%, transparent);
  box-shadow: 0 12px 36px rgba(0, 0, 0, .14);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
}

.brand-name {
  letter-spacing: -.045em;
}

.hero-copy {
  border: 1px solid var(--accent-line);
  background:
    radial-gradient(ellipse at 88% 12%, rgba(85, 214, 195, .17), transparent 34%),
    linear-gradient(140deg, var(--bg-elev), var(--bg-2) 72%);
  box-shadow: var(--shadow-1);
}

.hero-copy::after {
  opacity: .72;
  filter: blur(14px);
}

.hero h1 {
  letter-spacing: -.055em;
}

.hero h1 span {
  background: linear-gradient(100deg, var(--accent-2), var(--accent-3));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero-card,
.section,
.admin-panel {
  border: 1px solid var(--accent-line);
  box-shadow: var(--shadow-1);
}

.hero-card {
  background:
    radial-gradient(circle at 85% 6%, var(--accent-soft), transparent 44%),
    var(--bg-elev);
}

.section {
  background: color-mix(in srgb, var(--bg-2) 92%, transparent);
}

.section-kicker {
  letter-spacing: .16em;
}

.section-title {
  letter-spacing: -.035em;
}

.channel-card {
  overflow: hidden;
  border-color: color-mix(in srgb, var(--accent-line) 70%, transparent);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--bg-elev) 96%, var(--accent-soft)), var(--bg-2));
  transition:
    transform .22s ease,
    border-color .22s ease,
    box-shadow .22s ease,
    background-color .22s ease;
}

.channel-card:hover,
.channel-card:focus-within {
  transform: translateY(-3px);
  border-color: var(--accent);
  box-shadow: 0 14px 28px rgba(0, 0, 0, .2), 0 0 0 1px var(--accent-soft);
}

.channel-card .thumb {
  background-color: var(--bg);
}

.channel-card .channel-name {
  letter-spacing: -.02em;
}

.primary-btn,
.secondary-btn,
.icon-btn,
.back-btn,
.ctrl,
.mobile-nav button {
  transition:
    transform .18s ease,
    background-color .18s ease,
    border-color .18s ease,
    color .18s ease,
    box-shadow .18s ease;
}

.primary-btn:hover,
.secondary-btn:hover,
.icon-btn:hover,
.back-btn:hover,
.ctrl:hover {
  transform: translateY(-1px);
}

.primary-btn {
  box-shadow: 0 8px 24px var(--accent-soft);
}

.watch-section .player-frame,
.watch-section #playerFrame {
  border-color: var(--accent-line);
  box-shadow: 0 18px 48px rgba(0, 0, 0, .28);
}

.player-side {
  background:
    radial-gradient(ellipse at 100% 0%, var(--accent-soft), transparent 38%),
    var(--bg-elev);
}

.mobile-nav {
  border-color: var(--accent-line);
  background: color-mix(in srgb, var(--bg-2) 88%, transparent);
  box-shadow: 0 -12px 34px rgba(0, 0, 0, .18);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.modal-card,
.command-panel,
.ai-panel {
  border-color: var(--accent-line);
  box-shadow: 0 26px 80px rgba(0, 0, 0, .32);
}

@media (max-width: 780px) {
  .topbar {
    border-radius: 18px;
  }

  .hero-copy {
    background:
      radial-gradient(ellipse at 92% 6%, rgba(85, 214, 195, .15), transparent 38%),
      linear-gradient(145deg, var(--bg-elev), var(--bg-2));
  }

  .channel-card:hover,
  .channel-card:focus-within {
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
  }
}


/* ===== SAMI v23 — matched to screenshots (480css @1.5x) ===== */
html[data-theme='light']{--bg:#eff5f7;--surface:#fff;--line:#dbe5e8;--panel:#e9f0f1}
html:not([data-theme='light']){--panel:#0e1c25}
.ambient{display:none!important}
body{font-family:'IBM Plex Sans Arabic','Cairo',system-ui,sans-serif}
body .topbar{display:flex;align-items:center;gap:6px;height:auto;min-height:0;margin:0;padding:12px 0;border:0;border-bottom:1px solid var(--line);border-radius:0;box-shadow:none;background:transparent;backdrop-filter:none;position:relative;top:auto;width:auto;max-width:none;transform:none}
body .brand{display:flex;flex:0 0 auto;align-items:center;gap:9px}
body .brand-mark{width:40px;height:40px;border-radius:11px;background:#0b2a29;display:grid;place-items:center;padding:0;font-size:0;box-shadow:none;position:static}
body .brand-mark svg{width:40px;height:40px}
body .brand-copy{direction:ltr;text-align:left;display:flex;flex-direction:column;line-height:1}
body .brand-name{font-size:21px;font-weight:600;letter-spacing:.2em;color:var(--text)}
body .brand-sub{display:block;font-size:8px;letter-spacing:.13em;color:var(--text-3);margin-top:6px}
.primary-nav{display:flex;gap:2px;margin-inline-start:4px}
.nav-ico{width:38px;height:42px;display:grid;place-items:center;border-radius:8px;border:1px solid transparent;background:none;color:var(--text-2)}
.nav-ico.active{background:var(--panel);border-bottom:2px solid var(--accent);color:var(--text)}
.li{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.top-actions{display:flex;flex-direction:row-reverse;gap:6px;margin-inline-start:auto;align-items:center}
.pill-btn{display:flex;align-items:center;gap:7px;height:40px;padding:0 9px;border:1px solid var(--line);border-radius:8px;background:var(--surface);font-size:11px;font-weight:700;color:var(--text-2)}
body .top-actions .icon-btn{width:40px;height:40px;border-radius:8px;background:var(--surface);border:1px solid var(--line)}
.top-actions .search-trigger,.top-actions .account-btn{display:none!important}
.hero2{position:relative;margin:16px 0 0;padding:22px 17px 0;background:var(--panel);border-radius:14px;overflow:hidden;display:block}
.h2-kick{display:flex;align-items:center;gap:8px;color:var(--accent);font-size:12px;font-weight:500}
.h2-kick-ico{width:34px;height:34px;border:1px solid var(--accent-line);border-radius:50%;display:grid;place-items:center}
.h2-copy h1{font-family:'Readex Pro','Cairo',sans-serif;font-size:min(13vw,88px);line-height:1.18;font-weight:700;color:var(--text);margin:28px 0 12px}
.h2-copy h1 .g{color:var(--accent);display:block}
.h2-copy p{font-size:14.5px;line-height:1.95;color:var(--text-2);max-width:440px}
.h2-btn{display:inline-flex;align-items:center;gap:12px;margin-top:22px;padding:0 20px;height:54px;border-radius:4px;background:#10222a;color:#fff;font-weight:700;font-size:14px}
.h2-btn .li{stroke:#5fe8c2}
.h2-visual{position:relative;height:280px;margin:12px -17px 0}
.h2-orbit{position:absolute;left:0;top:0;width:100%;height:100%;fill:none;stroke:var(--accent);stroke-opacity:.28;overflow:visible}
.h2-card{position:absolute;left:19%;right:19%;top:44px;height:170px;border-radius:9px;background:linear-gradient(150deg,#0b2420,#04100e);transform:rotate(-7deg);box-shadow:0 26px 50px rgba(8,40,36,.28)}
.h2-card::before{content:'';position:absolute;inset:0;border-radius:9px;background:repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px)}
.h2-card>svg{position:absolute;inset:0;margin:auto;height:94%;width:auto}
.h2-live{position:absolute;top:36px;right:26px;color:#bff5e6;font-size:10px;font-weight:700;letter-spacing:.14em}
.h2-dots{position:absolute;top:11px;right:12px;display:flex;gap:4px}.h2-dots i{width:4px;height:4px;border-radius:50%;background:#5c7a74}
.h2-pin{position:absolute;width:7px;height:7px;border-radius:50%;background:#2fbf9b;box-shadow:0 0 0 6px rgba(47,191,155,.14)}
.p1{top:-3px;left:-3px}.p2{top:-38px;right:30px}.p3{bottom:8px;right:6px}
.h2-sig{position:absolute;top:30px;right:46px;direction:ltr;text-align:right;font-size:10px;letter-spacing:.16em;color:var(--accent)}
.h2-sig b{display:block;font-weight:700}.h2-sig span{color:var(--text-3);font-size:8.5px}
.h2-geo{position:absolute;bottom:22px;left:80px;direction:ltr;font-size:9.5px;letter-spacing:.16em;color:var(--accent);font-weight:600}
.h2-foot{display:flex;justify-content:space-between;align-items:center;margin:0 -17px;padding:0 17px;height:40px;border-top:1px solid var(--line);font-size:9px;color:var(--text-3)}
.h2-cnt{display:flex;align-items:center;gap:7px;flex-direction:row-reverse}.h2-cnt i{width:6px;height:6px;border-radius:50%;background:var(--accent)}
.guide{margin:44px 0 0}
.guide-head{display:flex;justify-content:space-between;align-items:flex-end;padding-bottom:14px}
.kick{color:var(--accent);font-size:11.5px;font-weight:500;margin-bottom:6px}
.guide h2,.idle-h{font-family:'Readex Pro','Cairo',sans-serif;font-size:min(6.6vw,40px);font-weight:700;line-height:1.3;color:var(--text)}
.guide p{font-size:12px;color:var(--text-2);margin-top:2px}
.guide-count{display:flex;flex-direction:column;align-items:center;padding-inline-start:16px;margin-inline-end:0;border-inline-start:1px solid var(--line);min-width:62px}
.guide-count b{font-size:34px;font-weight:300;color:var(--accent);line-height:1}.guide-count span{font-size:8.5px;color:var(--text-3);margin-top:6px}
.guide .search-box{border-top:1px solid var(--line);padding-top:16px;margin-bottom:12px;position:relative}
.guide .search-box input{height:50px;width:100%;border-radius:6px;background:var(--surface);border:1px solid var(--line);font-size:13.5px}
.guide .search-box .search-icon{top:calc(50% + 8px);transform:translateY(-50%)}
.guide .search-meta{display:flex;gap:7px;overflow-x:auto;padding:2px 0 14px;border-bottom:1px solid var(--line)}
body .filter-chip{flex:0 0 auto;height:34px;padding:0 14px;border-radius:6px;background:var(--surface);border:1px solid var(--line);color:var(--text-2);font-weight:600;font-size:13px;box-shadow:none}
body .filter-chip.active{background:#10222a;border-color:#10222a;color:#fff}
.filter-chip[data-category]>span:first-child,.filter-chip .count{display:none}
#channels{margin-top:0}#channels .section-header{display:none}
body .channel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding-top:14px}
@media(min-width:760px){body .channel-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(min-width:1100px){body .channel-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
body .channel-card{position:relative;display:flex;flex-direction:row;align-items:center;gap:10px;min-height:104px;padding:10px;background:var(--surface);border:1px solid var(--line);border-radius:6px;box-shadow:none;transform:none}
body .channel-card .thumb{width:46px;height:52px;flex:0 0 46px;aspect-ratio:auto;border-radius:5px;background:#fff;border:1px solid var(--line);padding:2px;margin:0;display:grid;place-items:center;overflow:hidden}
body .channel-card .thumb img{position:static;width:100%;height:100%;object-fit:contain;opacity:1}
body .channel-card .thumb .live-tag{display:none}
body .channel-card .card-info{flex:1;min-width:0;align-self:center;text-align:right;display:flex;flex-direction:column;gap:3px;padding:0}
body .channel-card .channel-cat{font-size:11px;color:var(--text-3);order:-1}
body .channel-card .channel-name{font-size:14.5px;font-weight:700;color:var(--text);white-space:normal;line-height:1.35}
.channel-meta{font-size:10.5px;color:var(--text-3);direction:rtl}
body .channel-card .card-bottom{position:absolute;top:5px;left:5px;padding:0;border:0;background:none;width:auto;min-height:0}
body .channel-card .small-action{width:28px;height:28px;border:0;background:none;color:var(--text-3);display:grid;place-items:center;box-shadow:none}
body .channel-card .small-action svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7}
body .channel-card .small-action.starred{color:var(--live)}body .channel-card .small-action.starred svg{fill:var(--live)}
.idle-watch{margin:46px 0 0}.idle-h{margin-bottom:14px}
.idle-card{border-radius:8px;overflow:hidden;background:#071a16;border:1px solid #14302a;color:#e8f6f1}
.idle-stage{position:relative;height:251px;background:radial-gradient(ellipse at 50% 20%,#0c2a22 0%,#04100d 75%)}
.pp-wrap{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;text-align:center;height:100%;min-height:0;padding:31px 16px 0;max-width:none!important}
.pp-top{position:absolute;top:21px;right:17px;direction:ltr;display:flex;align-items:center;gap:8px;font-size:10.5px;letter-spacing:.2em;font-weight:600;color:#cfe9e1}
.pp-top i{width:4px;height:4px;border-radius:50%;background:#3ddbb5}.pp-top b{color:#fff}
.pp-radar{width:97px;height:97px;flex:0 0 97px}
.pp-radar svg{width:100%;height:100%;fill:none;stroke:#2fbf9b;stroke-opacity:.6;overflow:visible}.pp-radar .c{fill:#4ee0b6;stroke:none;animation:ppPulse 2s ease-in-out infinite}
.pp-radar svg circle:nth-child(2){animation:ppRing 3s ease-in-out infinite;transform-origin:center}
@keyframes ppPulse{50%{opacity:.35}}@keyframes ppRing{50%{transform:scale(1.07);stroke-opacity:.95}}
.pp-eye{font-size:9.5px;letter-spacing:.2em;color:#5fe0c0;font-weight:600;margin-top:17px}
.pp-wrap h2{font-family:'Readex Pro','Cairo',sans-serif;font-size:17px;font-weight:600;color:#fff;margin-top:12px}.pp-wrap p{font-size:12px;color:#6f8a84;margin-top:6px}
.pp-ctrl{position:absolute;inset-inline:0;bottom:4px;height:46px;display:flex;align-items:center;gap:0;padding:0 10px;direction:rtl;color:#9bb5ae}
.pp-ctrl>span{width:43px;height:43px;display:grid;place-items:center}.pp-ctrl .sp{margin-inline-start:auto}
.pp-ctrl em{font-style:normal;display:flex;align-items:center;gap:7px;font-size:9px;color:#b4c9c3;margin-inline-start:2px}.pp-ctrl em i{width:5px;height:5px;border-radius:50%;background:#7d908b}
.pp-ctrl .li{width:20px;height:20px}
.idle-side{border-top:1px solid #12302a;padding:20px 16px 44px;background:#071b17}
.sig-row{display:flex;align-items:center;justify-content:space-between;padding-bottom:18px;border-bottom:1px solid #12302a;font-size:9.5px;color:#9bb5ae}
.sig-ico{width:34px;height:34px;border-radius:8px;background:rgba(61,219,181,.13);color:#3ddbb5;display:grid;place-items:center;order:2}.sig-ico .li{width:19px;height:19px}
.ready-empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px;padding:38px 10px 0;color:#7f9a94}
.ready-empty strong{font-family:'Readex Pro','Cairo',sans-serif;font-size:17px;font-weight:600;color:#fff;margin-top:14px}.ready-empty span{font-size:11.5px;line-height:2;max-width:240px}
.bars{display:flex;align-items:flex-end;justify-content:center;gap:5px;height:40px}
.bars i{display:block;width:9px;height:30%;border-radius:2px;background:linear-gradient(#256a58,#12382f);border:1px solid #2f8a74;animation:barRise 1.5s ease-in-out infinite}
.bars i:nth-child(1){animation-duration:1.3s;animation-delay:-.3s}.bars i:nth-child(2){animation-duration:1.7s;animation-delay:-.9s}
.bars i:nth-child(3){animation-duration:1.4s;animation-delay:-.1s}.bars i:nth-child(4){animation-duration:1.9s;animation-delay:-1.2s}
@keyframes barRise{0%,100%{height:22%}50%{height:100%}}
html .player-frame,html .player-placeholder{background:radial-gradient(ellipse at 50% 20%,#0c2a22 0%,#04100d 75%);color:#e8f6f1}
body .footer{display:flex;flex-direction:column;align-items:stretch;gap:10px;margin:36px 0 0;padding:16px 0 80px;border-top:1px solid var(--line);background:none}
.foot-brand{display:flex;flex-direction:row;align-items:center;gap:10px;font-size:11px;color:var(--text-2)}.foot-brand b{letter-spacing:.2em;font-size:12px;color:var(--text)}
.foot-brand .brand-mark{width:32px;height:32px;border-radius:9px}.foot-brand .brand-mark svg{width:32px;height:32px}
.footer-main{font-size:9.5px;letter-spacing:.1em;color:var(--text-3);text-align:right;padding-inline-end:6px}


html,body,.app-shell{background:var(--bg)!important}
.v10-install[hidden]{display:none!important}
#v10Resume,#v10Favs,#v10Reco{display:none!important}
#channels{background:none!important;border:0!important;box-shadow:none!important;padding:0!important}
.sig-row{justify-content:flex-start;gap:12px}.sig-ico{order:0}
.h2-copy h1{font-size:min(15vw,96px);line-height:.95;margin:30px 0 14px}
.h2-copy p{max-width:370px;font-weight:300}
body .topbar{padding:8px 0}
body .brand-name{font-weight:500;letter-spacing:.18em}
.h2-cnt b{font-weight:400}
.pp-radar svg circle:nth-child(1){stroke-width:1.3}.pp-radar svg circle:nth-child(2){stroke-width:1.3}

.guide .search-box .search-icon{left:auto!important;right:16px!important}
.guide .search-box input{padding-right:50px!important;padding-left:14px!important;text-align:right}
.h2-copy h1{line-height:1.02}


html.mm{--pad:17px}
html.mm .h2-copy h1{font-size:72px}
html.mm .guide h2,html.mm .idle-h{font-size:31px}
#mobileMode.active{background:var(--panel);border-bottom:2px solid var(--accent);color:var(--text)}
html.mm .modal-card{max-width:92%!important;width:min(440px,92%)!important}
html.mm .ai-panel{max-width:92%!important;width:min(440px,92%)!important}
html.mm /* Toast and overlays */
.toast{max-width:92%!important;width:min(440px,92%)!important}
body .channel-card{gap:8px;padding:10px 8px}body .channel-card .channel-name{font-size:13.5px}.channel-meta{font-size:10px}

div.script:
//
(function(){var root=document.getElementById('presentation');if(!root||root.hasAttribute('hidden'))return;if(!root)return;
var ring=root.querySelector('.ring'),stage=root.querySelector('.stage'),sl=ring.children,dots=root.querySelectorAll('.pres-dot'),n=sl.length,step=360/n,cur=0,paused=false,drag=null,de=document.documentElement;
function sg(){return de.dir==='ltr'?-1:1}
function act(){return((cur%n)+n)%n}
function render(){ring.style.transform='rotateY('+sg()*cur*step+'deg)';var a=act();for(var k=0;k<n;k++){sl[k].classList.toggle('on',k===a);dots[k].classList.toggle('on',k===a)}}
function go(d){cur+=d;render()}
function to(i){var d=((i-act())%n+n)%n;if(d>n/2)d-=n;go(d)}
var raf=0,ldx=0,vis=true;
stage.addEventListener('pointerdown',function(e){drag={x:e.clientX,base:sg()*cur*step,moved:false,s:e.target.closest&&e.target.closest('.slide')};ldx=0;ring.style.transition='none';try{stage.setPointerCapture(e.pointerId)}catch(_){}});
function paint(){raf=0;if(drag)ring.style.transform='rotateY('+(drag.base+ldx*.35)+'deg)'}
stage.addEventListener('pointermove',function(e){if(!drag)return;ldx=e.clientX-drag.x;if(Math.abs(ldx)>4)drag.moved=true;if(!raf)raf=requestAnimationFrame(paint)});
function end(e){if(!drag)return;var d=drag;drag=null;if(raf){cancelAnimationFrame(raf);raf=0}ring.style.transition='';try{stage.releasePointerCapture(e.pointerId)}catch(_){}if(!d.moved&&d.s&&e.type==='pointerup'){to(Array.prototype.indexOf.call(sl,d.s));return}cur=Math.round((d.base+ldx*.35)/(sg()*step));ldx=0;render()}
stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);stage.addEventListener('lostpointercapture',end);
root.querySelector('.pres-next').onclick=function(){go(1)};root.querySelector('.pres-prev').onclick=function(){go(-1)};
for(var k=0;k<n;k++)(function(k){dots[k].onclick=function(){to(k)}})(k);
root.addEventListener('keydown',function(e){var d=de.dir==='ltr'?1:-1;if(e.key==='ArrowRight')go(d);else if(e.key==='ArrowLeft')go(-d)});
['pointerenter','focusin'].forEach(function(v){root.addEventListener(v,function(){paused=true})});
['pointerleave','focusout'].forEach(function(v){root.addEventListener(v,function(){paused=false})});
try{new MutationObserver(render).observe(de,{attributes:true,attributeFilter:['dir']})}catch(_){}
try{new IntersectionObserver(function(en){vis=en[0].isIntersecting},{threshold:.15}).observe(root)}catch(_){}
if(!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches))setInterval(function(){if(vis&&!paused&&!drag&&!document.hidden)go(1)},5000);
render();})();
