// ── Theme-aware images ── // img = light-mode image (#1), img2 = dark-mode image (#2). Every existing read of // `.img` throughout the app keeps working: it now resolves to the image of the // active theme, so nothing else in the code needed to change. let HAS_THEMED_IMG=false; (function(){ const isDarkNow=()=>document.documentElement.getAttribute('data-theme')!=='light'; const wire=o=>{ if(!o||typeof o!=='object')return; const light=String(o.img||'').trim(),dark=String(o.img2||'').trim(); if(!dark)return; HAS_THEMED_IMG=true; Object.defineProperty(o,'img',{enumerable:true,configurable:true,get(){return isDarkNow()?(dark||light):(light||dark)}}); }; Object.keys(db).forEach(k=>{wire(db[k]);(db[k].c||[]).forEach(wire)}); })();
