const T = { watchBack:{ar:'العودة إلى القنوات',en:'Back to channels'}, watchFav:{ar:'المفضلة',en:'Favorite'}, relatedTitle:{ar:'قنوات أخرى من نفس القسم',en:'More from this section'}, adminPanelTitle:{ar:'لوحة المدير',en:'Admin panel'}, adminPanelSub:{ar:'تظهر لك وحدك',en:'Visible to you only'}, heroEyebrow:{ar:'تلفزيون مباشر — اكتشف وشاهد',en:'Live TV — discover and watch'}, heroHeadline:{ar:'كل القنوات التي تبحث عنها',en:'The channels you want, in one place'}, heroHeadlineAccent:{ar:'مباشرة',en:'live'}, heroPanelTitle:{ar:'ابدأ من هنا',en:'Start here'}, heroPanelCopy:{ar:'ابحث عن قناة أو اختر دولة، ثم افتح تجربة المشاهدة فورًا.',en:'Search for a channel or choose a country, then jump straight into watching.'}, heroText:{ar:'اكتشف القنوات حسب الدولة، ابحث بالاسم، وادخل إلى تجربة مشاهدة مصممة حول المحتوى بدل ازدحام الواجهة.',en:'Discover channels by country, search by name, and move into a watch experience built around content rather than clutter.'}, discoveryTitle:{ar:'اكتشاف القنوات',en:'Discover channels'}, discoverySub:{ar:'ابحث باسم القناة أو الدولة',en:'Search by channel or country'}, backToCats:{ar:"كل الأقسام",en:"All sections"}, countriesTitle:{ar:"الأقسام",en:"Sections"}, searchResultsTitle:{ar:"نتائج البحث",en:"Search results"}, aboutTitle:{ar:"عن الموقع",en:"About"}, aboutSub:{ar:"معلومات عن الخدمة وطريقة الاستخدام",en:"About the service and how to use it"}, aboutQ1:{ar:"ما هو هذا الموقع؟",en:"What is this site?"}, aboutA1:{ar:"واجهة عربية لاكتشاف القنوات التلفزيونية المتاحة عبر البث المباشر على الإنترنت وتصفحها حسب الدولة. الموقع يعمل كفهرس ومشغّل: لا يستضيف أي بث، وكل قناة تُعرض من مصدرها الأصلي المتاح للعامة.",en:"An Arabic interface for discovering TV channels streamed live over the internet and browsing them by country. The site works as an index and player: it hosts no streams, and every channel is shown from its original public source."}, aboutQ2:{ar:"كيف أستخدمه؟",en:"How do I use it?"}, aboutA2:{ar:"اختر القسم (الدولة) الذي تريده من قائمة الأقسام، ثم اختر القناة لتبدأ المشاهدة في المشغّل. يمكنك إضافة القنوات إلى المفضلة، والرجوع إلى ما شاهدته مؤخرًا، والبحث السريع بالاسم، وتغيير اللغة والمظهر من الشريط العلوي.",en:"Pick a section (country) from the list, then pick a channel to start watching in the player. You can add channels to favorites, return to what you watched recently, search quickly by name, and change language and theme from the top bar."}, aboutQ3:{ar:"ملاحظات مهمة",en:"Important notes"}, aboutA3:{ar:"جودة البث وتوفره تعتمد على مصدر كل قناة وقد تتغير أو تتوقف دون إشعار. إن لاحظت قناة لا تعمل أو محتوى يخالف حقوقك، تواصل معنا عبر صفحة الاتصال أدناه وسنراجعه بسرعة.",en:"Stream quality and availability depend on each channel's source and may change or stop without notice. If a channel doesn't work or content infringes your rights, contact us below and we'll review it quickly."}, faqTitle:{ar:"الأسئلة الشائعة",en:"FAQ"}, faq1q:{ar:"هل الخدمة مجانية؟",en:"Is the service free?"}, faq1a:{ar:"نعم، تصفح القنوات ومشاهدتها مجانية.",en:"Yes, browsing and watching channels is free."}, faq2q:{ar:"لماذا لا تعمل قناة معينة؟",en:"Why does a channel not work?"}, faq2a:{ar:"قد يكون مصدر البث متوقفًا مؤقتًا أو محجوبًا في منطقتك، جرّب مصدرًا آخر من قائمة المصادر إن وُجد.",en:"The stream source may be temporarily down or blocked in your region. Try another source from the sources list if available."}, faq3q:{ar:"هل تحتاج إلى حساب؟",en:"Do I need an account?"}, faq3a:{ar:"التصفح مفتوح للجميع، وتسجيل الدخول يتيح حفظ المفضلة وسجل المشاهدة ومزامنتها.",en:"Browsing is open to everyone; signing in lets you save and sync favorites and watch history."}, privTitle:{ar:"سياسة الخصوصية",en:"Privacy policy"}, priv1:{ar:"نحترم خصوصيتك. عند تسجيل الدخول نحفظ بريدك الإلكتروني واسم العرض والمفضلة وسجل المشاهدة لتقديم الخدمة ومزامنتها بين أجهزتك، ولا نبيع بياناتك لأي جهة.",en:"We respect your privacy. When you sign in we store your email, display name, favorites and watch history to provide the service and sync it across your devices. We never sell your data."}, priv2:{ar:"يستخدم الموقع ملفات تعريف الارتباط (الكوكيز) والتخزين المحلي لحفظ إعداداتك مثل اللغة والمظهر. كما تستخدم Google وشركاؤها ملفات تعريف الارتباط لعرض إعلانات مخصصة بناءً على زياراتك لهذا الموقع ومواقع أخرى عبر Google AdSense.",en:"The site uses cookies and local storage to save settings such as language and theme. Google and its partners also use cookies to show personalized ads based on your visits to this and other sites through Google AdSense."}, priv3a:{ar:"يمكنك إلغاء الإعلانات المخصصة أو إدارتها من",en:"You can opt out of or manage personalized ads from"}, priv3l1:{ar:"إعدادات إعلانات Google",en:"Google Ad Settings"}, priv3b:{ar:"، وللاطلاع على كيفية استخدام Google للبيانات زُر",en:", and to learn how Google uses data visit"}, priv3l2:{ar:"هذه الصفحة",en:"this page"}, priv3c:{ar:". باستمرارك في استخدام الموقع فإنك توافق على هذه السياسة، وقد نحدّثها من وقت لآخر.",en:". By continuing to use the site you agree to this policy, which we may update from time to time."}, termsTitle:{ar:"شروط الاستخدام",en:"Terms of use"}, terms1:{ar:"الموقع للاستخدام الشخصي وغير التجاري.",en:"The site is for personal, non-commercial use."}, terms2:{ar:"لا يستضيف الموقع أي بث ولا يملك حقوق القنوات المعروضة، وجميع الحقوق محفوظة لأصحابها.",en:"The site hosts no streams and owns no rights to the channels shown; all rights belong to their owners."}, terms3:{ar:"يُمنع استخدام الموقع بطريقة تضر بالخدمة أو بالمستخدمين الآخرين.",en:"Using the site in a way that harms the service or other users is prohibited."}, terms4:{ar:"يحق لمالك الموقع إزالة أي قناة أو تعديل الخدمة في أي وقت.",en:"The site owner may remove any channel or modify the service at any time."}, contactTitle:{ar:"اتصل بنا",en:"Contact us"}, contactA:{ar:"للاستفسارات أو الإبلاغ عن قناة أو طلب إزالة محتوى، تواصل مع مالك الموقع عبر",en:"For inquiries, reporting a channel or requesting content removal, contact the site owner via"}, footContact:{ar:"اتصل بنا",en:"Contact"}, footTerms:{ar:"الشروط",e