function t(key){const row=T[key];if(!row)return key;return row[state.lang]||row.ar} function catLabel(key){const cat=db[key];if(!cat)return '';return state.lang==='en'?(CATEGORY_EN[key]||cat.n):cat.n} function nameLabel(rawName){return state.lang==='en'?(CHANNEL_EN[rawName]||rawName):rawName} function chLabel(ch){return ch?nameLabel(ch.n):''} function qLabel(q){if(state.lang==='en'&&Q_EN[q])return Q_EN[q];return q} function sourceCountLabel(n){return state.lang==='en'?(n+' '+(n===1?'source':'sources')):(n+' مصدر')} function itemsCountLabel(n){return state.lang==='en'?(n+' '+(n===1?'item':'items')):(n+' عنصر')}
function applyI18n(){ els.root.setAttribute('lang',state.lang); els.root.setAttribute('dir',state.lang==='ar'?'rtl':'ltr'); $$('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)}); $$('[data-i18n-aria]').forEach(el=>{el.setAttribute('aria-label',t(el.dataset.i18nAria))}); $$('[data-i18n-title]').forEach(el=>{el.title=t(el.dataset.i18nTitle)}); $$('[data-i18n-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder)}); const onlineHint=byId('onlineHint');if(onlineHint&&state.onlineHintKey)onlineHint.textContent=t(state.onlineHintKey); const statsHint=byId('statsHint');if(statsHint&&state.statsHintKey)statsHint.textContent=t(state.statsHintKey); const label=byId('langToggleLabel');if(label)label.textContent=state.lang==='ar'?'EN':'AR'; const btn=byId('langToggle');if(btn)btn.title=state.lang==='ar'?'Switch to English':'التبديل إلى العربية'; renderFilters();renderGrid();renderHistory(); if(!state.channel){ els.playerMeta.textContent=t('playerMetaDefault'); els.nowTitle.textContent=t('nowTitleDefault'); els.nowMeta.textContent=t('nowMetaDefault'); els.signalText.textContent=t('waitingSelection'); els.sourceLabel.textContent='—'; els.qualityList.replaceChildren(); const e=document.createElement('div');e.className='ready-empty';e.innerHTML='<div class="bars"><i></i><i></i><i></i><i></i></div><strong>'+escapeHTML(t('readyTitle'))+'</strong><span>'+escapeHTML(t('readySub'))+'</span>'; els.qualityList.appendChild(e); if(els.placeholderTitle)els.placeholderTitle.textContent=t('placeholderTitleDefault'); if(els.placeholderText)els.placeholderText.textContent=t('placeholderTextDefault'); }else{ const catN=catLabel(state.category); els.nowTitle.textContent=chLabel(state.channel); els.nowMeta.textContent=catN+' · '+sourceCountLabel(sourcesFor(state.channel).length); els.playerMeta.textContent=t('currentContentPrefix')+catN; updateQualityList(state.channel); } if(els.results.classList.contains('show'))renderSearchResults(); if(els.commandBackdrop.classList.contains('show'))renderCommand(els.commandInput.value); if(window.SamiComments)SamiComments.refresh(); }
function setupLang(){ applyI18n(); const btn=byId('langToggle'); if(btn)btn.onclick=()=>{ state.lang=state.lang==='ar'?'en':'ar'; try{localStorage.setItem(CONFIG.storageLang,state.lang)}catch(_){} applyI18n(); }; } const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s)); const byId = id => document.getElementById(id);
const state = { category:null, channel:null, query:'', favoritesOnly:false, favs:{}, hist:[], hls:null, recorder:null, chunks:[], failoverIndex:0, controlTimer:null, searchTimer:null, isDark:(function(){let s=null;try{s=localStorage.getItem(CONFIG.storageTheme)}catch(_){}if(s)return s!=='light';try{return !(window.matchMedia&&matchMedia('(prefers-color-scheme: light)').matches)}catch(_){return true}})(), lang:(localStorage.getItem(CONFIG.storageLang)||'ar'), volume:Number(localStorage.getItem('sg_volume')||0.85), muted:localStorage.getItem('sg_muted')==='1', onlineHintKey:null, statsHintKey:null, user:null, cloudDb:null, cloudSynced:false, pendingPlay:null, emailAuthMode:'signin' };
const els = { body:document.body, root:document.documentElement, video:byId('mainVideo'), playerFrame:byId('playerFrame'), placeholder:byId('playerPlaceholder'), placeholderTitle:byId('placeholderTitle'), placeholderText:byId('placeholderText'), placeholderRetry:byId('placeholderRetry'), overlay:byId('playerOverlay'), play:byId('playBtn'), mute:byId('muteBtn'), pip:byId('pipBtn'), share:byId('shareBtn'), screenshot:byId('screenshotBtn'), record:byId('recordBtn'), fullscreen:byId('fullscreenBtn'), progress:byId('progressTrack'), fill:byId('progressFill'), nowTitle:byId('nowTitle'), nowMeta:byId('nowMeta'), playerMeta:byId('playerMeta'), sourceLabel:byId('sourceLabel'), signalDot:byId('signalDot'), signalText:byId('signalText'), qualityList:byId('qualityList'), search:byId('searchInput'), results:byId('searchResults'), filters:byId('categoryFilters'), grid:byId('channelGrid'), gridLabel:byId('gridLabel'), historySection:byId('recentSection'), historyTrack:byId('historyTrack'), toast:byId('toast'), commandBackdrop:byId('commandBackdrop'), commandInput:byId('commandInput'), commandBody:byId('commandBody'), modalBackdrop:byId('modalBackdrop'), themeIcon:byId('themeIcon'), accountToggle:byId('accountToggle'), accountAvatar:byId('accountAvatar'), accountBackdrop:byId('accountBackdrop'), accountGuestView:byId('accountGuestView'), accountProfileView:byId('accountProfileView'), accountAvatarLg:byId('accountAvatarLg'), accountName:byId('accountName'), accountEmail:byId('accountEmail'), accountSyncStatus:byId('accountSyncStatus'), googleSignInBtn:byId('googleSignInBtn'), googleSignOutBtn:byId('googleSignOutBtn'), emailAuthForm:byId('emailAuthForm'), emailAuthEmail:byId('emailAuthEmail'), emailAuthPassword:byId('emailAuthPassword'), emailAuthError:byId('emailAuthError'), emailAuthSubmit:byId('emailAuthSubmit'), emailAuthToggleMode:byId('emailAuthToggleMode'), emailAuthForgot:byId('emailAuthForgot'), closeAccount:byId('closeAccount') };
