function normalizeArabic(value){ return String(value||'') .toLowerCase() .replace(/[أإآٱ]/g,'ا') .replace(/[ى]/g,'ي') .replace(/[ؤ]/g,'و') .replace(/[ئ]/g,'ي') .replace(/[ة]/g,'ه') .replace(/[ـ]/g,'') .replace(/[ًٌٍَُِّْ]/g,'') .replace(/[\u200e\u200f\u061c]/g,'') .replace(/\s+/g,' ') .trim(); }
function dbStats(){ const categories=Object.entries(db); let channels=0,sources=0; categories.forEach(([,cat])=>{channels+=cat.c.length;cat.c.forEach(ch=>sources+=ch.l.length)}); return {categories:categories.length,channels,sources}; }
function showToast(message,ms=2200){ if(!els.toast)return; els.toast.textContent=message; els.toast.classList.add('show'); clearTimeout(els.toast._t); els.toast._t=setTimeout(()=>els.toast.classList.remove('show'),ms); }
function safeJSON(key,fallback){try{const v=JSON.parse(localStorage.getItem(key)||'');return v??fallback}catch(_){return fallback}} // Favorites & history now live ONLY in the signed-in user's cloud record. // They are kept in memory for the session and never written to localStorage, // so guests have no favorites/history at all. function purgeLocalUserData(){try{localStorage.removeItem(CONFIG.storageFavs);localStorage.removeItem(CONFIG.storageHistory)}catch(_){}} function getFavs(){return state.user?(state.favs||{}):{}} function saveFavs(v){ if(!state.user)return; state.favs=v; cloudPush('favorites',v); } function favKey(key,name){return key+'::'+name} function isFav(key,name){return !!getFavs()[favKey(key,name)]} function toggleFav(key,name){ // Ignore taps until the cloud copy has loaded, otherwise we could overwrite it. if(!state.user||!state.cloudSynced)return false; const f=Object.assign({},state.favs),k=favKey(key,name);f[k]=!f[k]; if(!f[k])delete f[k];saveFavs(f);return !!f[k]; } function getHistory(){return state.user?(state.hist||[]):[]} function pushHistory(key,ch){ if(!state.user)return; let h=(state.hist||[]).filter(x=>!(x.key===key&&x.name===ch.n)); h.unshift({key,name:ch.n,icon:db[key].i});h=h.slice(0,CONFIG.historyLimit); state.hist=h; // Before the first cloud load finishes, keep it in memory only; syncCloudOnSignIn merges it. if(state.cloudSynced)cloudPush('history',h); renderHistory(); } // Pushes a favorites/history update to the signed-in user's cloud record (Firebase Realtime DB). // No-op while signed out; failures are silent so offline use never breaks the UI. function cloudPush(node,value){ if(!state.user||!state.cloudDb)return; try{state.cloudDb.ref('users/'+state.user.uid+'/'+node).set(value).catch(()=>{})}catch(_){} } // Show/hide every favorites/history surface depending on sign-in state. function applyAuthGate(){ document.body.classList.toggle('is-authed',!!state.user); if(!state.user){state.favoritesOnly=false} }
// Re-paint every image that depends on the theme (cards, sections, history, related, player avatar). function refreshThemedImages(){ if(!HAS_THEMED_IMG)return; try{renderFilters();renderGrid();renderHistory()}catch(_){} try{if(els.results&&els.results.classList.contains('show'))renderSearchResults()}catch(_){} try{ if(state.channel&&state.category){ const ch=state.channel,key=state.category; const u=imgClean(ch.img)||imgClean(db[key]&&db[key].img); const nowAvatar=byId('nowAvatar'); if(nowAvatar&&u){nowAvatar.style.backgroundImage="url('"+u.replace(/'/g,"%27")+"')";nowAvatar.textContent=''} els.video.poster=imgClean(ch.img)||DEFAULT_POSTER; renderWatchExtras(); } }catch(_){} }
function setTheme(dark,persist,animate){ if(persist===undefined)persist=true; state.isDark=dark; if(persist){try{localStorage.setItem(CONFIG.storageTheme,dark?'dark':'light')}catch(_){}} const apply=()=>{ if(dark)els.root.removeAttribute('data-theme');else els.root.setAttribute('data-theme','light'); const mc=document.querySelector('meta[name="theme-color"]'); if(mc)mc.setAttribute('content',dark?'#050b12':'#eef4f5'); syncThemeButton(); refreshThemedImages(); els.themeIcon.innerHTML=!dark?'<path d="M12 3a9 9 0 1 0 9 9 6.7 6.7 0 0 1-9-9Z"/>':'<path d="M12 4V2h2v2h-2Zm0 18v-2h2v2h-2ZM4 11H2v2h2v-2Zm18 0h-2v2h2v-2ZM5.64 7.05 4.22 5.64l1.42-1.41 1.41 1.41-1.41 1.41Zm12.72 12.72-1.41-1.41 1.41-1.41 1.42 1.41-1.42 1.41ZM18.36 7.05l-1.41-1.41 1.41-1.41 1.42 1.41-1.42 1.41ZM5.64 19.77l-1.42-1.41 1.42-1.41 1.41 1.41-1.41 1.41ZM13 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/>'; }; // Smooth cross-fade between night/day where the browser supports it if(animate&&document.startViewTransition&&!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)){ try{document.startViewTransition(apply);return}catch(_){} } apply(); }
// Always render counts with Latin digits (0-9), independent of locale. function fmtNum(n){ n=Math.max(0,Math.floor(Number(n)||0)); return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g,','); }
function renderStats(){ if(!state.isAdmin)return; const s=dbStats(); const a=byId('categoryStat'),b=byId('channelStat'),c=byId('sourceStat'); if(a)a.textContent=fmtNum(s.categories); if(b)b.textContent=fmtNum(s.channels); if(c)c.textContent=fmtNum(s.sources); }
function initStats(){ renderStats(); }
// ── Real counters (no fake numbers), both backed by Firebase Realtime DB ── // 1) "Online now": counts real open connections via the onDisconnect pattern. // 2) "Site visits": a real persistent total that increases by 1 on every // page load and is stored server-side, so it never resets on refresh. // Until CONFIG.firebase is filled in, both cards honestly show "—". function loadScriptOnce(src){ return new Promise((resolve,reject)=>{ if(document.querySelector('script[src="'+src+'"]')){resolve();return} const s=document.createElement('script'); s.src=src;s.async=true; s.onload=()=>resolve();s.onerror=()=>reject(new Error('load-failed')); document.head.appendChild(s); }); }
// Every visitor is still counted (presence + visit are write-only); the numbers are // read and rendered ONLY for the verified admin (admins/<uid> === true). async function setupFirebaseCounters(){ const cfg=CONFIG.firebase; if(!cfg||!cfg.databaseURL||!cfg.apiKey){state.cntFailed='firebaseWaiting';if(state.isAdmin)attachAdminCounters();return} try{ await loadScriptOnce('https://www.gstatic.com/firebasejs/10.13.2/firebase-app-compat.js'); await loadScriptOnce('https://www.gstatic.com/firebasejs/10.13.2/firebase-database-compat.js'); if(!window.firebase||!firebase.apps)throw new Error('sdk-missing'); const app=firebase.apps.length?firebase.apps[0]:firebase.initializeApp(cfg); const db=firebase.database(app); state.cntDb=db; const myRef=db.ref('signal_presence').push(); db.ref('.info/connected').on('value',snap=>{ if(snap.val()===true){myRef.onDisconnect().remove();myRef.set(Date.now())} }); db.ref('site_stats/total_views').transaction(cur=>(cur||0)+1); }catch(_){state.cntFailed='firebaseError'} if(state.isAdmin)attachAdminCounters(); } function attachAdminCounters(){ if(!state.isAdmin||state.cntOff)return; const onlineEl=byId('onlineStat'),onlineHint=byId('onlineHint'),onlineDot=byId('onlineDot'); const statsEl=byId('statsCount'),statsHint=byId('statsHint'); const db=state.cntDb||state.cloudDb; if(!db){ if(state.cntFailed){ if(onlineDot)onlineDot.classList.remove('live'); state.onlineHintKey=state.cntFailed;if(onlineHint)onlineHint.textContent=t(state.onlineHintKey); state.statsHintKey=state.cntFailed;if(statsHint)statsHint.textContent=t(state.statsHintKey); } return; } const pRef=db.ref('signal_presence'),vRef=db.ref('site_stats/total_views'); const pCb=snap=>{if(onlineEl)onlineEl.textContent=fmtNum(snap.exists()?Object.keys(snap.val()).length:0)}; const vCb=snap=>{if(statsEl)statsEl.textContent=fmtNum(snap.val()||0)}; pRef.on('value',pCb);vRef.on('value',vCb); state.cntOff=()=>{try{pRef.off('value',pCb);vRef.off('value',vCb)}catch(_){}}; state.onlineHintKey='statOnlineSub';if(onlineHint)onlineHint.textContent=t(state.onlineHintKey); state.statsHintKey='statVisitsHintActive';if(statsHint)statsHint.textContent=t(state.statsHintKey); } window.samiSetAdmin=function(on){ on=!!on; if(!!state.isAdmin===on)return; state.isAdmin=on; const p=byId('adminStats');if(p)p.hidden=!on; if(on){renderStats();attachAdminCounters();return} if(state.cntOff){state.cntOff();state.cntOff=null} ['categoryStat','channelStat','sourceStat','statsCount','onlineStat'].forEach(i=>{const el=byId(i);if(el)el.textContent='—'}); };
// ── Google account: sign-in + cross-device sync of favorites/history ── // Uses the same Firebase project as the visit counters (Firebase Authentication + // Realtime Database). Requires, in the Firebase console: (1) Google enabled under // Authentication → Sign-in method, (2) the blog's domain listed under // Authentication → Settings → Authorized domains, and (3) Realtime Database rules // restricting the "users/$uid" path to its own owner (see the reply for the rule). let firebaseAuthReadyPromise=null; // Firebase restores a saved session asynchronously. Until its first callback fires, // "no user" only means "not known yet", NOT "signed out". authResolved tracks that. let authResolved=false;const authWaiters=[]; function waitForAuth(ms){ if(authResolved)return Promise.resolve(); return new Promise(res=>{const to=setTimeout(res,ms||8000);authWaiters.push(()=>{clearTimeout(to);res()})}); } // Loads the Firebase Auth/Database SDK and wires up auth state — idempotent and // safe to call again after a prior failure (e.g. a slow connection at page load), // since a failed attempt resets the cached promise so the next call retries. function ensureFirebaseAuthReady(){ if(state.cloudAuth)return Promise.resolve(true); if(firebaseAuthReadyPromise)return firebaseAuthReadyPromise; const cfg=CONFIG.firebase; if(!cfg||!cfg.apiKey||!cfg.databaseURL)return Promise.resolve(false); firebaseAuthReadyPromise=(async()=>{ try{ await loadScriptOnce('https://www.gstatic.com/firebasejs/10.13.2/firebase-app-compat.js'); await loadScriptOnce('https://www.gstatic.com/firebasejs/10.13.2/firebase-auth-compat.js'); await loadScriptOnce('https://www.gstatic.com/firebasejs/10.13.2/firebase-database-compat.js'); if(!window.firebase||!firebase.apps)throw new Error('sdk-missing'); const app=firebase.apps.length?firebase.apps[0]:firebase.initializeApp(cfg); state.cloudDb=firebase.database(app); state.cloudAuth=firebase.auth(app); try{await state.cloudAuth.setPersistence(firebase.auth.Auth.Persistence.LOCAL)}catch(_){} state.cloudProvider=new firebase.auth.GoogleAuthProvider(); state.cloudAuth.onAuthStateChanged(user=>{ state.user=user; authResolved=true; try{if(user)localStorage.setItem('sg_auth_hint','1');else localStorage.removeItem('sg_auth_hint')}catch(_){} authWaiters.splice(0).forEach(f=>{try{f()}catch(_){}}); if(state.cloudUserRef){state.cloudUserRef.off();state.cloudUserRef=null} if(!user){ state.favs={};state.hist=[];state.cloudSynced=false;purgeLocalUserData(); applyAuthGate();renderFilters();renderGrid();renderHistory(); }else{applyAuthGate()} renderAccountUI(); if(window.SamiComments)SamiComments.onAuth(); if(user)syncCloudOnSignIn(user.uid); if(user&&state.pendingPlay){ const p=state.pendingPlay;state.pendingPlay=null; closeAccountModal();playChannel(p.key,p.ch); } }); state.cloudAuth.getRedirectResult().catch(err=>{if(err&&err.code)showToast(t('accountSignInError')+' — '+err.code)}); return true; }catch(err){ firebaseAuthReadyPromise=null; // allow a fresh retry on the next attempt return false; } })(); return firebaseAuthReadyPromise; } async function setupAccount(){ if(els.accountToggle)els.accountToggle.onclick=()=>{els.accountBackdrop.classList.add('show');els.accountBackdrop.setAttribute('aria-hidden','false')}; if(els.closeAccount)els.closeAccount.onclick=closeAccountModal; if(els.accountBackdrop)els.accountBackdrop.addEventListener('click',e=>{if(e.target===els.accountBackdrop)closeAccountModal()}); if(els.googleSignInBtn)els.googleSignInBtn.onclick=signInWithGoogle; if(els.googleSignOutBtn)els.googleSignOutBtn.onclick=signOutGoogle; if(els.emailAuthForm)els.emailAuthForm.addEventListener('submit',e=>{e.preventDefault();submitEmailAuth()}); if(els.emailAuthToggleMode)els.emailAuthToggleMode.onclick=toggleEmailAuthMode; if(els.emailAuthForgot)els.emailAuthForgot.onclick=sendEmailPasswordReset; setupSignupProfileFields(); // Firebase auth is warmed up by deferredBoot() (after first interaction / idle) to keep first load fast. window._setAuthTab=function(tab){ state.emailAuthMode=tab; var tabSignin=document.getElementById('authTabSignin'),tabSignup=document.getElementById('authTabSignup'); if(tabSignin)tabSignin.classList.toggle('active',tab==='signin'); if(tabSignup)tabSignup.classList.toggle('active',tab==='signup'); if(els.emailAuthSubmit)els.emailAuthSubmit.textContent=t(tab==='signin'?'emailSignInBtn':'emailSignUpBtn'); if(els.emailAuthToggleMode)els.emailAuthToggleMode.textContent=t(tab==='signin'?'emailToggleToSignup':'emailToggleToSignin'); var confirmField=document.getElementById('emailAuthConfirmField'); if(confirmField)confirmField.style.display=tab==='signup'?'flex':'none'; setSignupExtraVisible(tab==='signup'); var passLabel=document.getElementById('emailAuthPasswordLabel'); if(passLabel)passLabel.textContent=tab==='signin'?'كلمة المرور':'كلمة المرور الجديدة'; var googleText=document.getElementById('googleSignInText'); if(googleText)googleText.textContent=tab==='signin'?'المتابعة عبر Google':'التسجيل عبر Google'; setEmailAuthError(''); }; }
// ===== Profile at sign-up: first/last name, optional age, optional photo ===== function setSignupExtraVisible(on){ var box=document.getElementById('signupExtraFields'); if(box)box.style.display=on?'flex':'none'; } function resetSignupExtra(){ state.signupPhoto=null; var prev=document.getElementById('signupPhotoPreview'),btn=document.getElementById('signupPhotoBtn'); if(prev){prev.style.backgroundImage='';prev.classList.remove('has-img');prev.innerHTML='&#128100;'} if(btn)btn.textContent=t('photoChoose'); } // Crops to a centred square and shrinks to 256px JPEG so it stays small enough for the realtime database. function fileToAvatarDataUrl(file){ return new Promise(function(resolve,reject){ var url=URL.createObjectURL(file),img=new Image(); img.onload=function(){ try{ var side=Math.min(img.naturalWidth,img.naturalHeight),sx=(img.naturalWidth-side)/2,sy=(img.naturalHeight-side)/2; var c=document.createElement('canvas');c.width=c.height=256; var ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,256,256); ctx.drawImage(img,sx,sy,side,side,0,0,256,256); URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',0.82)); }catch(e){reject(e)} }; img.onerror=function(){URL.revokeObjectURL(url);reject(new Error('img'))}; img.src=url; }); } function setupSignupProfileFields(){ var input=document.getElementById('signupPhotoInput'),btn=document.getElementById('signupPhotoBtn'),prev=document.getElementById('signupPhotoPreview'); if(!input||input._ready)return;input._ready=true; if(btn)btn.onclick=function(){input.click()}; if(prev)prev.onclick=function(){input.click()}; input.addEventListener('change',async function(){ var f=input.files&&input.files[0];if(!f)return; try{ var data=await fileToAvatarDataUrl(f); state.signupPhoto=data; prev.style.backgroundImage='url('+data+')';prev.classList.add('has-img');prev.textContent=''; if(btn)btn.textContent=t('photoChange'); }catch(_){setEmailAuthError(t('photoErr'))} input.value=''; }); } async function saveProfileAfterSignup(user,profile){ var displayName=(profile.first+' '+profile.last).trim(); var data={first:profile.first,last:profile.last,name:displayName}; if(profile.age)data.age=profile.age; if(profile.photo)data.photo=profile.photo; var ok=true; try{await user.updateProfile({displayName:displayName})}catch(_){ok=false} try{ if(state.cloudDb)await state.cloudDb.ref('users/'+user.uid+'/profile').set(data); else ok=false; }catch(_){ok=false} state.profile=Object.assign({},data,{uid:user.uid}); renderAccountUI(); if(!ok)showToast(t('profileSaveErr')); } function toggleEmailAuthMode(){ state.emailAuthMode=state.emailAuthMode==='signin'?'signup':'signin'; if(els.emailAuthSubmit)els.emailAuthSubmit.textContent=t(state.emailAuthMode==='signin'?'emailSignInBtn':'emailSignUpBtn'); if(els.emailAuthToggleMode)els.emailAuthToggleMode.textContent=t(state.emailAuthMode==='signin'?'emailToggleToSignup':'emailToggleToSignin'); var tabSignin=document.getElementById('authTabSignin'),tabSignup=document.getElementById('authTabSignup'); if(tabSignin)tabSignin.classList.toggle('active',state.emailAuthMode==='signin'); if(tabSignup)tabSignup.classList.toggle('active',state.emailAuthMode==='signup'); var confirmField=document.getElementById('emailAuthConfirmField'); if(confirmField)confirmField.style.display=state.emailAuthMode==='signup'?'flex':'none'; setSignupExtraVisible(state.emailAuthMode==='signup'); var passLabel=document.getElementById('emailAuthPasswordLabel'); if(passLabel)passLabel.textContent=state.emailAuthMode==='signin'?'كلمة المرور':'كلمة المرور الجديدة'; var googleText=document.getElementById('googleSignInText'); if(googleText)googleText.textContent=state.emailAuthMode==='signin'?'المتابعة عبر Google':'التسجيل عبر Google'; setEmailAuthError(''); } function setEmailAuthError(msg){ if(!els.emailAuthError)return; els.emailAuthError.textContent=msg||''; if(msg)els.emailAuthError.classList.add('visible');else els.emailAuthError.classList.remove('visible'); } function mapEmailAuthError(code){ switch(code){ case 'auth/invalid-email':return t('emailErrInvalid'); case 'auth/user-not-found':return t('emailErrUserNotFound'); case 'auth/wrong-password':case 'auth/invalid-credential':case 'auth/invalid-login-credentials':return t('emailErrWrongPassword'); case 'auth/email-already-in-use':return t('emailErrInUse'); case 'auth/weak-password':return t('emailErrWeakPassword'); default:return t('emailErrGeneric')+(code?' ('+code+')':''); } } async function submitEmailAuth(){ const email=(els.emailAuthEmail&&els.emailAuthEmail.value||'').trim(); const pass=els.emailAuthPassword&&els.emailAuthPassword.value||''; setEmailAuthError(''); if(!email||!pass){setEmailAuthError(mapEmailAuthError('auth/invalid-email'));return} var newProfile=null; if(state.emailAuthMode==='signup'){ var fEl=document.getElementById('signupFirstName'),lEl=document.getElementById('signupLastName'),aEl=document.getElementById('signupAge'); var first=(fEl&&fEl.value||'').trim(),last=(lEl&&lEl.value||'').trim(),ageRaw=(aEl&&aEl.value||'').trim(); if(!first||!last){setEmailAuthError(t('emailErrNameRequired'));return} var age=null; if(ageRaw!==''){age=parseInt(ageRaw,10);if(!(age>=5&&age<=120)){setEmailAuthError(t('emailErrAgeInvalid'));return}} newProfile={first:first,last:last,age:age,photo:state.signupPhoto||null}; } if(els.emailAuthSubmit)els.emailAuthSubmit.disabled=true; const ready=await ensureFirebaseAuthReady(); if(!ready||!state.cloudAuth){ if(els.emailAuthSubmit)els.emailAuthSubmit.disabled=false; setEmailAuthError(t('accountConnectError'));return; } try{ if(state.emailAuthMode==='signup'){ const cred=await state.cloudAuth.createUserWithEmailAndPassword(email,pass); if(newProfile&&cred&&cred.user)await saveProfileAfterSignup(cred.user,newProfile); } else await state.cloudAuth.signInWithEmailAndPassword(email,pass); closeAccountModal();showToast(t('accountSignedInToast')); if(els.emailAuthForm)els.emailAuthForm.reset(); resetSignupExtra(); }catch(err){ setEmailAuthError(mapEmailAuthError(err&&err.code)); }finally{ if(els.emailAuthSubmit)els.emailAuthSubmit.disabled=false; } } async function sendEmailPasswordReset(){ const email=(els.emailAuthEmail&&els.emailAuthEmail.value||'').trim(); if(!email){setEmailAuthError(t('emailResetNeedAddress'));return} const ready=await ensureFirebaseAuthReady(); if(!ready||!state.cloudAuth){setEmailAuthError(t('accountConnectError'));return} try{await state.cloudAuth.sendPasswordResetEmail(email);setEmailAuthError('');showToast(t('emailResetSent'))} catch(err){setEmailAuthError(mapEmailAuthError(err&&err.code))} } function closeAccountModal(){els.accountBackdrop.classList.remove('show');els.accountBackdrop.setAttribute('aria-hidden','true')} async function signInWithGoogle(){ if(els.googleSignInBtn)els.googleSignInBtn.disabled=true; const ready=await ensureFirebaseAuthReady(); if(els.googleSignInBtn)els.googleSignInBtn.disabled=false; if(!ready||!state.cloudAuth){showToast(t('accountConnectError'));return} try{ await state.cloudAuth.signInWithPopup(state.cloudProvider); closeAccountModal();showToast(t('accountSignedInToast')); }catch(err){ const code=err&&err.code; if(code==='auth/popup-blocked'||code==='auth/cancelled-popup-request'||code==='auth/operation-not-supported-in-this-environment'||code==='auth/web-storage-unsupported'){ // Popups are unreliable on some mobile browsers; fall back to a full-page redirect. try{await state.cloudAuth.signInWithRedirect(state.cloudProvider)}catch(err2){showToast(t('accountSignInError')+' — '+(err2&&err2.code||err2))} }else if(code!=='auth/popup-closed-by-user'){ showToast(t('accountSignInError')+' — '+(code||err)); } } } async function signOutGoogle(){ if(!state.cloudAuth)return; try{await state.cloudAuth.signOut();showToast(t('accountSignedOutToast'))}catch(_){} } function renderAccountUI(){ const user=state.user; if(els.accountToggle)els.accountToggle.classList.toggle('signed-in',!!user); if(user){ const prof=(state.profile&&state.profile.uid===user.uid)?state.profile:null; const photo=(prof&&prof.photo)||user.photoURL||''; const shownName=user.displayName||(prof&&prof.name)||''; if(els.accountAvatar){els.accountAvatar.hidden=false;els.accountAvatar.style.backgroundImage=photo?'url('+photo+')':'none'} if(els.accountAvatarLg){els.accountAvatarLg.style.backgroundImage=photo?'url('+photo+')':'none';els.accountAvatarLg.textContent=photo?'':(shownName?shownName.charAt(0).toUpperCase():'')} if(els.accountName)els.accountName.textContent=shownName||'—'; const ageEl=document.getElementById('accountAge'); if(ageEl){if(prof&&prof.age){ageEl.textContent=t('accountAgeText')+': '+prof.age;ageEl.hidden=false}else{ageEl.textContent='';ageEl.hidden=true}} if(els.accountEmail)els.accountEmail.textContent=user.email||''; if(els.accountGuestView)els.accountGuestView.hidden=true; if(els.accountProfileView)els.accountProfileView.hidden=false; if(els.accountSyncStatus)els.accountSyncStatus.textContent=t(state.cloudSynced?'accountSyncedNow':'accountSyncingNow'); }else{ if(els.accountAvatar)els.accountAvatar.hidden=true; state.profile=null; if(els.accountGuestView)els.accountGuestView.hidden=false; if(els.accountProfileView)els.accountProfileView.hidden=true; state.cloudSynced=false; } } async function syncCloudOnSignIn(uid){ if(!state.cloudDb)return; try{ const ref=state.cloudDb.ref('users/'+uid); const snap=await ref.once('value'); if(!state.user||state.user.uid!==uid)return; // signed out / switched account meanwhile const cloud=snap.val()||{}; // Cloud is the source of truth. Only items watched in this session before the // first load finished (state.hist) are merged on top of the cloud history. const cloudHist=Array.isArray(cloud.history)?cloud.history:[]; const seen=new Set();let mergedHist=[]; (state.hist||[]).concat(cloudHist).forEach(item=>{ if(!item||!item.key)return; const k=item.key+'::'+item.name; if(!seen.has(k)){seen.add(k);mergedHist.push(item)} }); mergedHist=mergedHist.slice(0,CONFIG.historyLimit); state.favs=cloud.favorites||{}; state.hist=mergedHist; purgeLocalUserData(); if(cloud.profile)state.profile=Object.assign({},cloud.profile,{uid:uid}); if(mergedHist.length!==cloudHist.length)await ref.child('history').set(mergedHist); state.cloudSynced=true;renderAccountUI();renderFilters();renderGrid();renderHistory(); state.cloudUserRef=ref; ref.on('value',s=>{ if(!state.user||state.user.uid!==uid)return; const v=s.val()||{}; if(v.profile){state.profile=Object.assign({},v.profile,{uid:uid});renderAccountUI()} state.favs=v.favorites||{}; state.hist=Array.isArray(v.history)?v.history:[]; renderFilters();renderGrid();renderHistory(); }); }catch(_){ state.cloudSynced=false; if(els.accountSyncStatus)els.accountSyncStatus.textContent=t('accountSyncError'); } }
const PAGE_SIZE=24; let gridList=[],gridShown=0,gridObserver=null; const DEFAULT_POSTER=els.video.getAttribute('poster')||''; function catsCountLabel(n){return state.lang==='en'?(n+' '+(n===1?'section':'sections')):(n+' قسم')} function chCountLabel(n){return state.lang==='en'?(n+' '+(n===1?'channel':'channels')):(n+' قناة')}
function renderFilters(){ const frag=document.createDocumentFragment();
try{const n=Object.keys(db).length,hc=byId('heroCatCount');if(hc)hc.textContent=state.lang==='en'?(n+' categories'):(n.toLocaleString('ar-EG')+' تصنيفًا')}catch(_){} if(state.user){ const fav=document.createElement('button'); fav.className='filter-chip'+(state.favoritesOnly?' active':''); fav.innerHTML=ICONS.heart+'<span>'+escapeHTML(t('quickFavs'))+'</span>'; fav.onclick=()=>{state.favoritesOnly=!state.favoritesOnly;renderFilters();renderGrid()}; frag.appendChild(fav); } Object.entries(db).forEach(([key,cat])=>{ const b=document.createElement('button'); b.className='filter-chip'+(!state.favoritesOnly&&state.category===key?' active':''); b.dataset.category=key; const icon=document.createElement('span');icon.textContent=cat.i;catIco(icon,cat,'width:20px;height:20px;object-fit:cover;border-radius:6px;display:block'); const text=document.createElement('span');text.textContent=catLabel(key); const count=document.createElement('span');count.className='count';count.textContent=cat.c.length; b.append(icon,text,count); b.onclick=()=>{const same=!state.favoritesOnly&&state.category===key;state.favoritesOnly=false;state.category=same?null:key;state.query='';els.search.value='';renderFilters();renderGrid();scrollToChannels()}; frag.appendChild(b); }); els.filters.replaceChildren(frag); }
// null => show the sections (countries) screen function getVisibleList(){ const favs=getFavs(); if(state.favoritesOnly){ return Object.entries(db).flatMap(([key,cat])=>cat.c.filter(ch=>favs[favKey(key,ch.n)]).map(ch=>({key,cat,ch}))) } if(state.category){const cat=db[state.category];return cat?cat.c.map(ch=>({key:state.category,cat,ch})):[]} return Object.entries(db).flatMap(([key,cat])=>cat.c.map(ch=>({key,cat,ch}))); }
function matches(item,q){ if(!q)return true; const n=normalizeArabic(q); return normalizeArabic(item.ch.n).includes(n)||normalizeArabic(item.cat.n).includes(n) }
function goSections(){state.category=null;state.favoritesOnly=false;state.query='';els.search.value='';els.results.classList.remove('show');renderFilters();renderGrid()}
function buildCard(entry,i){ const {key,cat,ch}=entry; const card=document.createElement('article');card.className='channel-card';card.dataset.key=key;card.dataset.name=ch.n;card.tabIndex=0;card.setAttribute('role','button'); const thumb=document.createElement('div');thumb.className='thumb'; const flag=document.createElement('span');flag.className='thumb-flag';flag.textContent=cat.i;if(!ch.img)catIco(flag,cat,'width:46px;height:46px;object-fit:cover;border-radius:12px;display:block');thumb.appendChild(flag); if(ch.img){ const img=new Image(); img.alt=''; img.loading='lazy'; img.decoding='async'; img.referrerPolicy='no-referrer'; thumb.appendChild(img); loadImg(img,ch.img,()=>img.classList.add('loaded'),()=>{img.removeAttribute('src');img.style.display='none'}); } const live=document.createElement('span');live.className='live-tag';live.innerHTML='<i></i> '+escapeHTML(t('liveTag'));thumb.appendChild(live); const info=document.createElement('div');info.className='card-info'; const name=document.createElement('div');name.className='channel-name';name.title=chLabel(ch);name.textContent=chLabel(ch); const catName=document.createElement('div');catName.className='channel-cat';catName.textContent=catLabel(key); const s0=sourcesFor(ch)[0];const meta=document.createElement('div');meta.className='channel-meta';meta.textContent=((s0&&s0.q)?qLabel(s0.q):t('liveTag'))+' · HLS';info.append(catName,name,meta); const bottom=document.createElement('div');bottom.className='card-bottom'; const tools=document.createElement('div');tools.className='card-tools'; const fav=document.createElement('button');fav.className='small-action'+(isFav(key,ch.n)?' starred':'');fav.title=t('favTitle');fav.setAttribute('aria-label',t('favAria'));fav.setAttribute('aria-pressed',String(isFav(key,ch.n)));fav.innerHTML=ICONS.heart; fav.onclick=(e)=>{e.stopPropagation();if(!state.user){promptAccountForChannel(key,ch);return}toggleFav(key,ch.n);const nowFav=isFav(key,ch.n);fav.classList.toggle('starred',nowFav);fav.setAttribute('aria-pressed',String(nowFav));if(state.favoritesOnly)renderGrid();showToast(nowFav?t('addedToFavorites'):t('removedFromFavorites'))}; const go=document.createElement('button');go.className='small-action';go.title=t('openTitle');go.setAttribute('aria-label',t('openAria'));go.textContent='›'; go.onclick=(e)=>{e.stopPropagation();playChannel(key,ch)}; tools.append(fav);bottom.append(tools);card.append(thumb,info,bottom); card.addEventListener('click',()=>playChannel(key,ch)); card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();playChannel(key,ch)}}); return card; }
function appendCards(){ const old=byId('gridSentinel');if(old)old.remove(); const end=Math.min(gridShown+PAGE_SIZE,gridList.length); const frag=document.createDocumentFragment(); for(let i=gridShown;i<end;i++){ frag.appendChild(buildCard(gridList[i],i)); if((i+1)%8===0&&i<gridList.length-1)frag.appendChild(createInlineAdCard()); } gridShown=end; els.grid.appendChild(frag); mountPendingAds(els.grid); if(gridShown<gridList.length){ const s=document.createElement('div');s.id='gridSentinel';s.className='grid-sentinel';els.grid.appendChild(s); if('IntersectionObserver' in window){ gridObserver=new IntersectionObserver(en=>{if(en[0].isIntersecting){gridObserver.disconnect();appendCards()}},{rootMargin:'700px 0px'}); gridObserver.observe(s); }else appendCards(); } }
function renderGrid(){ if(gridObserver){gridObserver.disconnect();gridObserver=null} const raw=getVisibleList(); const back=byId('backToCats'),title=byId('channelsTitle'); els.grid.replaceChildren(); els.grid.classList.toggle('country-grid',raw===null); if(raw===null){ title.textContent=t('countriesTitle');back.hidden=true; const keys=Object.keys(db);els.gridLabel.textContent=catsCountLabel(keys.length); const frag=document.createDocumentFragment(); keys.forEach(key=>{ const cat=db[key]; const b=document.createElement('button');b.className='country-card';b.type='button';b.dataset.key=key; const fl=document.createElement('span');fl.className='cc-flag';fl.textContent=cat.i;catIco(fl,cat,'width:54px;height:54px;object-fit:cover;border-radius:14px;display:block'); const nm=document.createElement('span');nm.className='cc-name';nm.textContent=catLabel(key); const ct=document.createElement('span');ct.className='cc-count';ct.textContent=chCountLabel(cat.c.length); b.append(fl,nm,ct); b.onclick=()=>{state.category=key;state.favoritesOnly=false;state.query='';els.search.value='';els.results.classList.remove('show');renderFilters();renderGrid();scrollToChannels()}; frag.appendChild(b); }); els.grid.appendChild(frag); return; } back.hidden=false; title.textContent=state.favoritesOnly?t('quickFavs'):(state.category?catLabel(state.category):t('searchResultsTitle')); const list=raw.filter(x=>matches(x,state.query)); {const gc=byId('guideCount');if(gc)gc.textContent=(list.length<10?'0':'')+list.length} els.gridLabel.textContent=itemsCountLabel(list.length); if(!list.length){ const e=document.createElement('div');e.className='empty'; const s=document.createElement('strong');s.textContent=state.favoritesOnly?t('emptyNoFavorites'):t('emptyNoResults'); const p=document.createElement('span');p.textContent=state.favoritesOnly?t('emptyNoFavoritesSub'):t('emptyNoResultsSub'); e.append(s,p);els.grid.appendChild(e);return; } gridList=list;gridShown=0;appendCards(); } // A full-width "advertisement" card interleaved every 8 tiles inside the channel // grid. Reuses the same AdSense ad unit as the static slots (top/before-player/ // below-list); create a separate ad unit in AdSense later if per-placement stats // are wanted. function createInlineAdCard(){ const wrap=document.createElement('div');wrap.className='ad-slot channel-grid-ad'; const label=document.createElement('span');label.className='ad-slot-label';label.textContent=t('adLabel'); const ins=document.createElement('ins');ins.className='adsbygoogle';ins.style.display='block'; ins.setAttribute('data-ad-client','ca-pub-4909042396420795'); ins.setAttribute('data-ad-slot','9828485567'); ins.setAttribute('data-ad-format','auto'); ins.setAttribute('data-full-width-responsive','true'); wrap.append(label,ins); return wrap; } // Initializes any adsbygoogle <ins> units that haven't been mounted yet (guarded via // the data-adsbygoogle-status attribute Google sets after init, so already-mounted // units are never double-pushed). function mountPendingAds(scope){ (scope||document).querySelectorAll('ins.adsbygoogle').forEach(el=>{ if(!el.dataset.adsbygoogleStatus&&!el.dataset.pushed){ el.dataset.pushed='1'; try{(window.adsbygoogle=window.adsbygoogle||[]).push({})}catch(_){} } }); }
function renderHistory(){ const h=getHistory(); els.historyTrack.replaceChildren(); els.historySection.hidden=!h.length; h.forEach(item=>{ const b=document.createElement('button');b.className='history-item'; const av=document.createElement('span');av.className='history-avatar';av.textContent=item.icon||'◉'; {const hc=db[item.key]?.c.find(x=>x.n===item.name);if(hc&&hc.img){const im=new Image();im.alt='';im.loading='lazy';im.decoding='async';im.referrerPolicy='no-referrer';im.style.cssText='width:100%;height:100%;object-fit:cover;border-radius:inherit';av.textContent='';av.style.overflow='hidden';av.appendChild(im);loadImg(im,hc.img,null,()=>im.remove())}else if(db[item.key]){av.style.overflow='hidden';catIco(av,db[item.key])}} const c=document.createElement('span');c.className='history-copy'; const n=document.createElement('span');n.className='history-name';n.textContent=nameLabel(item.name); const sub=document.createElement('span');sub.className='history-cat';sub.textContent=catLabel(item.key); c.append(n,sub);b.append(av,c);b.onclick=()=>{const cat=db[item.key];const ch=cat?.c.find(x=>x.n===item.name);if(ch)playChannel(item.key,ch)}; els.historyTrack.appendChild(b); }); }
function searchAll(q){ const n=normalizeArabic(q); if(!n)return []; const out=[]; Object.entries(db).forEach(([key,cat])=>{ if(normalizeArabic(cat.n).includes(n)||normalizeArabic(catLabel(key)).includes(n))out.push({type:'category',key,cat}); cat.c.forEach(ch=>{if(normalizeArabic(ch.n).includes(n)||normalizeArabic(cat.n).includes(n)||normalizeArabic(catLabel(key)).includes(n))out.push({type:'channel',key,cat,ch})}); }); return out.slice(0,24); }
function renderSearchResults(){ const q=els.search.value.trim(); state.query=q;const results=searchAll(q);els.results.replaceChildren(); if(!q){els.results.classList.remove('show');return} if(!results.length){ const e=document.createElement('div');e.className='empty';e.style.border=0;e.style.padding='25px 10px';e.innerHTML='<strong>'+escapeHTML(t('noResultTitle'))+'</strong><span>'+escapeHTML(t('noResultSub'))+'</span>';els.results.appendChild(e);els.results.classList.add('show');return; } results.forEach(r=>{ const b=document.createElement('button');b.className='search-result'; const icon=document.createElement('span');icon.className='result-icon';icon.textContent=r.cat.i;catIco(icon,r.cat,'width:100%;height:100%;object-fit:cover;border-radius:inherit');if(icon.style)icon.style.overflow='hidden'; const main=document.createElement('span');main.className='result-main'; const name=document.createElement('span');name.className='result-name';name.textContent=r.type==='category'?catLabel(r.key):chLabel(r.ch); const sub=document.createElement('span');sub.className='result-sub';sub.textContent=r.type==='category'?t('categoryBadge'):catLabel(r.key); const badge=document.createElement('span');badge.className='result-badge';badge.textContent=r.type==='category'?t('categoryBadge'):sourceCountLabel(r.ch.l.length); main.append(name,sub);b.append(icon,main,badge); b.onclick=()=>{els.results.classList.remove('show');if(r.type==='category'){state.category=r.key;state.favoritesOnly=false;renderFilters();state.query='';els.search.value='';renderGrid();scrollToChannels()}else{playChannel(r.key,r.ch)}}; els.results.appendChild(b); }); els.results.classList.add('show'); }
function openCommand(){els.commandBackdrop.classList.add('show');els.commandBackdrop.setAttribute('aria-hidden','false');els.commandInput.value='';renderCommand('');setTimeout(()=>els.commandInput.focus(),30)} function closeCommand(){els.commandBackdrop.classList.remove('show');els.commandBackdrop.setAttribute('aria-hidden','true')} function commandItems(q){ const base=[ {label:t('cmdHome'),hint:t('cmdHomeHint'),run:()=>scrollToId('home')}, {label:t('cmdPlayer'),hint:t('cmdPlayerHint'),run:()=>scrollToId('player')}, {label:t('cmdExplore'),hint:t('cmdExploreHint'),run:()=>scrollToId('explore')}, ...(state.user?[{label:t('cmdFavorites'),hint:t('cmdFavoritesHint'),run:()=>{state.favoritesOnly=true;renderFilters();renderGrid();scrollToChannels()}}]:[]), {label:t('cmdTheme'),hint:t('cmdThemeHint'),run:()=>setTheme(!state.isDark,true,true)}, ]; const n=normalizeArabic(q);const matches=n?searchAll(n).filter(x=>x.type==='channel').slice(0,10).map(x=>({label:chLabel(x.ch),hint:catLabel(x.key),run:()=>playChannel(x.key,x.ch)})):[]; return [...base,...matches].slice(0,14) } function renderCommand(q){ els.commandBody.replaceChildren();commandItems(q).forEach((it,i)=>{const b=document.createElement('button');b.className='command-item'+(i===0?' active':'');const icon=document.createElement('span');icon.className='result-icon';icon.textContent=i<5?'⌘':'▶';const c=document.createElement('span');c.innerHTML='<strong style="font-size:11px">'+escapeHTML(it.label)+'</strong><span style="display:block;color:var(--text-3);font-size:9px">'+escapeHTML(it.hint)+'</span>';const k=document.createElement('span');k.className='command-key';k.textContent=i===0?'Enter':'';b.append(icon,c,k);b.onclick=()=>{it.run();closeCommand()};els.commandBody.appendChild(b)}) }
// ── Robust channel/category image loader: cleans the URL, tries it directly, then via an image proxy ── function imgClean(u){ u=String(u||'').trim().replace(/^["']+|["']+$/g,''); if(!u)return ''; if(u.indexOf('//')===0)u='https:'+u; if(/^http:\/\//i.test(u))u='https://'+u.slice(7); let m=u.match(/drive\.google\.com\/file\/d\/([\w-]+)/)||u.match(/drive\.google\.com\/(?:open|uc)\?(?:[^#]*&)?id=([\w-]+)/); if(m)return 'https://lh3.googleusercontent.com/d/'+m[1]; m=u.match(/^https?:\/\/(?:www\.)?imgur\.com\/(?!a\/|gallery\/)(\w+)$/i); if(m)return 'https://i.imgur.com/'+m[1]+'.png'; if(/dropbox\.com/i.test(u))u=u.replace(/[?&]dl=0/,'').replace('www.dropbox.com','dl.dropboxusercontent.com'); return u; } function imgProxy(u){return 'https://wsrv.nl/?url='+encodeURIComponent(u.replace(/^https?:\/\//i,''))+'&w=256&h=256&fit=cover&output=webp'} function loadImg(im,url,onok,onfail){ const u=imgClean(url);if(!u){if(onfail)onfail();return} const tries=[u]; if(/hyphenhyphen/.test(u))tries.push(u.replace(/hyphenhyphen/g,'--')); if(!/^https:\/\/(wsrv\.nl|images\.weserv\.nl)\//i.test(u))tries.push(imgProxy(u)); let i=0; const next=()=>{if(i>=tries.length){if(onfail)onfail();return}im.src=tries[i++]}; im.onload=()=>{if(onok)onok()}; im.onerror=next; next(); } // صورة القسم (img داخل القسم في db) تحل محل العلم؛ إن كانت فارغة أو فشل تحميلها يبقى العلم. function catIco(el,cat,css){ if(!el||!cat||!cat.img)return; const im=new Image();im.alt='';im.decoding='async';im.referrerPolicy='no-referrer'; im.style.cssText=css||'width:100%;height:100%;object-fit:cover;border-radius:inherit'; loadImg(im,cat.img,()=>{el.textContent='';el.appendChild(im)},()=>{try{console.warn('category image failed to load:',cat.img)}catch(_){}}); } function escapeHTML(value){return String(value).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))} function scrollToId(id){ if(id==='player'){if(isWatchView())return;const w=state.lastWatch;if(w){playChannel(w.key,w.ch);return}id='channels'} if(isWatchView())closeWatchView(false); const el=byId(id);if(el)el.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})} function scrollToChannels(){scrollToId('channels')}
function setSignal(stateName,label){ els.signalDot.className='signal-dot'+(stateName==='bad'?' bad':stateName==='warn'?' warn':''); els.signalText.textContent=label; }
function updatePlayIcon(){els.play.innerHTML=els.video.paused?ICONS.play:ICONS.pause} function updateMuteIcon(){const isMuted=curMuted()||curVol()===0;els.mute.innerHTML=isMuted?ICONS.mute:ICONS.volume;els.mute.setAttribute('aria-pressed',String(isMuted))}
function adjustVolume(delta){ state.volume=Math.min(1,Math.max(0,curVol()+delta));state.muted=false;applyVol(); try{localStorage.setItem('sg_volume',String(state.volume));localStorage.setItem('sg_muted','0')}catch(_){} updateMuteIcon();showToast(t('volumeLabel')+': '+Math.round(state.volume*100)+(state.lang==='en'?'%':'٪'),900); }
function captureScreenshot(){ const v=els.video; if(!v||!v.videoWidth){showToast(t('noStreamToCapture'));return} try{ const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight; c.getContext('2d').drawImage(v,0,0,c.width,c.height); const url=c.toDataURL('image/png'); const a=document.createElement('a');a.href=url;a.download='SAMI_Shot_'+Date.now()+'.png';a.click(); showToast(t('screenshotSaved')); }catch(_){showToast(t('screenshotFailed'))} }
function destroyHls(){destroyAudio();clearTimeout(state.reconnectTimer);if(state.hls){try{state.hls.destroy()}catch(_){}state.hls=null}if(state.blobUrl){try{URL.revokeObjectURL(state.blobUrl)}catch(_){}state.blobUrl=null}state.merged=false}
// Merged mode (preferred): a tiny master playlist declares the audio playlist as the audio group of the // video playlist, so hls.js plays both in ONE player and ONE <video>. Sound and picture can never drift, // and when the picture buffers the sound stops with it and resumes together. Dual mode below is the fallback. const NOREF={progressive:true,fetchSetup:(c,i)=>{try{i.referrerPolicy='no-referrer'}catch(_){}return new Request(c.url,i)}}; function mergedMaster(src){ try{ const kb=(/(\d+)kbps/.exec(src.u)||[])[1],bw=(kb?Number(kb):1500)*1000+192000; const txt='#EXTM3U\n#EXT-X-VERSION:4\n' +'#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="aud",NAME="Audio",LANGUAGE="ar",DEFAULT=YES,AUTOSELECT=YES,URI="'+src.a+'"\n' +'#EXT-X-STREAM-INF:BANDWIDTH='+bw+',AUDIO="aud"\n'+src.u+'\n'; state.blobUrl=URL.createObjectURL(new Blob([txt],{type:'application/vnd.apple.mpegurl'})); return state.blobUrl }catch(_){return null} }
// ── Split audio + video: a separate audio playlist is merged with whichever video quality is playing. ── // The <video> stays silent; a hidden Audio element plays the audio playlist and is kept in sync. // Audio pauses the instant the video starts buffering and resumes (re-aligned) when the picture is back. function curMuted(){return state.split?state.muted:els.video.muted} function curVol(){return state.split?state.volume:els.video.volume} function applyVol(){ const v=Math.min(1,Math.max(0,state.volume));els.video.volume=v; if(state.split&&state.audEl){els.video.muted=true;state.audEl.muted=state.muted;state.audEl.volume=v} else els.video.muted=state.muted } function audioPause(){const a=state.audEl;if(a&&!a.paused){try{a.pause()}catch(_){}}} function alignAudio(force){ const a=state.audEl,v=els.video;if(!a)return; try{if(isFinite(v.currentTime)&&isFinite(a.currentTime)&&(force||Math.abs(v.currentTime-a.currentTime)>0.35))a.currentTime=v.currentTime}catch(_){} } function audioResume(){ const a=state.audEl,v=els.video;if(!state.split||!a)return; if(v.paused||v.ended||v.seeking||state.vBuf||v.readyState<3)return; if(a.paused){alignAudio(true);const pr=a.play();if(pr&&pr.catch)pr.catch(()=>{})} } function audioGate(){ const a=state.audEl,v=els.video;if(!state.split||!a)return; if(v.paused||v.ended||v.seeking||state.vBuf)audioPause();else audioResume() } // periodic tick: re-align when drift exceeds 0.35s, and retry playback if the first play() was refused function syncAudio(){ const a=state.audEl,v=els.video;if(!state.split||!a||v.paused||state.vBuf)return; if(a.paused)audioResume();else alignAudio(false) } function handleAudioError(d){ if(!d||!d.fatal||!state.audHls)return;const ah=state.audHls; if(d.type===Hls.ErrorTypes.NETWORK_ERROR&&(state.audRetries=(state.audRetries||0)+1)<=5){ clearTimeout(state.audRetry);state.audRetry=setTimeout(()=>{if(state.audHls===ah)ah.startLoad()},Math.min(1200*state.audRetries,6000));return } if(d.type===Hls.ErrorTypes.MEDIA_ERROR&&(state.audMedia=(state.audMedia||0)+1)<=3){ah.recoverMediaError();return} showToast(state.lang==='en'?'Audio track failed to load':'تعذر تحميل مسار الصوت') } function startAudio(aUrl){ let a=state.audEl;if(!a){a=state.audEl=document.createElement('audio');a.preload='auto';a.style.display='none';a.setAttribute('playsinline','');document.body.appendChild(a)} state.audRetries=0;state.audMedia=0;state.vBuf=false; if(window.Hls&&Hls.isSupported()){ state.split=true;applyVol(); const ah=new Hls(Object.assign({enableWorker:true,lowLatencyMode:true,maxBufferLength:24,maxMaxBufferLength:48,backBufferLength:8},NOREF)); state.audHls=ah;ah.attachMedia(a); ah.on(Hls.Events.MEDIA_ATTACHED,()=>ah.loadSource(aUrl)); ah.on(Hls.Events.MANIFEST_PARSED,audioGate); ah.on(Hls.Events.ERROR,(_,d)=>handleAudioError(d)) }else if(a.canPlayType('application/vnd.apple.mpegurl')){ state.split=true;applyVol();a.src=aUrl }else return; clearInterval(state.audSync);state.audSync=setInterval(syncAudio,1000) } function destroyAudio(){ clearTimeout(state.vBufT);clearInterval(state.audSync);clearTimeout(state.audRetry); if(state.audHls){try{state.audHls.destroy()}catch(_){}state.audHls=null} if(state.audEl){try{state.audEl.pause();state.audEl.removeAttribute('src');state.audEl.load()}catch(_){}} state.split=false;state.vBuf=false;try{els.video.muted=state.muted}catch(_){} }
// ===== SAMI v13: Cloudflare Worker HLS proxy ===== // ضع رابط الـ Worker هنا (بدون / في النهاية). اتركه فارغًا لتعطيل الوسيط. const HLS_PROXY='https://bitter-brook-6557.alhydrys220.workers.dev'; // نطاقات تمر دائمًا عبر الوسيط: const PROXY_HOSTS=[]; // أو أضف px:true داخل القناة (على مستوى القناة) أو داخل مصدر معيّن في l const viaProxy=(u,force)=>{ if(!HLS_PROXY||!u||u.indexOf(HLS_PROXY)===0)return u; try{const h=new URL(u).hostname; if(force||PROXY_HOSTS.some(d=>h===d||h.endsWith('.'+d)))return HLS_PROXY+'/?url='+encodeURIComponent(u)}catch(_){} return u; }; function sourcesFor(ch){return Array.isArray(ch?.l)?ch.l.filter(x=>x&&x.u).map(x=>{ const f=!!(x.px||ch.px); const y=(x.a||!ch.a)?x:Object.assign({},x,{a:ch.a}); const u2=viaProxy(y.u,f),a2=y.a?viaProxy(y.a,f):y.a; return (u2===y.u&&a2===y.a)?y:Object.assign({},y,{u:u2,a:a2}); }):[]}
function updateQualityList(ch){ els.qualityList.replaceChildren(); const sources=sourcesFor(ch);els.sourceLabel.textContent=sources.length?sourceCountLabel(sources.length):'—'; if(!sources.length){const e=document.createElement('div');e.className='empty';e.style.padding='22px';e.textContent=t('noSourcesForItem');els.qualityList.appendChild(e);return} sources.forEach((src,i)=>{ const b=document.createElement('button');b.className='quality-btn'+(i===state.failoverIndex?' active':''); const n=document.createElement('span');n.textContent=src.q?qLabel(src.q):(t('sourceOrdinalPrefix')+(i+1)); const q=document.createElement('span');q.className='q-mark';q.textContent=i===state.failoverIndex?t('activeMark'):t('playMark'); b.append(n,q);b.onclick=()=>loadSource(i); els.qualityList.appendChild(b) }) }
function setUrlState(key,name){ const url=new URL(location.href);url.searchParams.set('channel',key);url.searchParams.set('name',name);history.replaceState(Object.assign({},history.state||{},{channel:key,name}),'',url) }
// ===== Dedicated watch page (player + channel + related features) ===== function isWatchView(){return document.documentElement.getAttribute('data-view')==='watch'} function openWatchView(){ const wv=byId('watchView'),hv=byId('homeView');if(!wv||!hv)return; if(!isWatchView()){ state.homeScroll=window.scrollY||0; try{history.pushState({view:'watch'},'',location.href)}catch(_){} } hv.hidden=true;wv.hidden=false; document.documentElement.setAttribute('data-view','watch'); $$('[data-mobile]').forEach(x=>x.classList.toggle('active',x.dataset.mobile==='player')); window.scrollTo(0,0); } function closeWatchView(restore){ if(!isWatchView())return; const wv=byId('watchView'),hv=byId('homeView'); if(!document.pictureInPictureElement){ try{destroyHls()}catch(_){} try{els.video.pause();els.video.removeAttribute('src');els.video.load()}catch(_){} } if(document.fullscreenElement){try{document.exitFullscreen()}catch(_){}} if(wv)wv.hidden=true;if(hv)hv.hidden=false; document.documentElement.removeAttribute('data-view'); document.documentElement.removeAttribute('data-watching'); document.body.classList.remove('is-watching'); try{const u=new URL(location.href);u.searchParams.delete('channel');u.searchParams.delete('name');history.replaceState(Object.assign({},history.state||{},{view:null}),'',u)}catch(_){} $$('[data-mobile]').forEach(x=>x.classList.toggle('active',x.dataset.mobile==='home')); window.scrollTo(0,restore?(state.homeScroll||0):0); } function renderWatchExtras(){ const w=state.lastWatch;if(!w)return; const fav=byId('watchFav'); if(fav){const on=!!(state.favs&&state.favs[favKey(w.key,w.ch.n)]);fav.setAttribute('aria-pressed',on?'true':'false');const ic=fav.querySelector('.fav-ico');if(ic)ic.textContent=on?'★':'☆'} const sec=byId('relatedSection'),track=byId('relatedTrack');if(!sec||!track)return; track.replaceChildren(); const list=(db[w.key]?db[w.key].c:[]).filter(x=>x.n!==w.ch.n).slice(0,30); sec.hidden=!list.length; list.forEach(ch=>{ const b=document.createElement('button');b.className='history-item';b.type='button'; const av=document.createElement('span');av.className='history-avatar';av.textContent=db[w.key].i||'◉';av.style.overflow='hidden';if(!ch.img)catIco(av,db[w.key]); const im0=imgClean(ch.img); if(im0){const im=new Image();im.alt='';im.loading='lazy';im.decoding='async';im.referrerPolicy='no-referrer';im.style.cssText='width:100%;height:100%;object-fit:cover;border-radius:inherit';im.onload=()=>{av.textContent='';av.appendChild(im)};im.src=im0} const c=document.createElement('span');c.className='history-copy'; const n=document.createElement('span');n.className='history-name';n.textContent=nameLabel(ch.n); const sub=document.createElement('span');sub.className='history-cat';sub.textContent=catLabel(w.key); c.append(n,sub);b.append(av,c);b.onclick=()=>playChannel(w.key,ch); track.appendChild(b); }); } function setupWatchView(){ const back=byId('watchBack'); if(back)back.onclick=()=>{if(history.state&&history.state.view==='watch')history.back();else closeWatchView(true)}; const fav=byId('watchFav'); if(fav)fav.onclick=()=>{const w=state.lastWatch;if(!w)return;toggleFav(w.key,w.ch.n);renderWatchExtras()}; window.addEventListener('popstate',e=>{ if(e.state&&e.state.view==='watch'){const w=state.lastWatch;if(!isWatchView()&&w)playChannel(w.key,w.ch)} else closeWatchView(true); }); document.addEventListener('click',e=>{ if(!isWatchView())return; const a=e.target.closest&&e.target.closest('a.brand,a[href^="#"]'); if(!a||a.closest('#watchView'))return; e.preventDefault(); const id=a.classList.contains('brand')?'home':((a.getAttribute('href')||'#home').slice(1)||'home'); closeWatchView(false);requestAnimationFrame(()=>scrollToId(id)); },true); }
function findFromUrl(){ const url=new URL(location.href);const key=url.searchParams.get('channel');const name=url.searchParams.get('name'); if(!key||!name||!db[key])return null;const ch=db[key].c.find(x=>x.n===name);return ch?{key,ch}:null }
function playChannel(key,ch){ if(!db[key]||!ch)return; if(!state.user){promptAccountForChannel(key,ch);return} const wasSections=!state.category&&!state.favoritesOnly&&!state.query; els.video.poster=imgClean(ch.img)||DEFAULT_POSTER; state.category=key;state.channel=ch;state.query='';els.search.value='';state.favoritesOnly=false;state.failoverIndex=0; document.documentElement.setAttribute('data-watching','1'); document.body.classList.add('is-watching'); const nowAvatar=byId('nowAvatar'); if(nowAvatar){ nowAvatar.style.backgroundImage=''; nowAvatar.textContent=(db[key]&&db[key].i)?db[key].i:'◉'; if(!ch.img&&db[key]&&db[key].img){try{const cu=imgClean(db[key].img);if(cu){nowAvatar.style.backgroundImage="url('"+cu.replace(/'/g,"%27")+"')";nowAvatar.textContent=''}}catch(_){}} if(ch.img){ try{ const avatarUrl=imgClean(ch.img); if(avatarUrl){ nowAvatar.style.backgroundImage="url('"+avatarUrl.replace(/'/g,"%27")+"')"; nowAvatar.textContent=''; } }catch(_){} } } els.placeholder.hidden=true; if(els.placeholderRetry)els.placeholderRetry.hidden=true; if(els.placeholderTitle)els.placeholderTitle.textContent=t('placeholderTitleDefault'); if(els.placeholderText)els.placeholderText.textContent=t('placeholderTextDefault'); els.nowTitle.textContent=chLabel(ch);els.nowMeta.textContent=catLabel(key)+' · '+sourceCountLabel(sourcesFor(ch).length);els.playerMeta.textContent=t('currentContentPrefix')+catLabel(key); updateQualityList(ch);pushHistory(key,ch);state.lastWatch={key,ch};openWatchView();setUrlState(key,ch.n);loadSource(0);renderWatchExtras(); if(window.SamiComments)SamiComments.onChannel(key,ch); if(wasSections){renderFilters();renderGrid()} } // Watching a channel requires a signed-in Google account; browsing, search, and // favorites stay open to everyone. The requested channel is remembered and played // automatically once sign-in succeeds (including an already-signed-in session that // is still resolving when the page loads). function promptAccountForChannel(key,ch){ state.pendingPlay={key,ch}; const showPrompt=()=>{ if(state.user)return; // session restored: onAuthStateChanged plays the pending channel showToast(t('accountRequiredToast')); if(els.accountBackdrop){els.accountBackdrop.classList.add('show');els.accountBackdrop.setAttribute('aria-hidden','false')} }; if(authResolved){showPrompt();return} ensureFirebaseAuthReady().then(ready=>ready?waitForAuth(8000):null).then(showPrompt,showPrompt); }
function loadSource(index,mode){ if(!state.channel)return;const sources=sourcesFor(state.channel);if(!sources[index])return; state.failoverIndex=index;state.reconnectAttempts=0;updateQualityList(state.channel);setSignal('warn',t('connecting'));els.placeholder.hidden=true;destroyHls();state.mergedFallback=(mode==='dual'); const url=sources[index].u;const tok=state.loadTok=(state.loadTok||0)+1; const start=()=>{ if(tok!==state.loadTok)return; try{ if(window.Hls&&Hls.isSupported()){ let src=url;if(sources[index].a&&mode==='merged'){const m=mergedMaster(sources[index]);if(m){src=m;state.merged=true}} const h=new Hls(Object.assign({enableWorker:true,lowLatencyMode:true,maxBufferLength:24,maxMaxBufferLength:48,backBufferLength:8,capLevelToPlayerSize:true},sources[index].a?NOREF:{})); state.hls=h; h.attachMedia(els.video); h.on(Hls.Events.MEDIA_ATTACHED,()=>h.loadSource(src)); h.on(Hls.Events.MANIFEST_PARSED,()=>{state.reconnectAttempts=0;setSignal('good',t('stableSignal'));els.video.play().catch(()=>{});updatePlayIcon()}); h.on(Hls.Events.ERROR,(_,data)=>handleHlsError(data,index)); if(sources[index].a&&!state.merged)startAudio(sources[index].a); }else if(els.video.canPlayType('application/vnd.apple.mpegurl')){ els.video.src=url;if(sources[index].a)startAudio(sources[index].a);els.video.play().catch(()=>{});setSignal('good',t('nativePlayback')); }else{ setSignal('bad',t('noHlsSupport'));showToast(t('noHlsToast'));return; } }catch(err){handleSourceFailure(index,err)} }; ensureHls().then(start,start); }
let hlsPromise=null; function ensureHls(){ if(window.Hls)return Promise.resolve(); if(hlsPromise)return hlsPromise; hlsPromise=new Promise((resolve,reject)=>{ const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/hls.js@1.7.3/dist/hls.min.js';sc.async=true; sc.onload=()=>resolve();sc.onerror=()=>{hlsPromise=null;reject(new Error('hls-load-failed'))}; document.head.appendChild(sc); }); return hlsPromise; }
function handleHlsError(data,index){ if(!data||!data.fatal)return; try{console.warn('[SAMI hls]',data.type,data.details,data.response&&data.response.code,data.url)}catch(_){} if(state.merged&&!state.mergedFallback&&/manifest|level|audioTrack|bufferAddCodec|bufferIncompatible/i.test(data.details||'')){loadSource(index,'dual');return} if(data.type===Hls.ErrorTypes.NETWORK_ERROR&&state.hls){ state.reconnectAttempts=(state.reconnectAttempts||0)+1; if(state.reconnectAttempts<=5){ setSignal('warn',(state.lang==='en'?'Reconnecting (':'إعادة الاتصال (')+state.reconnectAttempts+'/5) '+(data.details||'')+(data.response&&data.response.code?' '+data.response.code:'')); clearTimeout(state.reconnectTimer); state.reconnectTimer=setTimeout(()=>{if(state.hls)state.hls.startLoad()},Math.min(1200*state.reconnectAttempts,6000)); return; } } if(data.type===Hls.ErrorTypes.MEDIA_ERROR&&state.hls){setSignal('warn',t('recovering'));state.hls.recoverMediaError();return} handleSourceFailure(index,data) }
function showPlaceholderError(title,text){ destroyHls(); if(els.placeholderTitle)els.placeholderTitle.textContent=title; if(els.placeholderText)els.placeholderText.textContent=text; if(els.placeholderRetry)els.placeholderRetry.hidden=false; els.placeholder.hidden=false; }
function handleSourceFailure(index,_err){ setSignal('bad',t('sourceFailed')+(_err&&_err.details?' · '+_err.details+(_err.response&&_err.response.code?' '+_err.response.code:''):'')); const sources=sourcesFor(state.channel); if(index+1<sources.length&&index<CONFIG.maxFailovers){ showToast(t('switchingSource')); setTimeout(()=>loadSource(index+1),650); }else{ showToast(t('allSourcesFailed')); showPlaceholderError(t('itemFailedTitle'),t('itemFailedText')); } }
function setupPlayer(){ els.video.volume=Math.min(1,Math.max(0,state.volume));els.video.muted=state.muted;updatePlayIcon();updateMuteIcon(); els.play.onclick=()=>{if(els.video.paused)els.video.play().catch(()=>{});else els.video.pause()}; els.mute.onclick=()=>{state.muted=!curMuted();applyVol();localStorage.setItem('sg_muted',state.muted?'1':'0');updateMuteIcon()}; els.fullscreen.onclick=async()=>{try{if(!document.fullscreenElement)await els.playerFrame.requestFullscreen();else await document.exitFullscreen()}catch(_) {}} if(!document.pictureInPictureEnabled)els.pip.style.display='none';else els.pip.onclick=async()=>{try{if(document.pictureInPictureElement)await document.exitPictureInPicture();else await els.video.requestPictureInPicture()}catch(_) {}} els.share.onclick=shareCurrent; if(els.screenshot)els.screenshot.onclick=captureScreenshot; if(els.placeholderRetry)els.placeholderRetry.onclick=()=>{if(state.channel){els.placeholderRetry.hidden=true;els.placeholder.hidden=true;loadSource(0)}}; els.record.onclick=toggleRecording; els.video.addEventListener('play',()=>{updatePlayIcon();setSignal('good',t('playbackStable'));hideOverlayLater()}); els.video.addEventListener('pause',()=>{updatePlayIcon();showOverlay()}); const bufStart=()=>{clearTimeout(state.vBufT);state.vBuf=true;audioPause()}; els.video.addEventListener('waiting',()=>{bufStart();setSignal('warn',t('loadingStream'))}); els.video.addEventListener('stalled',()=>{if(state.split&&!els.video.paused)bufStart()}); els.video.addEventListener('suspend',()=>{if(state.split&&!els.video.paused&&els.video.readyState<3)bufStart()}); ['play','pause','seeking','seeked'].forEach(ev=>els.video.addEventListener(ev,audioGate)); els.video.addEventListener('playing',()=>{clearTimeout(state.vBufT);state.vBufT=setTimeout(()=>{state.vBuf=false;audioGate()},150);setSignal('good',t('playbackStable'));hideOverlayLater()}); els.video.addEventListener('error',()=>setSignal('bad',t('mediaError'))); els.video.addEventListener('timeupdate',()=>{if(els.video.duration&&Number.isFinite(els.video.duration))els.fill.style.width=((els.video.currentTime/els.video.duration)*100)+'%';else els.fill.style.width='100%'}); els.progress.onclick=e=>{if(els.video.duration&&Number.isFinite(els.video.duration)){const r=els.progress.getBoundingClientRect();els.video.currentTime=((e.clientX-r.left)/r.width)*els.video.duration}}; ['pointermove','pointerdown','mouseenter'].forEach(ev=>els.playerFrame.addEventListener(ev,showOverlay)); els.playerFrame.addEventListener('mouseleave',()=>{if(!els.video.paused)hideOverlayLater()}); } function showOverlay(){els.overlay.classList.remove('hide');clearTimeout(state.controlTimer)} function hideOverlayLater(){clearTimeout(state.controlTimer);state.controlTimer=setTimeout(()=>{if(!els.video.paused)els.overlay.classList.add('hide')},2600)}
async function shareCurrent(){ const title=chLabel(state.channel)||'SAMI';const url=location.href;const data={title,text:t('watchNow')+' '+title+' '+t('nowSuffix'),url}; try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(url);showToast(t('linkCopied'))}}catch(_){} }
function toggleRecording(){ if(state.recorder&&state.recorder.state==='recording'){state.recorder.stop();els.record.classList.remove('recording');showToast(t('recordingDone'));return} const stream=els.video.captureStream?els.video.captureStream():null;if(!stream){showToast(t('recordingUnsupported'));return} if(state.split&&state.audEl&&state.audEl.captureStream){try{state.audEl.captureStream().getAudioTracks().forEach(t=>stream.addTrack(t))}catch(_){}} try{ state.chunks=[];state.recorder=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm'}); state.recorder.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data)}; state.recorder.onstop=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(state.chunks,{type:'video/webm'}));a.download='SAMI_Record_'+Date.now()+'.webm';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}; state.recorder.start(1000);els.record.classList.add('recording');showToast(t('recordingInProgress')); }catch(_){showToast(t('recordingFailed'))} }
function renderCommandShortcut(){if(window.innerWidth>800)byId('openCommand').title=t('quickSearchShortcut')}
function setupSearch(){ els.search.addEventListener('input',()=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>{renderSearchResults();renderGrid()},120)}); els.search.addEventListener('focus',()=>{if(els.search.value.trim())renderSearchResults()}); document.addEventListener('click',e=>{if(!e.target.closest('.search-box'))els.results.classList.remove('show')}); }
function setupShortcuts(){ document.addEventListener('keydown',e=>{ if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand();return} if(e.key==='Escape'){closeCommand();closeModal();return} const tag=(e.target?.tagName||'').toLowerCase();if(tag==='input'||tag==='textarea')return; if(e.code==='Space'){e.preventDefault();els.play.click()} else if(e.key.toLowerCase()==='f'){els.fullscreen.click()} else if(e.key.toLowerCase()==='m'){els.mute.click()} else if(e.key==='ArrowUp'&&els.playerFrame.contains(document.activeElement)){e.preventDefault();adjustVolume(0.1)} else if(e.key==='ArrowDown'&&els.playerFrame.contains(document.activeElement)){e.preventDefault();adjustVolume(-0.1)} }); }
function setupTheme(){ setTheme(state.isDark,false,false); byId('themeToggle').onclick=()=>setTheme(!state.isDark,true,true); // Until the visitor picks a theme manually, follow the device's day/night setting live try{ const mq=window.matchMedia('(prefers-color-scheme: light)'); const onSys=e=>{let saved=null;try{saved=localStorage.getItem(CONFIG.storageTheme)}catch(_){}if(!saved)setTheme(!e.matches,false,true)}; if(mq.addEventListener)mq.addEventListener('change',onSys);else if(mq.addListener)mq.addListener(onSys); }catch(_){} } function syncThemeButton(){const b=byId('themeToggle');if(b)b.setAttribute('aria-pressed',String(!state.isDark))}
function setupDialogs(){ byId('openCommand').onclick=openCommand;byId('heroSearchBtn').onclick=openCommand;byId('quickCommand').onclick=openCommand; byId('quickFavs').onclick=()=>{if(!state.user)return;state.favoritesOnly=true;renderFilters();renderGrid();scrollToChannels()}; byId('quickHistory').onclick=()=>scrollToId('recentSection'); els.commandBackdrop.addEventListener('click',e=>{if(e.target===els.commandBackdrop)closeCommand()}); els.commandInput.addEventListener('input',e=>renderCommand(e.target.value)); byId('aboutBtn').onclick=()=>{els.modalBackdrop.classList.add('show');els.modalBackdrop.setAttribute('aria-hidden','false')}; byId('closeModal').onclick=closeModal;els.modalBackdrop.addEventListener('click',e=>{if(e.target===els.modalBackdrop)closeModal()}); } function closeModal(){els.modalBackdrop.classList.remove('show');els.modalBackdrop.setAttribute('aria-hidden','true')}
function setupMobileNav(){ $$('[data-mobile]').forEach(b=>b.addEventListener('click',()=>{ $$('[data-mobile]').forEach(x=>x.classList.remove('active'));b.classList.add('active'); const key=b.dataset.mobile;if(key==='home')scrollToId('home');if(key==='search'){scrollToId('explore');setTimeout(()=>els.search.focus(),250)}if(key==='favorites'){if(!state.user)return;state.favoritesOnly=true;renderFilters();renderGrid();scrollToChannels()}if(key==='player')scrollToId('player') })) }
function setupCardGlow(){ if(!window.matchMedia('(hover:hover) and (pointer:fine)').matches)return; if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return; document.addEventListener('pointermove',e=>{ const card=e.target.closest('.quick-card,.channel-card'); if(!card)return; const r=card.getBoundingClientRect(); const px=(e.clientX-r.left),py=(e.clientY-r.top); card.style.setProperty('--mx',px+'px'); card.style.setProperty('--my',py+'px'); const nx=(px/r.width)-.5,ny=(py/r.height)-.5; card.style.setProperty('--rx',(nx*6).toFixed(2)+'deg'); card.style.setProperty('--ry',(ny*-6).toFixed(2)+'deg'); },{passive:true}); document.addEventListener('pointerleave',e=>{ const card=e.target.closest&&e.target.closest('.quick-card,.channel-card'); if(!card)return; card.style.setProperty('--rx','0deg'); card.style.setProperty('--ry','0deg'); },true); }
function setupReveal(){ const targets=$$('.reveal'); if(!targets.length)return; const obs=new IntersectionObserver(entries=>{ entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('in');obs.unobserve(en.target)}}); },{threshold:.12,rootMargin:'0px 0px -10% 0px'}); targets.forEach(el=>obs.observe(el)); }
function setupNavSpy(){ const sections=['home','player','explore','channels','siteComments'];const links=$$('.nav-link'); const obs=new IntersectionObserver(entries=>entries.forEach(en=>{if(en.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.dataset.nav===en.target.id))}}),{rootMargin:'-20% 0px -65% 0px',threshold:0}); sections.map(byId).filter(Boolean).forEach(el=>obs.observe(el)); }
function setupPresenceHook(){ // No fake counter. A real endpoint can be configured later without changing the UI contract. if(!CONFIG.presenceEndpoint)return; try{ const ping=()=>fetch(CONFIG.presenceEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({page:location.pathname,ts:Date.now()})}).catch(()=>{}); ping();setInterval(ping,25000); }catch(_){} }
function setupAbout(){ byId('backToCats').onclick=()=>{goSections();scrollToChannels()}; const all=document.querySelector('a.quick-card[href="#channels"]');if(all)all.addEventListener('click',goSections); $$('[data-open]').forEach(b=>b.addEventListener('click',()=>{const d=byId(b.dataset.open);if(!d)return;d.open=true;scrollToId(b.dataset.open)})); }
// Heavy third-party work (Firebase SDK, live counters, auth, hls.js) starts only after the // first interaction or shortly after the page has loaded, so the first paint is fast. function deferredBoot(){ if(state.booted)return;state.booted=true; setupFirebaseCounters();ensureFirebaseAuthReady();ensureHls().catch(()=>{}); } function scheduleBoot(){ const evs=['pointerdown','keydown','scroll','touchstart']; const go=()=>{evs.forEach(ev=>removeEventListener(ev,go));deferredBoot()}; evs.forEach(ev=>addEventListener(ev,go,{passive:true})); const idle=()=>setTimeout(deferredBoot,1800); if(document.readyState==='complete')idle();else addEventListener('load',idle,{once:true}); }
// ===== SAMI comments v1: per-channel comments + site wall (members only, Firebase Realtime DB) ===== // Data: channelComments/<channelId>/<id> siteComments/<id> siteSupport/<uid> publicProfiles/<uid> admins/<uid> // Reading is public; writing needs a signed-in account (enforced by the Firebase rules given in the reply). const CM={pageSize:40,cooldown:15000,maxLen:500,emojis:['😀','😂','😍','🥰','😎','🤩','👏','🙏','💪','🔥','❤️','💚','⭐','🎉','👍','⚽','📺','🌹']}; const CMS={ ar:{ chKicker:'CHANNEL COMMENTS',chTitle:'تعليقات القناة',chSub:'للأعضاء أصحاب الحسابات فقط', siteKicker:'COMMUNITY WALL',siteTitle:'آراء وتعليقات الزوار',siteSub:'شاركنا رأيك أو ادعم الموقع', phCh:'اكتب تعليقك عن هذه القناة…',phSite:'شاركنا رأيك أو اترك رسالة دعم للموقع…',phReply:'اكتب ردّك…', send:'نشر التعليق',sending:'جارٍ النشر…',reply:'رد',cancel:'إلغاء',del:'حذف',delConfirm:'حذف هذا التعليق نهائيًا؟', support:'دعم',lockedTitle:'التعليقات للأعضاء فقط', lockedCh:'أنشئ حسابًا أو سجّل الدخول لتتمكن من التعليق على هذه القناة.', lockedSite:'أنشئ حسابًا أو سجّل الدخول لتترك تعليقك وتدعم الموقع.', signIn:'تسجيل الدخول / إنشاء حساب',empty:'لا توجد تعليقات بعد — كن أول من يعلّق!', loading:'جارٍ تحميل التعليقات…',loadErr:'تعذّر تحميل التعليقات. تحقّق من الاتصال وقواعد قاعدة البيانات.', more:'عرض تعليقات أقدم',newest:'الأحدث',top:'الأكثر دعمًا', rate:'قيّم الموقع (اختياري)',owner:'المالك',orphan:'رد على تعليق محذوف', now:'الآن',tooFast:'انتظر بضع ثوانٍ قبل نشر تعليق جديد.',noLinks:'الروابط غير مسموحة في التعليقات.', emptyText:'اكتب تعليقًا أولًا.',postErr:'تعذّر النشر. تأكد من اتصالك وحاول مجددًا.',actErr:'تعذّر تنفيذ الإجراء.', sAvg:'متوسط التقييم',sCount:'تعليق',sFans:'داعم للموقع',supportSite:'ادعم الموقع',supportedSite:'شكرًا لدعمك!', thanks:'شكرًا لدعمك للموقع 💚',unsupported:'تم إلغاء الدعم',signInFirst:'سجّل الدخول أولًا.',chCount:'تعليق', you:'أنت',pending:'جارٍ التحقق من حسابك…',pin:'تثبيت',unpin:'إلغاء التثبيت',pinned:'📌 مثبّت',ban:'حظر',banConfirm:'حظر هذا المستخدم من التعليق؟ (سيُحذف تعليقه أيضًا)',banned:'تم حظر المستخدم',banErr:'أنت محظور من التعليق.' }, en:{ chKicker:'CHANNEL COMMENTS',chTitle:'Channel comments',chSub:'Registered members only', siteKicker:'COMMUNITY WALL',siteTitle:'Visitor comments & feedback',siteSub:'Share your thoughts or support the site', phCh:'Write your comment about this channel…',phSite:'Share your thoughts or leave a message of support…',phReply:'Write your reply…', send:'Post comment',sending:'Posting…',reply:'Reply',cancel:'Cancel',del:'Delete',delConfirm:'Delete this comment permanently?', support:'Support',lockedTitle:'Comments are for members only', lockedCh:'Create an account or sign in to comment on this channel.', lockedSite:'Create an account or sign in to leave a comment and support the site.', signIn:'Sign in / Create account',empty:'No comments yet — be the first!', loading:'Loading comments…',loadErr:'Could not load comments. Check your connection and database rules.', more:'Show older comments',newest:'Newest',top:'Most supported', rate:'Rate the site (optional)',owner:'Owner',orphan:'Reply to a deleted comment', now:'just now',tooFast:'Please wait a few seconds before posting again.',noLinks:'Links are not allowed in comments.', emptyText:'Write a comment first.',postErr:'Could not post. Check your connection and try again.',actErr:'Action failed.', sAvg:'Average rating',sCount:'comments',sFans:'site supporters',supportSite:'Support the site',supportedSite:'Thanks for your support!', thanks:'Thanks for supporting the site 💚',unsupported:'Support removed',signInFirst:'Please sign in first.',chCount:'comments', you:'You',pending:'Checking your account…',pin:'Pin',unpin:'Unpin',pinned:'📌 Pinned',ban:'Ban',banConfirm:'Ban this user from commenting? (their comment will be deleted too)',banned:'User banned',banErr:'You are banned from commenting.' } }; const cs=k=>((CMS[state.lang]||CMS.ar)[k])||CMS.ar[k]||k; let cmSite=null,cmChan=null,cmAdmin=false,cmLast=0,cmPub=null; const cmProf={},cmProfQ={}; function cmHash(str){let h1=0xdeadbeef,h2=0x41c6ce57;for(let i=0;i<str.length;i++){const c=str.charCodeAt(i);h1=Math.imul(h1^c,2654435761);h2=Math.imul(h2^c,1597334677)}h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return (4294967296*(2097151&h2)+(h1>>>0)).toString(36)} function cmChId(key,name){return 'c_'+cmHash(key+'::'+name)} function cmColor(uid){let h=0;uid=String(uid||'');for(let i=0;i<uid.length;i++)h=(h*31+uid.charCodeAt(i))>>>0;return 'hsl('+(h%360)+',52%,40%)'} function cmSafeSrc(s){return typeof s==='string'&&(s.indexOf('data:image/')===0||s.indexOf('https://')===0)&&!/["'\\\n\r]/.test(s)} function cmAgo(ts){ if(!ts)return cs('now'); const s=Math.round((ts-Date.now())/1000),a=Math.abs(s);let v,u; if(a<45)return cs('now'); if(a<3300){v=Math.round(s/60);u='minute'}else if(a<82800){v=Math.round(s/3600);u='hour'}else if(a<2160000){v=Math.round(s/86400);u='day'}else if(a<27000000){v=Math.round(s/2592000);u='month'}else{v=Math.round(s/31536000);u='year'} try{return new Intl.RelativeTimeFormat(state.lang==='en'?'en':'ar-u-nu-latn',{numeric:'auto'}).format(v,u)}catch(_){return new Date(ts).toLocaleDateString()} } function cmOpenAccount(){if(els.accountBackdrop){els.accountBackdrop.classList.add('show');els.accountBackdrop.setAttribute('aria-hidden','false')}} function cmThumb(dataUrl,size){ return new Promise((res,rej)=>{ const img=new Image(); img.onload=()=>{try{const side=Math.min(img.naturalWidth,img.naturalHeight)||1,sx=(img.naturalWidth-side)/2,sy=(img.naturalHeight-side)/2;const c=document.createElement('canvas');c.width=c.height=size;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,size,size);x.drawImage(img,sx,sy,side,side,0,0,size,size);res(c.toDataURL('image/jpeg',0.72))}catch(e){rej(e)}}; img.onerror=()=>rej(new Error('img'));img.src=dataUrl; }); } // Publishes a small public card (name + 96px avatar) so other visitors can see who wrote a comment. // The private profile under users/<uid> stays private; the e-mail is never published. async function cmEnsurePublic(){ const u=state.user;if(!u||!state.cloudDb)throw new Error('no-auth'); if(cmPub&&cmPub.uid===u.uid)return cmPub; let prof=(state.profile&&state.profile.uid===u.uid)?state.profile:null; if(!prof){try{prof=(await state.cloudDb.ref('users/'+u.uid+'/profile').once('value')).val()}catch(_){}} const name=String(u.displayName||(prof&&prof.name)||(u.email?u.email.split('@')[0]:'')||'مستخدم').trim().slice(0,40)||'مستخدم'; let photo=(prof&&prof.photo)||u.photoURL||''; if(photo&&photo.indexOf('data:image/')===0){try{photo=await cmThumb(photo,96)}catch(_){photo=''}} if(!cmSafeSrc(photo)||photo.length>50000)photo=''; const rec={name:name};if(photo)rec.photo=photo;if(cmAdmin)rec.badge='owner'; await state.cloudDb.ref('publicProfiles/'+u.uid).set(rec); cmProf[u.uid]=rec;cmPub={uid:u.uid,name:name}; return cmPub; } function cmLoadProfile(uid){ if(cmProf[uid]!==undefined)return Promise.resolve(cmProf[uid]); if(cmProfQ[uid])return cmProfQ[uid]; if(!state.cloudDb)return Promise.resolve(null); return (cmProfQ[uid]=state.cloudDb.ref('publicProfiles/'+uid).once('value').then(s=>(cmProf[uid]=s.val()||null)).catch(()=>(cmProf[uid]=null))); } function cmPaint(root){ root.querySelectorAll('.cm-av[data-uid]').forEach(el=>{ const uid=el.dataset.uid; el.style.backgroundColor=cmColor(uid); if(!el.textContent&&!el.style.backgroundImage)el.textContent=(el.dataset.name||'؟').trim().charAt(0).toUpperCase(); cmLoadProfile(uid).then(p=>{if(p&&cmSafeSrc(p.photo)){el.style.backgroundImage='url("'+p.photo+'")';el.textContent=''}}); }); root.querySelectorAll('.cm-badge[data-uid]').forEach(el=>{ cmLoadProfile(el.dataset.uid).then(p=>{if(p&&p.badge==='owner'){el.hidden=false;el.textContent=cs('owner')}}); }); } function cmBurst(btn){ if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return; const r=btn.getBoundingClientRect(),icons=['💚','✨','⭐','💙','🎉']; for(let i=0;i<12;i++){ const s=document.createElement('span');s.className='cm-burst';s.textContent=icons[i%icons.length]; s.style.left=(r.left+r.width/2)+'px';s.style.top=(r.top+r.height/2)+'px'; s.style.setProperty('--dx',(Math.random()*180-90)+'px');s.style.setProperty('--dy',(-50-Math.random()*110)+'px'); document.body.appendChild(s);setTimeout(()=>s.remove(),1100); } }
function cmThread(cfg){ const th={kind:cfg.kind,root:cfg.root,path:cfg.path||null,query:null,cb:null,ref:null,supRef:null,supCb:null,limit:CM.pageSize, sort:'new',data:[],seen:null,loaded:false,err:false,replyTo:null,replyDraft:'',draft:'',rating:0,busy:false, title:'',supporters:0,mySupport:false,emoOpen:false}; const R=th.root,site=th.kind==='site'; R.innerHTML='<div class="cm-card"><div class="section-header cm-hdr"><div><div class="section-kicker"></div><h2 class="section-title"></h2></div><div class="section-sub"></div></div>'+ '<div class="cm-stats"></div><div class="cm-compose"></div><div class="cm-bar"></div><div class="cm-list" aria-live="polite"></div><div class="cm-more"></div></div>'; const q=s=>R.querySelector(s); const ui={kicker:q('.section-kicker'),title:q('.section-title'),sub:q('.section-sub'),stats:q('.cm-stats'),compose:q('.cm-compose'),bar:q('.cm-bar'),list:q('.cm-list'),more:q('.cm-more')}; const esc=escapeHTML;
function renderHead(){ ui.kicker.textContent=cs(site?'siteKicker':'chKicker'); ui.title.textContent=site?cs('siteTitle'):(cs('chTitle')+(th.title?' · '+th.title:'')); ui.sub.textContent=cs(site?'siteSub':'chSub'); } function renderStats(){ const n=th.data.length,plus=n>=th.limit?'+':''; if(!site){ui.stats.innerHTML='<div class="cm-stat"><b>'+n+plus+'</b><span>'+esc(cs('chCount'))+'</span></div>';return} const rated=th.data.filter(c=>!c.parent&&c.rating>=1&&c.rating<=5); const avg=rated.length?(rated.reduce((a,c)=>a+c.rating,0)/rated.length).toFixed(1):'—'; ui.stats.innerHTML= '<div class="cm-stat"><b><i class="cm-star">★</i> '+avg+'</b><span>'+esc(cs('sAvg'))+'</span></div>'+ '<div class="cm-stat"><b>'+n+plus+'</b><span>'+esc(cs('sCount'))+'</span></div>'+ '<div class="cm-stat"><b>'+th.supporters+'</b><span>'+esc(cs('sFans'))+'</span></div>'+ '<button type="button" class="cm-support'+(th.mySupport?' on':'')+'" data-act="support"><span class="cm-heart">'+(th.mySupport?'💚':'🤍')+'</span> '+esc(cs(th.mySupport?'supportedSite':'supportSite'))+'</button>'; } function myAvatar(u){ const prof=(state.profile&&state.profile.uid===u.uid)?state.profile:null; const photo=(prof&&prof.photo)||u.photoURL||''; const nm=u.displayName||(prof&&prof.name)||u.email||''; return '<span class="cm-av me" data-uid="'+esc(u.uid)+'" data-name="'+esc(nm)+'"'+(cmSafeSrc(photo)?' style="background-image:url(&quot;'+esc(photo)+'&quot;)"':'')+'></span>'; } function renderCompose(){ const u=state.user; let hint=false;try{hint=!!localStorage.getItem('sg_auth_hint')}catch(_){} if(!u&&!authResolved&&hint){ui.compose.innerHTML='<div class="cm-locked cm-skel">'+esc(cs('pending'))+'</div>';return} if(!u){ ui.compose.innerHTML='<div class="cm-locked"><div class="cm-lock-ico">🔒</div><strong>'+esc(cs('lockedTitle'))+'</strong><p>'+esc(cs(site?'lockedSite':'lockedCh'))+'</p><button type="button" class="primary-btn" data-act="signin">'+esc(cs('signIn'))+'</button></div>'; return; } const stars=site?('<div class="cm-rate"><span>'+esc(cs('rate'))+'</span><span class="cm-rate-stars">'+[1,2,3,4,5].map(n=>'<button type="button" class="cm-rs'+(th.rating>=n?' on':'')+'" data-act="star" data-n="'+n+'" aria-label="'+n+'">★</button>').join('')+'</span></div>'):''; ui.compose.innerHTML='<div class="cm-composer">'+myAvatar(u)+'<div class="cm-box">'+stars+ '<textarea class="cm-ta" rows="2" maxlength="'+CM.maxLen+'" placeholder="'+esc(cs(site?'phSite':'phCh'))+'"></textarea>'+ '<div class="cm-emo" '+(th.emoOpen?'':'hidden')+'>'+CM.emojis.map(e=>'<button type="button" data-act="emopick" data-e="'+e+'">'+e+'</button>').join('')+'</div>'+ '<div class="cm-actions"><button type="button" class="cm-emo-btn" data-act="emoji" aria-label="emoji">😊</button><span class="cm-count"><span class="cm-n">0</span>/'+CM.maxLen+'</span><button type="button" class="primary-btn cm-send" data-act="send">'+esc(cs('send'))+'</button></div></div></div>'; const ta=ui.compose.querySelector('.cm-ta');ta.value=th.draft; ui.compose.querySelector('.cm-n').textContent=th.draft.length; cmPaint(ui.compose); } function renderBar(){ ui.bar.innerHTML='<button type="button" class="cm-chip'+(th.sort==='new'?' on':'')+'" data-act="sort" data-s="new">'+esc(cs('newest'))+'</button><button type="button" class="cm-chip'+(th.sort==='top'?' on':'')+'" data-act="sort" data-s="top">'+esc(cs('top'))+'</button>'; } function likesOf(c){return c.likes?Object.keys(c.likes).length:0} function itemHTML(c,isReply,orphan,inner){ const u=state.user,uid=u&&u.uid,likes=likesOf(c),liked=!!(uid&&c.likes&&c.likes[uid]); const canDel=!!uid&&(c.uid===uid||cmAdmin); const canMod=cmAdmin&&!!uid; const stars=(c.rating>=1&&c.rating<=5)?'<span class="cm-stars" aria-label="'+c.rating+'/5">'+'★'.repeat(c.rating)+'<i>'+'★'.repeat(5-c.rating)+'</i></span>':''; const isNew=th.seen&&!th.seen.has(c.id); return '<article class="cm-item'+(c.pinned&&!isReply?' is-pinned':'')+(isReply?' cm-reply':'')+(isNew?' cm-new':'')+(uid&&c.uid===uid?' mine':'')+'" data-id="'+esc(c.id)+'">'+ '<span class="cm-av" data-uid="'+esc(c.uid)+'" data-name="'+esc(c.name||'')+'"></span>'+ '<div class="cm-main"><div class="cm-meta"><strong class="cm-name">'+esc(c.name||'—')+'</strong><span class="cm-badge" data-uid="'+esc(c.uid)+'" hidden></span>'+stars+''+(c.pinned&&!isReply?'<span class="cm-pinned">'+esc(cs('pinned'))+'</span>':'')+'<time>'+esc(cmAgo(c.ts))+'</time></div>'+ (orphan?'<div class="cm-orph">↪ '+esc(cs('orphan'))+'</div>':'')+ '<div class="cm-text">'+esc(c.text)+'</div>'+ '<div class="cm-foot"><button type="button" class="cm-like'+(liked?' on':'')+'" data-act="like" data-id="'+esc(c.id)+'"><span>'+(liked?'💚':'🤍')+'</span> '+esc(cs('support'))+(likes?' <b>'+likes+'</b>':'')+'</button>'+ '<button type="button" class="cm-lnk" data-act="reply" data-id="'+esc(c.id)+'" data-top="'+esc(c.parent||c.id)+'" data-name="'+esc(c.name||'')+'">'+esc(cs('reply'))+'</button>'+ (canDel?'<button type="button" class="cm-lnk del" data-act="del" data-id="'+esc(c.id)+'">'+esc(cs('del'))+'</button>':'')+ (canMod&&!isReply?'<button type="button" class="cm-lnk" data-act="pin" data-id="'+esc(c.id)+'">'+esc(cs(c.pinned?'unpin':'pin'))+'</button>':'')+ (canMod&&c.uid!==uid?'<button type="button" class="cm-lnk ban" data-act="ban" data-id="'+esc(c.id)+'" data-uid="'+esc(c.uid)+'">'+esc(cs('ban'))+'</button>':'')+'</div>'+ (inner||'')+'</div></article>'; } function replyForm(id){ if(th.replyTo!==id||!state.user)return ''; return '<div class="cm-rform"><textarea class="cm-rta" rows="2" maxlength="'+CM.maxLen+'" placeholder="'+esc(cs('phReply'))+'"></textarea><div class="cm-ractions"><button type="button" class="primary-btn cm-send" data-act="rsend" data-id="'+esc(id)+'">'+esc(cs('send'))+'</button><button type="button" class="secondary-btn" data-act="rcancel">'+esc(cs('cancel'))+'</button></div></div>'; } function renderList(){ const L=ui.list; const ae=document.activeElement,keep=(ae&&ae.classList&&ae.classList.contains('cm-rta')&&L.contains(ae))?ae.selectionStart:null; if(!th.loaded){L.innerHTML='<div class="cm-empty">'+esc(cs('loading'))+'</div>';return} if(th.err){L.innerHTML='<div class="cm-empty bad">'+esc(cs('loadErr'))+'</div>';return} if(!th.data.length){L.innerHTML='<div class="cm-empty">'+esc(cs('empty'))+'</div>';th.seen=new Set();return} const byId_={},kids={}; th.data.forEach(c=>{byId_[c.id]=c}); const tops=[]; th.data.forEach(c=>{if(c.parent&&byId_[c.parent]){(kids[c.parent]=kids[c.parent]||[]).push(c)}else tops.push(c)}); tops.sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||(th.sort==='top'?(likesOf(b)-likesOf(a))||((b.ts||0)-(a.ts||0)):((b.ts||0)-(a.ts||0)))); const html=tops.map(c=>{ const rs=(kids[c.id]||[]).sort((a,b)=>(a.ts||0)-(b.ts||0)); const inner=(rs.length?'<div class="cm-replies">'+rs.map(r=>itemHTML(r,true,false,'')).join('')+'</div>':'')+replyForm(c.id); return itemHTML(c,false,!!c.parent,inner); }).join(''); L.innerHTML=html; cmPaint(L); th.seen=new Set(th.data.map(c=>c.id)); const rta=L.querySelector('.cm-rta'); if(rta){rta.value=th.replyDraft;if(keep!==null){try{rta.focus({preventScroll:true});rta.setSelectionRange(keep,keep)}catch(_){}}} } function renderMore(){ ui.more.innerHTML=(th.loaded&&!th.err&&th.data.length>=th.limit)?'<button type="button" class="secondary-btn" data-act="more">'+esc(cs('more'))+'</button>':''; } function renderAll(){renderHead();renderStats();renderCompose();renderBar();renderList();renderMore()}
function stop(){ if(th.query&&th.cb){try{th.query.off('value',th.cb)}catch(_){}} th.query=null;th.cb=null; if(th.supRef&&th.supCb){try{th.supRef.off('value',th.supCb)}catch(_){}} th.supRef=null;th.supCb=null; } async function start(keep){ if(!th.path)return; stop(); if(!keep){th.loaded=false;th.err=false;th.data=[];th.seen=null;renderList();renderMore();renderStats()} const path=th.path; let ready=false;try{ready=await ensureFirebaseAuthReady()}catch(_){} if(th.path!==path)return; if(!ready||!state.cloudDb){th.err=true;th.loaded=true;renderList();return} th.ref=state.cloudDb.ref(path); th.query=th.ref.orderByChild('ts').limitToLast(th.limit); th.cb=snap=>{ if(th.path!==path)return; const arr=[]; snap.forEach(ch=>{const v=ch.val();if(v&&typeof v.text==='string'&&typeof v.uid==='string'){v.id=ch.key;arr.push(v)}}); th.data=arr;th.loaded=true;th.err=false;renderStats();renderList();renderMore(); }; th.query.on('value',th.cb,()=>{th.err=true;th.loaded=true;renderList();renderMore()}); if(site){ th.supRef=state.cloudDb.ref('siteSupport'); th.supCb=s=>{th.supporters=s.numChildren();th.mySupport=!!(state.user&&s.hasChild(state.user.uid));renderStats()}; th.supRef.on('value',th.supCb,()=>{}); } } function setPath(p,title){ th.path=p;th.title=title||'';th.limit=CM.pageSize;th.replyTo=null;th.replyDraft='';th.draft='';th.rating=0;th.emoOpen=false; renderHead();renderCompose(); if(p)start();else{stop();th.data=[];th.loaded=false;renderList();renderMore()} }
async function submit(text,parent){ const u=state.user; if(!u){showToast(cs('signInFirst'));cmOpenAccount();return false} text=String(text||'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim(); if(!text){showToast(cs('emptyText'));return false} if(/(https?:\/\/|www\.)/i.test(text)){showToast(cs('noLinks'));return false} if(Date.now()-cmLast<CM.cooldown){showToast(cs('tooFast'));return false} if(!th.path||!state.cloudDb)return false; try{ const me=await cmEnsurePublic(); const rec={uid:u.uid,name:me.name,text:text.slice(0,CM.maxLen),ts:firebase.database.ServerValue.TIMESTAMP}; if(parent)rec.parent=parent;else if(site&&th.rating>=1)rec.rating=th.rating; await state.cloudDb.ref(th.path).push().set(rec); cmLast=Date.now();return true; }catch(_){showToast(cs('postErr'));return false} }
R.addEventListener('input',e=>{ const tg=e.target; if(tg.classList.contains('cm-ta')){th.draft=tg.value;const n=ui.compose.querySelector('.cm-n');if(n)n.textContent=tg.value.length} else if(tg.classList.contains('cm-rta')){th.replyDraft=tg.value} }); R.addEventListener('keydown',e=>{ if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){ if(e.target.classList.contains('cm-ta')){e.preventDefault();const b=ui.compose.querySelector('[data-act="send"]');if(b)b.click()} else if(e.target.classList.contains('cm-rta')){e.preventDefault();const b=ui.list.querySelector('[data-act="rsend"]');if(b)b.click()} } }); R.addEventListener('click',async e=>{ const b=e.target.closest('[data-act]');if(!b||!R.contains(b))return; const act=b.dataset.act,id=b.dataset.id,u=state.user; if(act==='signin'){cmOpenAccount();return} if(act==='sort'){th.sort=b.dataset.s;renderBar();renderList();return} if(act==='more'){th.limit+=CM.pageSize;start(true);return} if(act==='emoji'){th.emoOpen=!th.emoOpen;const p=ui.compose.querySelector('.cm-emo');if(p)p.hidden=!th.emoOpen;return} if(act==='emopick'){const ta=ui.compose.querySelector('.cm-ta');if(!ta)return;const s=ta.selectionStart||ta.value.length,v=ta.value;if(v.length+b.dataset.e.length>CM.maxLen)return;ta.value=v.slice(0,s)+b.dataset.e+v.slice(ta.selectionEnd||s);th.draft=ta.value;const pos=s+b.dataset.e.length;ta.focus();try{ta.setSelectionRange(pos,pos)}catch(_){}ui.compose.querySelector('.cm-n').textContent=ta.value.length;return} if(act==='star'){const n=Number(b.dataset.n);th.rating=th.rating===n?0:n;ui.compose.querySelectorAll('.cm-rs').forEach(x=>x.classList.toggle('on',Number(x.dataset.n)<=th.rating));return} if(act==='send'){ if(th.busy)return;th.busy=true;b.disabled=true;b.textContent=cs('sending'); const ok=await submit(th.draft,null); th.busy=false; if(ok){th.draft='';th.rating=0;th.emoOpen=false} renderCompose();return; } if(act==='reply'){ if(!u){showToast(cs('signInFirst'));cmOpenAccount();return} const top=b.dataset.top,nm=b.dataset.name; th.replyTo=top;th.replyDraft=(b.dataset.id!==top&&nm)?('@'+nm+' '):''; renderList(); const rta=ui.list.querySelector('.cm-rta');if(rta){rta.focus();try{rta.setSelectionRange(rta.value.length,rta.value.length)}catch(_){}} return; } if(act==='rcancel'){th.replyTo=null;th.replyDraft='';renderList();return} if(act==='rsend'){ if(th.busy)return;th.busy=true;b.disabled=true;b.textContent=cs('sending'); const ok=await submit(th.replyDraft,id); th.busy=false; if(ok){th.replyTo=null;th.replyDraft=''} renderList();return; } if(act==='like'){ if(!u){showToast(cs('signInFirst'));cmOpenAccount();return} const c=th.data.find(x=>x.id===id);if(!c||!th.ref)return; const p=th.ref.child(id+'/likes/'+u.uid); try{if(c.likes&&c.likes[u.uid])await p.remove();else await p.set(true)}catch(_){showToast(cs('actErr'))} return; } if(act==='pin'){ if(!th.ref||!cmAdmin)return; const c=th.data.find(x=>x.id===id);if(!c)return; try{if(c.pinned)await th.ref.child(id+'/pinned').remove();else await th.ref.child(id+'/pinned').set(true)}catch(_){showToast(cs('actErr'))} return; } if(act==='ban'){ if(!th.ref||!cmAdmin||!b.dataset.uid||!confirm(cs('banConfirm')))return; try{await state.cloudDb.ref('bans/'+b.dataset.uid).set(true);await th.ref.child(id).remove();showToast(cs('banned'))}catch(_){showToast(cs('actErr'))} return; } if(act==='del'){ if(!th.ref||!confirm(cs('delConfirm')))return; try{await th.ref.child(id).remove()}catch(_){showToast(cs('actErr'))} return; } if(act==='support'){ if(!u){showToast(cs('signInFirst'));cmOpenAccount();return} if(!state.cloudDb)return; const p=state.cloudDb.ref('siteSupport/'+u.uid); try{ if(th.mySupport){await p.remove();showToast(cs('unsupported'))} else{await p.set(true);cmBurst(b);showToast(cs('thanks'))} }catch(_){showToast(cs('actErr'))} return; } }); // keep relative times fresh without re-fetching setInterval(()=>{if(!document.hidden&&th.loaded&&!th.err&&th.data.length&&!ui.list.querySelector('.cm-rta:focus'))renderList()},60000); renderAll(); return {th,render