function setupComments(){ const siteRoot=byId('siteThread'),chRoot=byId('chThread'); if(!siteRoot||!chRoot||cmSite)return; cmSite=cmThread({kind:'site',root:siteRoot,path:'siteComments'}); cmChan=cmThread({kind:'channel',root:chRoot,path:null}); const sec=byId('siteComments'); const go=()=>cmSite.start(); if('IntersectionObserver' in window&&sec){ const io=new IntersectionObserver(es=>{if(es.some(x=>x.isIntersecting)){io.disconnect();go()}},{rootMargin:'700px 0px'}); io.observe(sec); }else go(); } window.SamiComments={ onChannel(key,ch){ if(!cmChan)return; const sec=byId('channelComments');if(sec)sec.hidden=false; const id=cmChId(key,ch.n),title=chLabel(ch); if(cmChan.th.path==='channelComments/'+id){cmChan.th.title=title;cmChan.renderHead();return} cmChan.setPath('channelComments/'+id,title); }, async onAuth(){ cmAdmin=false;cmPub=null; if(window.samiSetAdmin)samiSetAdmin(false); if(state.user&&state.cloudDb){ try{cmAdmin=(await state.cloudDb.ref('admins/'+state.user.uid).once('value')).val()===true}catch(_){} cmEnsurePublic().catch(()=>{}); } if(window.samiSetAdmin)samiSetAdmin(cmAdmin); if(cmSite)cmSite.renderAll(); if(cmChan)cmChan.renderAll(); }, refresh(){ if(cmSite)cmSite.renderAll(); if(cmChan){ if(state.channel&&cmChan.th.path)cmChan.th.title=chLabel(state.channel); cmChan.renderAll(); } } };
function initFromUrl(){const x=findFromUrl();if(x)playChannel(x.key,x.ch)}
function init(){ // Keep the catalogue usable when an optional feature fails to initialize. const bootStep=(name,fn)=>{try{fn()}catch(e){console.error('[SAMI V20] '+name+' failed',e)}}; bootStep('purgeLocalUserData',purgeLocalUserData); bootStep('setupWatchView',setupWatchView); bootStep('setupLang',setupLang); bootStep('initStats',initStats); bootStep('renderFilters',renderFilters); bootStep('renderGrid',renderGrid); bootStep('renderHistory',renderHistory); bootStep('setupPlayer',setupPlayer); bootStep('setupSearch',setupSearch); bootStep('setupTheme',setupTheme); bootStep('setupDialogs',setupDialogs); bootStep('setupShortcuts',setupShortcuts); bootStep('setupMobileNav',setupMobileNav); bootStep('setupNavSpy',setupNavSpy); bootStep('setupReveal',setupReveal); bootStep('setupAbout',setupAbout); bootStep('renderCommandShortcut',renderCommandShortcut); bootStep('setupPresenceHook',setupPresenceHook); bootStep('setupAccount',setupAccount); bootStep('setupComments',setupComments); bootStep('firebaseAuth',()=>{try{if(localStorage.getItem('sg_auth_hint'))ensureFirebaseAuthReady()}catch(_){}}); bootStep('scheduleBoot',scheduleBoot); window.addEventListener('resize',()=>bootStep('renderCommandShortcut',renderCommandShortcut)); bootStep('initFromUrl',initFromUrl); document.addEventListener('visibilitychange',()=>{try{if(document.hidden&&state.hls&&!document.pictureInPictureElement){state.hls.stopLoad();if(state.audHls)state.audHls.stopLoad()}if(!document.hidden&&state.hls){state.hls.startLoad();if(state.audHls)state.audHls.startLoad()}}catch(e){console.warn('[SAMI V20] visibility handler failed',e)}}); }
// ===== SAMI v10: smart features — all free, client-side, no paid API ===== const V10={}; (function(){ const L=(a,e)=>state.lang==='en'?e:a; const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches; const nc=navigator.connection||{}; const lite=!!(nc.saveData||/2g|3g/.test(nc.effectiveType||'')||(navigator.deviceMemory&&navigator.deviceMemory<=2)||(navigator.hardwareConcurrency&&navigator.hardwareConcurrency<=2)); const key2=(k,n)=>k+'::'+n;
// ---------- 1. AI Search: synonyms + typo tolerance + intent (local, free) ---------- const SYN={ 'رياضه':['رياض','sport','sports','سبورت','بين','كاس','دوري','مباريات','كوره'], 'اخبار':['news','نيوز','الجزيره','العربيه','عاجل','سكاي','اخباريه'], 'اطفال':['kids','كرتون','سبيس','بيبي','طيور','كيدز','cartoon'], 'افلام':['فيلم','movie','movies','سينما','دراما','مسلسل','مسلسلات','cinema'], 'دين':['قران','quran','اسلام','islam','مكه','المدينه','شريعه','ديني'], 'موسيقى':['اغاني','music','طرب','مزيكا','song'], 'وثائقي':['وثائق','documentary','طبيعه','discovery','ناشيونال'] }; let IDX=null,IDXL=''; function idx(){ if(IDX&&IDXL===state.lang)return IDX;IDXL=state.lang;IDX=[]; Object.entries(db).forEach(([key,cat])=>cat.c.forEach(ch=>{ const txt=normalizeArabic(ch.n+' '+chLabel(ch)+' '+cat.n+' '+catLabel(key)); IDX.push({key,cat,ch,txt,words:txt.split(' ').filter(w=>w.length>2)}); })); return IDX; } function lev(a,b,m){ if(Math.abs(a.length-b.length)>m)return m+1; const p=[];for(let j=0;j<=b.length;j++)p[j]=j; for(let i=1;i<=a.length;i++){ let prev=p[0];p[0]=i;let min=i; for(let j=1;j<=b.length;j++){const tmp=p[j];p[j]=a[i-1]===b[j-1]?prev:1+Math.min(prev,p[j],p[j-1]);prev=tmp;if(p[j]<min)min=p[j]} if(min>m)return m+1; } return p[b.length]; } searchAll=function(q){ const n=normalizeArabic(q);if(!n)return []; const toks=n.split(' ').filter(Boolean),terms=new Set(); Object.entries(SYN).forEach(([k,arr])=>{ const all=[k,...arr].map(normalizeArabic); if(toks.some(tk=>tk.length>2&&all.some(w=>w===tk||w.includes(tk)||tk.includes(w))))all.forEach(w=>terms.add(w)); }); const out=[]; idx().forEach(e=>{ let s=0; if(e.txt.includes(n))s+=10; toks.forEach(tk=>{ if(e.txt.includes(tk))s+=4; else if(tk.length>=4){const m=tk.length>=7?2:1;if(e.words.some(w=>lev(w,tk,m)<=m))s+=2} }); terms.forEach(w=>{if(w.length>2&&e.txt.includes(w))s+=1.5}); if(s>0)out.push({type:'channel',key:e.key,cat:e.cat,ch:e.ch,s}); }); Object.entries(db).forEach(([key,cat])=>{ const c=normalizeArabic(cat.n+' '+catLabe