// ---------- 5. Live status (real signals only) ---------- const ST=new Map(),pq=[];let running=0; const st=(k,n)=>{const v=ST.get(key2(k,n));return v&&Date.now()-v.t<6e5?v.s:'unk'}; function paint(k,n){ const s=st(k,n); document.querySelectorAll('[data-key="'+CSS.escape(k)+'"][data-name="'+CSS.escape(n)+'"] .st-dot').forEach(d=>{d.dataset.s=s}); } function setSt(k,n,s){ST.set(key2(k,n),{s,t:Date.now()});paint(k,n)} function pump(){ while(running<3&&pq.length){ const [k,n,u]=pq.shift();running++; const c=new AbortController(),to=setTimeout(()=>c.abort(),5000); fetch(u,{mode:'no-cors',cache:'no-store',signal:c.signal}) .then(()=>{setSt(k,n,'on');c.abort()},()=>{setSt(k,n,'off')}) .finally(()=>{clearTimeout(to);running--;pump()}); } } const io='IntersectionObserver' in window?new IntersectionObserver(es=>es.forEach(x=>{ if(!x.isIntersecting)return;io.unobserve(x.target); const e=x.target._e,u=e&&sourcesFor(e.ch)[0]; if(u&&st(e.key,e.ch.n)==='unk'&&navigator.onLine){pq.push([e.key,e.ch.n,u.u]);pump()} }),{rootMargin:'160px'}):null; const _bc=buildCard; buildCard=function(e,i){ const c=_bc(e,i),th=c.querySelector('.thumb'); if(th){ const d=document.createElement('i');d.className='st-dot';d.dataset.s=st(e.key,e.ch.n);d.title=L('حالة البث','Stream status');th.appendChild(d); if(!lite&&io){c._e=e;io.observe(c)} if(!lite&&e.ch.img)imgQ.push(e.ch.img); } return c; };
