// ===== SAMI v11: real AI assistant (Cloudflare Worker + Workers AI, free) ===== (function(){ // ▼▼ الصق هنا رابط الـ Worker بعد نشره (مثال: https://sami-ai.yourname.workers.dev) ▼▼ // إذا تُرك فارغًا يعمل المساعد في "الوضع المحلي" (بحث ذكي بدون نموذج لغوي). const AI_ENDPOINT='https://sami.alhydrys220.workers.dev/'; const DAILY_CAP=25,COOLDOWN=2500,TIMEOUT=15000; const L=(a,e)=>state.lang==='en'?e:a; const kk=(k,n)=>k+'::'+n; let panel,fab,list,input,sendBtn,badge,busy=false,lastSend=0,turns=[],opened=false;
