// ---- retrieval: only a small, relevant slice of the catalog is sent to the model ---- function gather(text){ const map=new Map(),seen=new Set(),rows=[];let n=0; const add=(key,ch)=>{ const k=kk(key,ch.n);if(seen.has(k)||n>=30)return;seen.add(k); const id='c'+(++n);map.set(id,{type:'channel',key,ch}); rows.push(id+'|'+chLabel(ch)+'|'+catLabel(key)+'|'+V10.st(key,ch.n)); }; if(state.channel&&state.category&&db[state.category])add(state.category,state.channel); searchAll(text).filter(r=>r.type==='channel').slice(0,14).forEach(r=>add(r.key,r.ch)); V10.recs(8).forEach(r=>add(r.key,r.ch)); Object.keys(getFavs()).slice(0,4).forEach(f=>{const [k,nm]=f.split('::');const c=db[k]&&db[k].c.find(x=>x.n===nm);if(c)add(k,c)}); // pad with a few channels from every category so general requests ("something for kids") have material Object.entries(db).forEach(([key,cat])=>cat.c.slice(0,2).forEach(ch=>add(key,ch))); const cats=Object.entries(db).map(([k,c])=>{map.set('k:'+k,{type:'category',key:k,cat:c});return 'k:'+k+'='+catLabel(k)}).join('; '); const cur=state.channel&&state.category?(chLabel(state.channel)+' ('+catLabel(state.category)+')'):'none'; const favs=Object.keys(getFavs()).slice(0,6).map(f=>nameLabel(f.split('::')[1])).join('; ')||'none'; const rec=getHistory().slice(0,5).map(h=>nameLabel(h.name)).join('; ')||'none'; const ctx='CATEGORIES: '+cats+'\nNOW_PLAYING: '+cur+'\nFAVORITES: '+favs+'\nRECENT: '+rec+'\nCANDIDATES (id|channel|category|status):\n'+rows.join('\n'); return {map,ctx}; }
// ---- model output is untrusted: lenient parse, then keep only ids we actually sent ---- function parse(raw,map){ let reply='',ids=[]; const s=String(raw||''); try{ const a=s.indexOf('{'),b=s.lastIndexOf('}'); if(a>=0&&b>a){const o=JSON.parse(s.slice(a,b+1));reply=String(o.reply||o.text||'');ids=Array.isArray(o.ids)?o.ids.map(String):[]} }catch(_){} if(!reply){reply=s.replace(/[{}"]/g,' ').replace(/\b(reply|ids)\s*:/g,' ').replace(/\[[^\]]*\]/g,' ').replace(/\s+/g,' ').trim()} if(!ids.length)ids=(s.match(/\bc\d+\b|k:[a-z]+/g)||[]); const seen=new Set(),acts=[]; ids.forEach(i=>{if(!seen.has(i)&&map.has(i)&&acts.length<4){seen.add(i);acts.push(map.get(i))}}); return {reply:reply.slice(0,700),acts}; }
function local(text){ const r=searchAll(text).filter(x=>x.type==='channel').slice(0,5); if(r.length)return {reply:L('أقرب النتائج لطلبك:','Closest matches:'),acts:r.map(x=>({type:'channel',key:x.key,ch:x.ch}))}; return {reply:L('لم أجد تطابقًا مباشرًا. هذه اقتراحات اليوم:','No direct match. Today\'s picks:'),acts:V10.recs(4).map(x=>({type:'channel',key:x.key,ch:x.ch}))}; }
async function askModel(text,g){ const c=new AbortController(),to=setTimeout(()=>c.abort(),TIMEOUT); try{ const r=await fetch(AI_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:state.lang==='en'?'en':'ar',message:text,context:g.ctx,history:turns.slice(-6)}),signal:c.signal}); if(!r.ok){let d='';try{d=String((await r.json()).detail||'')}catch(_){}throw new Error('http '+r.status+(d?' '+d:''))} const j=await r.json();if(!j||!j.text)throw new Error('empty'); return parse(j.text,g.map); }finally{clearTimeout(to)} }
// ---- UI ---- function bubble(role,text){ const d=document.createElement('div');d.className='ai-msg ai-'+role;d.textContent=text;list.appendChild(d);list.scrollTop=list.scrollHeight;return d; } function chips(acts,after){ if(!acts.length&&!after)return; const w=document.createElement('div');w.className='ai-chips'; acts.forEach(a=>{ const b=document.createElement('button');b.type='button';b.className='ai-chip'; const t=document.createElement('strong');t.textContent=a.type==='category'?catLabel(a.key):chLabel(a.ch); const s=document.createElement('small');s.textContent=a.type==='category'?L('فتح القسم','Open section'):catLabel(a.key); b.append(t,s); b.onclick=()=>{ close(); if(a.type==='category'){state.category=a.key;state.favoritesOnly=false;renderFilters();state.query='';els.search.value='';renderGrid();scrollToChannels()} else playChannel(a.key,a.ch); }; w.appendChild(b); }); if(after)w.appendChild(after); list.appendChild(w);list.scrollTop=list.scrollHeight; } function signInBtn(){ const b=document.createElement('button');b.type='button';b.className='ai-chip ai-signin';b.textContent=L('تسجيل الدخول لتفعيل الذكاء الاصطناعي','Sign in to enable AI'); b.onclick=()=>{close();if(els.accountBackdrop){els.accountBackdrop.classList.add('show');els.accountBackdrop.setAttribute('aria-hidden','false')}}; return b; } function setBusy(v){busy=v;sendBtn.disabled=v;panel.setAttribute('aria-busy',String(v))} function mode(){return AI_ENDPOINT&&state.user?'ai':'local'} function paintBadge(){badge.textContent=mode()==='ai'?'AI':L('محلي','Local');badge.dataset.m=mode()}
async function send(text){ text=String(text||'').trim().slice(0,300); if(!text||busy)return; const now=Date.now();if(now-lastSend<COOLDOWN){showToast(L('انتظر لحظة…','One moment…'));return} lastSend=now;input.value='';paintBadge();bubble('user',text);setBusy(true); const typing=document.createElement('div');typing.className='ai-msg ai-bot ai-typing';typing.innerHTML='<i></i><i></i><i></i>';list.appendChild(typing);list.scrollTop=list.scrollHeight; let res=null,note='',extra=null; try{ if(mode()==='ai'){ if(capLeft()<=0){note=L('وصلت للحد اليومي للمساعد، سأجيب بالبحث المحلي.','Daily AI limit reached — using local search.')} else{ try{const g=gather(text);res=await askModel(text,g);capUse()} catch(e){note=L('تعذّر الاتصال بالنموذج الآن ('+String(e&&e.message||e).slice(0,140)+') — نتائج البحث المحلي:','The model is unavailable ('+String(e&&e.message||e).slice(0,140)+') — local results:')} } }else if(AI_ENDPOINT&&!state.user){extra=signInBtn()} }finally{typing.remove()} if(!res)res=local(text); if(note)bubble('bot',note); bubble('bot',res.reply||L('تفضّل:','Here you go:')); chips(res.acts,extra); turns.push({role:'user',content:text},{role:'assistant',content:res.reply});turns=turns.slice(-8); setBusy(false);if(!/Mobi|Android/i.test(navigator.userAgent))input.focus(); }
function open(){ if(!panel)return;opened=true;panel.hidden=false;fab.setAttribute('aria-expanded','true');paintBadge(); requestAnimationFrame(()=>panel.classList.add('open')); if(!list.childElementCount){ bubble('bot',mode()==='ai'?L('أهلًا! اسألني عن القنوات: اقترح لي قناة، أو اطلب نوع محتوى، أو قل ما تريد مشاهدته.','Hi! Ask me about channels — recommendations, a type of content, or what you want to watch.') :L('أهلًا! أنا في الوضع المحلي: أبحث لك في القنوات بذكاء (مرادفات وتصحيح أخطاء).','Hi! I\'m in local mode — smart channel search (synonyms, typo tolerance).')); const w=document.createElement('div');w.className='ai-chips ai-sugg'; [[L('اقترح لي قناة رياضية','Suggest a sports channel')],[L('ماذا أشاهد الآن؟','What should I watch?')],[L('قنوات أخبار','News channels')],[L('قنوات أطفال','Kids channels')]].forEach(([q])=>{ const b=document.createElement('button');b.type='button';b.className='ai-chip ai-q';b.textContent=q;b.onclick=()=>{w.remove();send(q)};w.appendChild(b); }); list.appendChild(w); } setTimeout(()=>input.focus(),60); } function close(){ if(!panel||panel.hidden)return;panel.classList.remove('open');fab.setAttribute('aria-expanded','false'); setTimeout(()=>{if(!panel.classList.contains('open'))panel.hidden=true},200); }
function setupAI(){ fab=document.createElement('button');fab.type='button';fab.className='ai-fab';fab.setAttribute('aria-haspopup','dialog');fab.setAttribute('aria-expanded','false'); fab.setAttribute('aria-label',L('المساعد الذكي','AI assistant'));fab.title=fab.getAttribute('aria-label'); fab.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l1.9 5.6L19.5 9.5l-5.6 1.9L12 17l-1.9-5.6L4.5 9.5l5.6-1.9L12 2Zm7 11l1 2.9 2.9 1-2.9 1-1 2.9-1-2.9-2.9-1 2.9-1 1-2.9ZM5 14l.8 2.2L8 17l-2.2.8L5 20l-.8-2.2L2 17l2.2-.8L5 14Z"/></svg>'; panel=document.createElement('section');panel.className='ai-panel';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label',L('المساعد الذكي','AI assistant')); panel.innerHTML='<header class="ai-head"><strong>SAMI AI</strong><span class="ai-badge"></span><button type="button" class="ai-x" aria-label="close">×</button></header><div class="ai-list" role="log" aria-live="polite"></div><form class="ai-form"><input class="ai-input" type="text" maxlength="300" autocomplete="off" enterkeyhint="send"><button class="ai-send" type="submit"></button></form><p class="ai-foot"></p>'; document.body.append(fab,panel); list=panel.querySelector('.ai-list');input=panel.querySelector('.ai-input');sendBtn=panel.querySelector('.ai-send');badge=panel.querySelector('.ai-badge'); input.placeholder=L('اسأل عن القنوات…','Ask about channels…');input.setAttribute('aria-label',input.placeholder); sendBtn.textContent=L('إرسال','Send'); panel.querySelector('.ai-foot').textContent=L('قد يخطئ المساعد. يعتمد فقط على قائمة قنوات الموقع ولا يعرف جداول البرامج.','The assistant can be wrong. It only knows this site\'s channel list, not programme schedules.'); fab.onclick=()=>{if(panel.hidden)open();else close()}; panel.querySelector('.ai-x').onclick=close; panel.querySelector('.ai-form').onsubmit=e=>{e.preventDefault();send(input.value)}; panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();close();fab.focus()}}); paintBadge(); }
const _ci2=commandItems; commandItems=function(q){ const r=_ci2(q),n=normalizeArabic(q); const it={label:L('اسأل المساعد الذكي','Ask the AI assistant'),hint:'SAMI AI',run:()=>{setTimeout(()=>{open();if(q&&q.trim().length>2){input.value=q.trim()}},60)}}; return n&&!normalizeArabic(it.label).includes(n)&&n.length<3?r:[...r,it]; }; const _init2=init; init=function(){_init2();try{setupAI()}catch(e){console.warn('ai',e)}}; })();
window.SAMI_APP={db,playChannel,searchAll}; if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init(); })(); //

