(function(){
  var KEY='sami_mm',root=document.documentElement,btn=document.getElementById('mobileMode');
  function phoneW(){return Math.min((window.screen&&screen.width)||480,520)}
  function desktopish(){return window.innerWidth>phoneW()*1.3}
  function apply(on){
    if(on&&desktopish()){root.classList.add('mm');root.style.zoom=(window.innerWidth/phoneW()).toFixed(3)}
    else{root.classList.remove('mm');root.style.zoom=''}
    if(btn){var a=root.classList.contains('mm');btn.classList.toggle('active',a);btn.setAttribute('aria-pressed',a?'true':'false')}
  }
  function note(msg){var d=document.createElement('div');d.textContent=msg;d.style.cssText='position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#10222a;color:#fff;padding:10px 16px;border-radius:8px;font-size:13px;z-index:9999';document.body.appendChild(d);setTimeout(function(){d.remove()},1800)}
  var pref=null;try{pref=localStorage.getItem(KEY)}catch(e){}
  var small=Math.min(screen.width||9999,screen.height||9999)<=700;
  apply(pref===null?(desktopish()&&small):pref==='1');
  if(btn)btn.addEventListener('click',function(){
    var on=!root.classList.contains('mm');
    if(on&&!desktopish()){note('أنت الآن في نمط الموبايل');return}
    try{localStorage.setItem(KEY,on?'1':'0')}catch(e){}
    apply(on);
  });
})();
